import type { Identifier, RaRecord } from "ra-core";
import type { ComponentType } from "react";

import type {
  COMPANY_CREATED,
  CONTACT_CREATED,
  CONTACT_NOTE_CREATED,
  DEAL_CREATED,
  DEAL_NOTE_CREATED,
} from "./consts";

export type SignUpData = {
  email: string;
  password: string;
  first_name: string;
  last_name: string;
};

export type SalesFormData = {
  avatar?: string;
  email: string;
  password?: string;
  first_name: string;
  last_name: string;
  administrator: boolean;
  disabled: boolean;
};

export type Sale = {
  first_name: string;
  last_name: string;
  administrator: boolean;
  avatar?: RAFile;
  disabled?: boolean;
  user_id: string;

  /**
   * This is a copy of the user's email, to make it easier to handle by react admin
   * DO NOT UPDATE this field directly, it should be updated by the backend
   */
  email: string;

  /** Unipile Phase 3 — synced from edge functions, not edited in forms. */
  unipile_account_id?: string | null;
  unipile_linkedin_seat_type?: string | null;
  unipile_account_status?: string | null;
  unipile_checkpoint_type?: string | null;
  unipile_connected_at?: string | null;
  unipile_last_sync_at?: string | null;

  /**
   * This is used by the fake rest provider to store the password
   * DO NOT USE this field in your code besides the fake rest provider
   * @deprecated
   */
  password?: string;
} & Pick<RaRecord, "id">;

export type Company = {
  name: string;
  logo: RAFile;
  sector: string;
  size: 1 | 10 | 50 | 250 | 500;
  linkedin_url: string;
  website: string;
  phone_number: string;
  address: string;
  zipcode: string;
  city: string;
  state_abbr: string;
  sales_id?: Identifier;
  created_at: string;
  description: string;
  revenue: string;
  tax_identifier: string;
  country: string;
  context_links?: string[];
  nb_contacts?: number;
  nb_deals?: number;
} & Pick<RaRecord, "id">;

export type EmailAndType = {
  email: string;
  type: "Work" | "Home" | "Other";
};

export type PhoneNumberAndType = {
  number: string;
  type: "Work" | "Home" | "Other";
};

export type Contact = {
  first_name: string;
  last_name: string;
  title: string;
  company_id?: Identifier | null;
  email_jsonb: EmailAndType[];
  avatar?: Partial<RAFile>;
  linkedin_url?: string | null;
  first_seen: string;
  last_seen: string;
  has_newsletter: boolean;
  tags: number[];
  gender: string;
  sales_id?: Identifier;
  status: string;
  background: string;
  phone_jsonb: PhoneNumberAndType[];
  nb_tasks?: number;
  company_name?: string;
} & Pick<RaRecord, "id">;

export type ContactNote = {
  contact_id: Identifier;
  text: string;
  date: string;
  sales_id: Identifier;
  status: string;
  attachments?: AttachmentNote[];
} & Pick<RaRecord, "id">;

export type Deal = {
  name: string;
  company_id: Identifier;
  contact_ids: Identifier[];
  category: string;
  stage: string;
  description: string;
  amount: number;
  created_at: string;
  updated_at: string;
  archived_at?: string;
  expected_closing_date: string;
  sales_id: Identifier;
  index: number;
  // Agent H, schema 30 (2026-07-19): unguessable token backing the public,
  // unauthenticated candidate-application link (/apply/:token). Every deal
  // gets one for free via the column's DB default -- never null in
  // practice, but optional here defensively since older client-side record
  // shapes (fakerest fixtures, cached queries from before this column
  // existed) may not include it.
  public_application_token?: string;
  // Agent H, 2026-07-22 migration (agent_h_role_brief_tiers_and_clarifications):
  // ranked primary-vs-fallback candidate profile, only populated when the
  // JD genuinely described one -- see parse-job-description's header
  // comment. Null/empty for the common flat-requirement case.
  preference_tiers?: Array<{
    rank: number;
    label: string;
    keywords: string[];
    condition: string | null;
  }> | null;
  // Ambiguities parse-job-description flagged at intake time (task #30),
  // shown once as a dismissible advisory in JdIntakePage.
  clarifying_questions?: string[] | null;
  clarifying_questions_dismissed?: boolean;
  // Agent H, schema 18: discovery scroll-position cache on the role brief.
  role_brief_last_scroll_token?: string | null;
  role_brief_last_scroll_query?: string | null;
  role_brief_last_scroll_updated_at?: string | null;
  // Phase 2: Coordinator tab settings persisted to the deal row.
  coordinator_settings?: {
    knowledge_base?: string;
    calendar_link?: string;
    reply_mode?: "draft" | "auto";
  } | null;
  // Pause sourcing toggle — blocks start_sourcing / calibration_next_batch.
  // Autopilot (when added) will also check this before auto-triggering runs.
  sourcing_paused?: boolean;
  // T1/T2: taxonomy-aware sourcing intent, versioned. Stored as
  // { current: VersionedSearchIntent, history: VersionedSearchIntent[] }.
  role_brief_search_intent?: SearchIntentRecord | null;
} & Pick<RaRecord, "id">;

// ─── SearchIntent frontend types (mirrors supabase/functions/_shared/searchIntent.ts) ───

export type SearchIntentCategory =
  | "seniority"
  | "company"
  | "title"
  | "skill"
  | "experience_range"
  | "location"
  | "other";

export type SearchIntentDisposition = "require" | "exclude" | "prefer";

export type SearchIntentCondition = {
  category: SearchIntentCategory;
  disposition: SearchIntentDisposition;
  value: string;
  note?: string;
};

export type UnenforcedConstraint = {
  description: string;
  reason: string;
};

export type VersionedSearchIntent = {
  version: number;
  updated_at: string;
  conditions: SearchIntentCondition[];
  unenforceable_constraints: UnenforcedConstraint[];
};

export type SearchIntentRecord = {
  current: VersionedSearchIntent;
  history: VersionedSearchIntent[];
};

// See docs/adr/ADR-617f-phase-b-role-conversation-turns.md
export type RoleConversationTurn = {
  deal_id: Identifier;
  speaker: "recruiter" | "agent";
  actor_sales_id?: Identifier | null;
  content: string;
  in_reply_to?: Identifier | null;
  idempotency_key?: string | null;
  metadata?: Record<string, unknown>;
  created_at: string;
} & Pick<RaRecord, "id">;

export type DealNote = {
  deal_id: Identifier;
  text: string;
  date: string;
  sales_id: Identifier;
  attachments?: AttachmentNote[];

  // This is defined for compatibility with `ContactNote`
  status?: undefined;
} & Pick<RaRecord, "id">;

export type Tag = {
  id: number;
  name: string;
  color: string;
};

// Agent H Stage 3: a sourced/saved job candidate (public.candidates).
// Deliberately separate from Contact -- see 09_agent_h_candidates.sql's
// table comment for why. Enrichment fields are all nullable: null means
// "never attempted", not "attempted and empty" -- see the column comments in
// 21_agent_h_contact_and_devsignal_enrichment.sql for the full status
// vocabulary (enriched / not_found / failed).
export type Candidate = {
  first_name: string | null;
  last_name: string | null;
  current_title: string | null;
  current_company_id?: Identifier | null;
  linkedin_url: string | null;
  email_jsonb?: EmailAndType[] | null;
  phone_jsonb?: PhoneNumberAndType[] | null;
  source: string | null;
  source_id: string | null;
  status: string | null;
  contact_enrichment_status?: "enriched" | "not_found" | "failed" | null;
  contact_enrichment_source?: "hunter" | "apollo" | null;
  devsignal_enrichment_status?: "enriched" | "not_found" | "failed" | null;
  github_username?: string | null;
  github_url?: string | null;
  stackoverflow_url?: string | null;
  engaged_by_sales_id?: Identifier | null;
  engaged_since?: string | null;
  // The full search-result payload save-sourced-candidate captured at save
  // time (2026-07-22 follow-up: this was already being written on every
  // insert, just never read back anywhere -- see DealCandidatesSection's
  // "Quick view" for the fix). Vendor-shaped, not a fixed schema -- read
  // defensively (see readSourceSnapshot in DealCandidatesSection.tsx) since
  // its exact keys depend on which sourcing edge function produced this
  // candidate (free-portal/Exa/X-ray all normalize slightly differently).
  source_raw?: Record<string, unknown> | null;
  created_at: string;
  updated_at: string;
} & Pick<RaRecord, "id">;

// Agent H Stage 3: links a Candidate to a role brief (Deal) they were
// sourced for (public.deal_candidates). match_score is the Voyage rank
// score captured at save time -- see
// 23_agent_h_deal_candidates_match_score.sql -- null for candidates saved
// before that column existed, or any search that didn't score.
export type DealCandidate = {
  deal_id: Identifier;
  candidate_id: Identifier;
  sourced_via: string;
  match_score?: number | null;
  created_at: string;
  // Stage 1: Outreach (2026-07-22 migration
  // agent_h_deal_candidates_outreach_stage) -- bridges "just sourced" to
  // "actively being contacted". not_contacted (default) -> sent
  // (send-first-outreach fired) -> responded (a reply was captured via
  // resend-inbound-reply). Never auto-downgraded once set to responded.
  response_status?: "not_contacted" | "sent" | "responded";
  contacted_at?: string | null;
  responded_at?: string | null;
  reply_text?: string | null;
  // Phase 4 Unipile outreach tracking (schema 34).
  outreach_channel?: "email" | "linkedin_connection" | "linkedin_inmail" | null;
  outreach_message_body?: string | null;
  outreach_approved_at?: string | null;
  outreach_sent_at?: string | null;
  linkedin_provider_id?: string | null;
} & Pick<RaRecord, "id">;

export type Task = {
  contact_id: Identifier;
  type: string;
  text: string;
  due_date: string;
  done_date?: string | null;
  sales_id?: Identifier;
} & Pick<RaRecord, "id">;

export type ActivityCompanyCreated = {
  type: typeof COMPANY_CREATED;
  company_id: Identifier;
  company: Company;
  sales_id: Identifier;
  date: string;
} & Pick<RaRecord, "id">;

export type ActivityContactCreated = {
  type: typeof CONTACT_CREATED;
  company_id: Identifier;
  sales_id?: Identifier;
  contact: Contact;
  date: string;
} & Pick<RaRecord, "id">;

export type ActivityContactNoteCreated = {
  type: typeof CONTACT_NOTE_CREATED;
  sales_id?: Identifier;
  contactNote: ContactNote;
  date: string;
} & Pick<RaRecord, "id">;

export type ActivityDealCreated = {
  type: typeof DEAL_CREATED;
  company_id: Identifier;
  sales_id?: Identifier;
  deal: Deal;
  date: string;
};

export type ActivityDealNoteCreated = {
  type: typeof DEAL_NOTE_CREATED;
  sales_id?: Identifier;
  dealNote: DealNote;
  date: string;
};

export type Activity = RaRecord &
  (
    | ActivityCompanyCreated
    | ActivityContactCreated
    | ActivityContactNoteCreated
    | ActivityDealCreated
    | ActivityDealNoteCreated
  );

export interface RAFile {
  src: string;
  title: string;
  path?: string;
  rawFile: File;
  type?: string;
}

export type AttachmentNote = RAFile;

export interface LabeledValue {
  value: string;
  label: string;
}

export type DealStage = LabeledValue;

export interface NoteStatus extends LabeledValue {
  color: string;
}

export interface ContactGender {
  value: string;
  label: string;
  icon: ComponentType<{ className?: string }>;
}

export const COMPANY_CREATED = "company.created" as const;
export const CONTACT_CREATED = "contact.created" as const;
export const CONTACT_NOTE_CREATED = "contactNote.created" as const;
export const DEAL_CREATED = "deal.created" as const;
export const DEAL_NOTE_CREATED = "dealNote.created" as const;

// Phase 2 (2026-07-26): Outreach templates — list, create, edit, delete.
// Uses localStorage for zero-schema-change storage. Templates are scoped to
// the browser session (per-user effectively, since each recruiter uses their
// own browser). A future phase can lift these into a database table if
// multi-user sharing or admin-managed best-practices libraries are needed.
//
// Best-practices callout surfaces the top messaging tips inline so recruiters
// see them every time they open the page — no separate docs link to miss.
import { useEffect, useState } from "react";
import { FileText, Info, Pencil, Plus, Trash2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";

const STORAGE_KEY = "agent_h_outreach_templates_v1";

export type Template = {
  id: string;
  name: string;
  subject: string;
  body: string;
  channel: "email" | "linkedin" | "any";
  createdAt: string;
  updatedAt: string;
};

function loadTemplates(): Template[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    return JSON.parse(raw) as Template[];
  } catch {
    return [];
  }
}

function saveTemplates(templates: Template[]) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(templates));
  } catch {
    // ignore
  }
}

function newId() {
  return `tmpl_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
}

const CHANNEL_LABELS: Record<Template["channel"], string> = {
  email: "Email",
  linkedin: "LinkedIn",
  any: "Any channel",
};

const BEST_PRACTICES = [
  "Keep LinkedIn connection notes under 200 characters — shorter gets more accepts.",
  "Personalise the first line: mention the role, a specific skill, or recent work.",
  "One clear ask per message: a quick call, a reply, or a link — not all three.",
  "Send on Tuesday–Thursday mornings for the best open rates.",
  "Follow up once, three to five days after the first send — no more.",
];

type FormState = Omit<Template, "id" | "createdAt" | "updatedAt">;

const EMPTY_FORM: FormState = {
  name: "",
  subject: "",
  body: "",
  channel: "any",
};

export const TemplatesPage = () => {
  const [templates, setTemplates] = useState<Template[]>([]);
  const [editing, setEditing] = useState<Template | null>(null);
  const [creating, setCreating] = useState(false);
  const [form, setForm] = useState<FormState>(EMPTY_FORM);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setTemplates(loadTemplates());
  }, []);

  const openCreate = () => {
    setEditing(null);
    setForm(EMPTY_FORM);
    setError(null);
    setCreating(true);
  };

  const openEdit = (t: Template) => {
    setEditing(t);
    setForm({
      name: t.name,
      subject: t.subject,
      body: t.body,
      channel: t.channel,
    });
    setError(null);
    setCreating(false);
  };

  const closeForm = () => {
    setEditing(null);
    setCreating(false);
    setError(null);
  };

  const handleSave = () => {
    if (!form.name.trim()) {
      setError("Name is required.");
      return;
    }
    if (!form.body.trim()) {
      setError("Message body is required.");
      return;
    }
    const now = new Date().toISOString();
    if (editing) {
      const updated = templates.map((t) =>
        t.id === editing.id ? { ...t, ...form, updatedAt: now } : t,
      );
      setTemplates(updated);
      saveTemplates(updated);
    } else {
      const newTemplate: Template = {
        ...form,
        id: newId(),
        createdAt: now,
        updatedAt: now,
      };
      const updated = [newTemplate, ...templates];
      setTemplates(updated);
      saveTemplates(updated);
    }
    closeForm();
  };

  const handleDelete = (id: string) => {
    const updated = templates.filter((t) => t.id !== id);
    setTemplates(updated);
    saveTemplates(updated);
    if (editing?.id === id) closeForm();
  };

  const showForm = creating || editing !== null;

  return (
    <div className="flex flex-col gap-6 max-w-3xl mx-auto px-6 py-6">
      {/* Header */}
      <div className="flex items-start justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-xl font-semibold tracking-tight flex items-center gap-2">
            <FileText className="h-5 w-5 text-muted-foreground" />
            Outreach Templates
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            Reusable message templates for email and LinkedIn outreach. Stored
            in this browser.
          </p>
        </div>
        <Button onClick={openCreate} className="gap-2">
          <Plus className="h-4 w-4" />
          New template
        </Button>
      </div>

      {/* Best practices callout */}
      <div className="rounded-xl border bg-muted/30 p-4 flex flex-col gap-2">
        <div className="flex items-center gap-2 text-xs font-medium text-muted-foreground uppercase tracking-wide">
          <Info className="h-3.5 w-3.5" />
          Messaging best practices
        </div>
        <ul className="flex flex-col gap-1">
          {BEST_PRACTICES.map((tip, i) => (
            <li key={i} className="text-xs text-muted-foreground flex gap-2">
              <span className="shrink-0 text-muted-foreground/50">·</span>
              {tip}
            </li>
          ))}
        </ul>
      </div>

      {/* Create / Edit form */}
      {showForm && (
        <div className="rounded-xl border p-5 flex flex-col gap-4">
          <h2 className="text-base font-medium">
            {editing ? "Edit template" : "New template"}
          </h2>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="flex flex-col gap-1.5">
              <Label htmlFor="tmpl-name">Template name</Label>
              <Input
                id="tmpl-name"
                placeholder="e.g. Senior Engineer — first touch"
                value={form.name}
                onChange={(e) =>
                  setForm((f) => ({ ...f, name: e.target.value }))
                }
              />
            </div>
            <div className="flex flex-col gap-1.5">
              <Label htmlFor="tmpl-channel">Channel</Label>
              <select
                id="tmpl-channel"
                className="h-9 rounded-md border border-input bg-background px-3 text-sm text-foreground"
                value={form.channel}
                onChange={(e) =>
                  setForm((f) => ({
                    ...f,
                    channel: e.target.value as Template["channel"],
                  }))
                }
              >
                {(["any", "email", "linkedin"] as Template["channel"][]).map(
                  (ch) => (
                    <option key={ch} value={ch}>
                      {CHANNEL_LABELS[ch]}
                    </option>
                  ),
                )}
              </select>
            </div>
          </div>

          {form.channel !== "linkedin" && (
            <div className="flex flex-col gap-1.5">
              <Label htmlFor="tmpl-subject">Subject line (email)</Label>
              <Input
                id="tmpl-subject"
                placeholder="e.g. Exciting opportunity at [Company]"
                value={form.subject}
                onChange={(e) =>
                  setForm((f) => ({ ...f, subject: e.target.value }))
                }
              />
            </div>
          )}

          <div className="flex flex-col gap-1.5">
            <Label htmlFor="tmpl-body">
              Message body
              {form.channel === "linkedin" && (
                <span className="ml-2 text-xs text-muted-foreground font-normal">
                  ({form.body.length} / 300 chars for connection note)
                </span>
              )}
            </Label>
            <Textarea
              id="tmpl-body"
              placeholder="Hi {{first_name}}, I came across your profile and…"
              rows={7}
              value={form.body}
              onChange={(e) => setForm((f) => ({ ...f, body: e.target.value }))}
            />
            <p className="text-xs text-muted-foreground">
              Use {"{{first_name}}"} for personalization (substitution coming
              soon).
            </p>
          </div>

          {error && <p className="text-sm text-destructive">{error}</p>}

          <div className="flex items-center gap-3">
            <Button onClick={handleSave}>Save template</Button>
            <Button variant="outline" onClick={closeForm}>
              Cancel
            </Button>
          </div>
        </div>
      )}

      {/* Templates list */}
      {templates.length === 0 && !showForm ? (
        <div className="rounded-xl border bg-muted/20 py-12 text-center">
          <FileText className="h-8 w-8 text-muted-foreground/30 mx-auto mb-3" />
          <p className="text-sm text-muted-foreground">No templates yet.</p>
          <p className="text-xs text-muted-foreground mt-1">
            Create your first template to reuse across roles.
          </p>
          <Button
            variant="outline"
            size="sm"
            className="mt-4"
            onClick={openCreate}
          >
            Create first template
          </Button>
        </div>
      ) : (
        <div className="flex flex-col gap-3">
          {templates.map((t) => (
            <div
              key={t.id}
              className={`rounded-xl border p-4 flex flex-col gap-2 transition-colors ${
                editing?.id === t.id ? "border-foreground/20 bg-muted/20" : ""
              }`}
            >
              <div className="flex items-start justify-between gap-3">
                <div className="flex flex-col gap-0.5">
                  <span className="font-medium text-sm">{t.name}</span>
                  <span className="text-xs text-muted-foreground">
                    {CHANNEL_LABELS[t.channel]}
                    {t.subject ? ` · "${t.subject}"` : ""}
                  </span>
                </div>
                <div className="flex items-center gap-1 shrink-0">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => openEdit(t)}
                    aria-label="Edit template"
                  >
                    <Pencil className="h-3.5 w-3.5" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleDelete(t.id)}
                    aria-label="Delete template"
                    className="text-destructive hover:text-destructive"
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </Button>
                </div>
              </div>
              <p className="text-xs text-muted-foreground line-clamp-2">
                {t.body}
              </p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

TemplatesPage.path = "/templates";

import { startOfToday } from "date-fns/startOfToday";
import { endOfToday } from "date-fns/endOfToday";
import { endOfTomorrow } from "date-fns/endOfTomorrow";
import { endOfWeek } from "date-fns/endOfWeek";

import { getDay, isAfter } from "date-fns";

export const isBeforeFriday = () => getDay(new Date()) < 5; // Friday is represented by 5

type Task = {
  due_date: string;
  done_date: string | null;
};

export const isDone = (task: Task) => task.done_date != null;

// A task is recently done if it was marked as done less than 5 minutes ago
// useful to keep recently done tasks in the list to avoid flickering when a task is marked as done while the user is consulting the list of tasks. It gives a chance to the user to see that the task was marked as done and then it will disappear after 5 minutes.
export const isRecentlyDone = (task: Task) =>
  task.done_date != null &&
  isAfter(new Date(task.done_date), new Date(Date.now() - 5 * 60 * 1000));

export const isOverdue = (dateString: string) => {
  return new Date(dateString) < startOfToday();
};

export const isDueToday = (dateString: string) => {
  const dueDate = new Date(dateString);
  return dueDate >= startOfToday() && dueDate < endOfToday();
};

export const isDueTomorrow = (dateString: string) => {
  const dueDate = new Date(dateString);
  return dueDate >= endOfToday() && dueDate < endOfTomorrow();
};

export const isDueThisWeek = (dateString: string) => {
  const dueDate = new Date(dateString);
  return (
    dueDate >= endOfTomorrow() &&
    dueDate < endOfWeek(new Date(), { weekStartsOn: 0 })
  );
};

export const isDueLater = (dateString: string) => {
  const dueDate = new Date(dateString);
  return dueDate >= endOfWeek(new Date(), { weekStartsOn: 0 });
};

import {
  ListContextProvider,
  ResourceContextProvider,
  useList,
  useTranslate,
} from "ra-core";

import { TasksIterator } from "./TasksIterator";

type TaskListProps = {
  tasks: any[];
  title: string;
  showContact?: boolean;
  isMobile: boolean;
};

export const TaskListFilter = ({
  tasks,
  title,
  showContact,
  isMobile,
}: TaskListProps) => {
  const translate = useTranslate();
  const listContext = useList({
