// Agent H, sourcing sidebar (2026-07-21): browser-native speech-to-text so
// a recruiter can talk instead of typing their request. Deliberately the
// browser's own SpeechRecognition API, not a server-side transcription
// vendor -- Harsha's ask was specifically "if it's hard engineering, skip
// it," and this is a few lines with no new backend cost. Chrome/Edge
// support it natively; Safari/Firefox support is weaker, so the hook
// exposes isSupported and the caller (SourcingSidebar) hides the mic
// button entirely when unsupported rather than showing a broken control.
import { useEffect, useRef, useState } from "react";

type SpeechRecognitionLike = {
  lang: string;
  interimResults: boolean;
  continuous: boolean;
  onresult: ((event: any) => void) | null;
  onerror: ((event: any) => void) | null;
  onend: (() => void) | null;
  start: () => void;
  stop: () => void;
};

const getSpeechRecognitionCtor = (): (new () => SpeechRecognitionLike) | null => {
  if (typeof window === "undefined") return null;
  return (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition || null;
};

export const useVoiceInput = (onResult: (transcript: string) => void) => {
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
  const Ctor = getSpeechRecognitionCtor();
  const isSupported = Ctor != null;

  useEffect(() => {
    return () => {
      recognitionRef.current?.stop();
    };
  }, []);

  const toggleListening = () => {
    if (!Ctor) return;

    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
      return;
    }

    const recognition = new Ctor();
    recognition.lang = "en-US";
    recognition.interimResults = false;
    recognition.continuous = false;
    recognition.onresult = (event: any) => {
      const transcript = event.results?.[0]?.[0]?.transcript ?? "";
      if (transcript) onResult(transcript);
    };
    recognition.onerror = () => setIsListening(false);
    recognition.onend = () => setIsListening(false);

    recognitionRef.current = recognition;
    recognition.start();
    setIsListening(true);
  };

  return { isSupported, isListening, toggleListening };
};

// Agent H, sourcing sidebar (2026-07-21): the conversation logic behind
// SourcingSidebar. Extracted into its own hook so the routing between
// parseAgentCommand's actions and what happens next (existing today,
// duplicated separately in InboxPage.tsx's and CanvasPage.tsx's own
// runFreeTextCommand) has exactly one home for the sidebar experience,
// instead of a third near-copy. InboxPage's own bottom CommandBar is left
// wired to its existing runFreeTextCommand this pass -- swapping it over
// too is a follow-up once this sidebar is proven out, not bundled in here.
import { useCallback, useState } from "react";
import type { QueryClient } from "@tanstack/react-query";

import type { CrmDataProvider } from "../providers/types";
import type { Identifier } from "ra-core";
import {
  initialSourcingSteps,
  type SourcingStep,
  type ThreadItem,
} from "./sourcingThreadTypes";

const makeId = () => `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

type UseSourcingThreadArgs = {
  dataProvider: CrmDataProvider;
  queryClient: QueryClient;
  openDeals: Array<{ id: Identifier; name: string }>;
  onNavigate: (path: string) => void;
};

type SourcingThreadItem = Extract<ThreadItem, { kind: "sourcing" }>;

export const useSourcingThread = ({
  dataProvider,
  queryClient,
  openDeals,
  onNavigate,
}: UseSourcingThreadArgs) => {
  const [thread, setThread] = useState<ThreadItem[]>([]);
  const [isBusy, setIsBusy] = useState(false);

  const appendItem = (item: ThreadItem) => setThread((prev) => [...prev, item]);

  // Only ever patches a "sourcing" thread item (the one kind that changes
  // in place as its steps progress) -- typed against that variant
  // specifically rather than Partial<ThreadItem>, so a patch can't
  // silently smuggle in fields that don't belong to this item's kind.
  const patchSourcingItem = (
    id: string,
    patch: Partial<Omit<SourcingThreadItem, "kind" | "id">>,
  ) =>
    setThread((prev) =>
      prev.map((item) =>
        item.kind === "sourcing" && item.id === id
          ? { ...item, ...patch }
          : item,
      ),
    );

  const submit = useCallback(
    async (text: string) => {
      const trimmed = text.trim();
      if (!trimmed || isBusy) return;

      appendItem({ kind: "user", id: makeId(), text: trimmed });
      setIsBusy(true);

      try {
        const parsed = await dataProvider.parseAgentCommand(trimmed, {
          view: "inbox",
          open_deals: openDeals,
          current_deal_id: null,
        });

        if (parsed.action === "continue_sourcing" && parsed.deal_id != null) {
          const dealName =
            openDeals.find((d) => d.id === parsed.deal_id)?.name ?? "that role";
          const sourcingId = makeId();
          appendItem({
            kind: "sourcing",
            id: sourcingId,
            dealName,
            steps: initialSourcingSteps(),
          });

          try {
            const result = await dataProvider.continueSourcingForDeal(
              parsed.deal_id,
            );
            const doneSteps: SourcingStep[] = [
              {
                key: "parse",
                label: "Understanding your request",
                status: "done",
              },
              {
                key: "portals",
                label: "Developer & community search",
                status: "done",
              },
              { key: "exa", label: "Web search", status: "done" },
              { key: "filter", label: "Checking relevance", status: "done" },
            ];
            patchSourcingItem(sourcingId, {
              steps: doneSteps,
              result: {
                foundCount: result.foundCount,
                filteredCount: result.filteredCount,
              },
            });
          } catch (error) {
            patchSourcingItem(sourcingId, {
              error:
                error instanceof Error
                  ? error.message
                  : "Sourcing failed for this role.",
            });
          }
        } else if (
          parsed.action === "relax_criterion" &&
          parsed.criterion_id != null
        ) {
          await dataProvider.relaxLearnedCriterion(parsed.criterion_id);
          queryClient.invalidateQueries({
            queryKey: ["inbox_per_deal_signals"],
          });
          appendItem({
            kind: "assistant",
            id: makeId(),
            text: parsed.explanation,
            tone: "success",
          });
        } else if (
          parsed.action === "show_candidates" &&
          parsed.deal_id != null
        ) {
          appendItem({
            kind: "assistant",
            id: makeId(),
            text: parsed.explanation,
            tone: "success",
          });
          onNavigate(`/canvas/${parsed.deal_id}`);
        } else if (parsed.action === "show_roles") {
          appendItem({
            kind: "assistant",
            id: makeId(),
            text: parsed.explanation,
            tone: "success",
          });
          onNavigate("/deals");
        } else {
          appendItem({
            kind: "assistant",
            id: makeId(),
            text: parsed.explanation,
            tone: "info",
          });
        }
      } catch (error) {
        appendItem({
          kind: "assistant",
          id: makeId(),
          text:
            error instanceof Error
              ? error.message
              : "Something went wrong running that.",
          tone: "error",
        });
      } finally {
        setIsBusy(false);
      }
    },
    [dataProvider, queryClient, openDeals, onNavigate, isBusy],
  );

  return { thread, submit, isBusy };
};

import { useState } from "react";

export const DISPLAY_PAGE_SIZE = 25;

export function useSourcingPagination() {
  const [visibleCount, setVisibleCount] = useState(DISPLAY_PAGE_SIZE);

  const showMore = (totalCandidates: number) =>
    setVisibleCount((n) => Math.min(n + DISPLAY_PAGE_SIZE, totalCandidates));

  const reset = () => setVisibleCount(DISPLAY_PAGE_SIZE);

  return { visibleCount, showMore, reset };
}

import type { CrmDataProvider } from "../providers/types";
import {
  type OutreachPrepared,
  type PdlCandidate,
  type SaveState,
} from "./sourcingTypes";

type SetState<T> = React.Dispatch<React.SetStateAction<T>>;
type NotifyFn = (msg: string, opts: { type: string }) => void;

export type OutreachActionsDeps = {
  dataProvider: CrmDataProvider;
  notify: NotifyFn;
  selectedId: string;
  candidates: PdlCandidate[];
  bulkSelected: Set<string>;
  candidateDbIds: Record<string, number>;
  outreachPrepared: Record<string, OutreachPrepared>;
  onCandidateSaved?: (candidateId: number, name: string) => void;
  setOutreachStates: SetState<Record<string, any>>;
  setOutreachPrepared: SetState<Record<string, OutreachPrepared>>;
  setOutreachSendStates: SetState<Record<string, any>>;
  setSaveStates: SetState<Record<string, SaveState>>;
  setCandidateDbIds: SetState<Record<string, number>>;
  setBulkPreparing: SetState<boolean>;
  setBulkQueue: SetState<
    Array<{ candidateKey: string; prepared: OutreachPrepared }>
  >;
  setBulkQueueIdx: SetState<number>;
  setBulkSelected: SetState<Set<string>>;
};

export function createOutreachActionHandlers(d: OutreachActionsDeps) {
  const handlePrepareOutreach = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    if (!candidateId || !d.selectedId) return;
    d.setOutreachStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    try {
      const result = await d.dataProvider.prepareFirstOutreach(
        candidateId,
        Number(d.selectedId),
      );
      d.setOutreachPrepared((prev) => ({
        ...prev,
        [candidate.id]: result as OutreachPrepared,
      }));
      d.setOutreachStates((prev) => ({ ...prev, [candidate.id]: "done" }));
      d.notify("Review the outreach message before sending", { type: "info" });
    } catch (error: any) {
      d.setOutreachStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to prepare outreach", {
        type: "error",
      });
    }
  };

  // Save-then-prepare in one shot so action bar outreach works before
  // the recruiter manually clicks "Add to pipeline".
  const handleOutreachFromSearch = async (candidate: PdlCandidate) => {
    if (!d.selectedId) return;
    let cId = d.candidateDbIds[candidate.id];
    if (!cId) {
      d.setSaveStates((prev) => ({ ...prev, [candidate.id]: "saving" }));
      try {
        const outcome = await d.dataProvider.saveSourcedCandidate(
          Number(d.selectedId),
          candidate,
        );
        if (outcome.candidate_id) {
          cId = outcome.candidate_id;
          d.setCandidateDbIds((prev) => ({ ...prev, [candidate.id]: cId! }));
          d.setSaveStates((prev) => ({ ...prev, [candidate.id]: "saved" }));
          if (d.onCandidateSaved) {
            const name =
              candidate.full_name || `Candidate #${outcome.candidate_id}`;
            d.onCandidateSaved(outcome.candidate_id, name);
          }
        }
      } catch (error: any) {
        d.setSaveStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
        d.notify(error?.message || "Failed to save candidate", {
          type: "error",
        });
        return;
      }
    }
    if (!cId) return;
    d.setOutreachStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    try {
      const result = await d.dataProvider.prepareFirstOutreach(
        cId,
        Number(d.selectedId),
      );
      d.setOutreachPrepared((prev) => ({
        ...prev,
        [candidate.id]: result as OutreachPrepared,
      }));
      d.setOutreachStates((prev) => ({ ...prev, [candidate.id]: "done" }));
      d.notify("Review the outreach message before sending", { type: "info" });
    } catch (error: any) {
      d.setOutreachStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to prepare outreach", {
        type: "error",
      });
    }
  };

  const handleConfirmSendOutreach = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    const prepared = d.outreachPrepared[candidate.id];
    if (!candidateId || !d.selectedId || !prepared) return;
    d.setOutreachSendStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    try {
      const isDualChannel =
        prepared.dual_channel &&
        prepared.send_email_too &&
        prepared.email_preview;
      await d.dataProvider.sendFirstOutreach(
        candidateId,
        Number(d.selectedId),
        {
          channel: prepared.channel,
          message_body: prepared.message_body ?? undefined,
          linkedin_provider_id: prepared.linkedin_provider_id ?? undefined,
          subject:
            prepared.channel === "email"
              ? prepared.email_preview?.subject
              : undefined,
          html:
            prepared.channel === "email"
              ? prepared.email_preview?.html
              : undefined,
          also_send_email: isDualChannel ? true : undefined,
          email_to: isDualChannel ? prepared.email_preview?.to : undefined,
          email_subject: isDualChannel
            ? prepared.email_preview?.subject
            : undefined,
          email_html: isDualChannel ? prepared.email_preview?.html : undefined,
        },
      );
      d.setOutreachSendStates((prev) => ({ ...prev, [candidate.id]: "done" }));
      d.setOutreachPrepared((prev) => {
        const next = { ...prev };
        delete next[candidate.id];
        return next;
      });
      d.notify(
        isDualChannel ? "Outreach sent via LinkedIn + email" : "Outreach sent",
        {
          type: "success",
        },
      );
    } catch (error: any) {
      d.setOutreachSendStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to send outreach", { type: "error" });
    }
  };

  const handleBulkPrepareOutreach = async () => {
    if (!d.selectedId || d.bulkSelected.size === 0) return;
    d.setBulkPreparing(true);
    const selected = d.candidates.filter((c) => d.bulkSelected.has(c.id));
    const queue: Array<{ candidateKey: string; prepared: OutreachPrepared }> =
      [];
    for (const candidate of selected) {
      let cId = d.candidateDbIds[candidate.id];
      if (!cId) {
        try {
          const outcome = await d.dataProvider.saveSourcedCandidate(
            Number(d.selectedId),
            candidate,
          );
          if (outcome.candidate_id) {
            cId = outcome.candidate_id;
            d.setCandidateDbIds((prev) => ({ ...prev, [candidate.id]: cId! }));
            d.setSaveStates((prev) => ({ ...prev, [candidate.id]: "saved" }));
          }
        } catch {
          continue;
        }
      }
      if (!cId) continue;
      try {
        const result = await d.dataProvider.prepareFirstOutreach(
          cId,
          Number(d.selectedId),
        );
        queue.push({
          candidateKey: candidate.id,
          prepared: result as OutreachPrepared,
        });
        d.setOutreachPrepared((prev) => ({
          ...prev,
          [candidate.id]: result as OutreachPrepared,
        }));
      } catch {
        // skip
      }
    }
    d.setBulkQueue(queue);
    d.setBulkQueueIdx(0);
    d.setBulkPreparing(false);
    d.setBulkSelected(new Set());
    if (queue.length > 0) {
      d.notify(
        `${queue.length} outreach draft(s) ready — review each before sending`,
        { type: "info" },
      );
    }
  };

  return {
    handlePrepareOutreach,
    handleOutreachFromSearch,
    handleConfirmSendOutreach,
    handleBulkPrepareOutreach,
  };
}

import type { CrmDataProvider } from "../providers/types";
import {
  EMPTY_OFFER_DRAFT,
  INTERVIEW_STATUS_LABELS,
  OFFER_STATUS_LABELS,
  RESUME_STATUS_LABELS,
  type EmailPreview,
  type InterviewResult,
  type OfferDraft,
  type OfferInfo,
  type PdlCandidate,
  type ResumeInfo,
} from "./sourcingTypes";

type SetState<T> = React.Dispatch<React.SetStateAction<T>>;
type NotifyFn = (msg: string, opts: { type: string }) => void;

export type InterviewResumeOfferDeps = {
  dataProvider: CrmDataProvider;
  notify: NotifyFn;
  selectedId: string;
  candidateDbIds: Record<string, number>;
  bookingPrepared: Record<
    string,
    { booking_link_url: string; email_preview: EmailPreview | null }
  >;
  resumeEmailPreviews: Record<string, EmailPreview>;
  resumeInfos: Record<string, ResumeInfo>;
  offerDrafts: Record<string, OfferDraft>;
  offerEmailPreviews: Record<string, EmailPreview>;
  offerInfos: Record<string, OfferInfo>;
  setInterviewStates: SetState<Record<string, any>>;
  setInterviewResults: SetState<Record<string, InterviewResult>>;
  setBookingPrepared: SetState<
    Record<
      string,
      { booking_link_url: string; email_preview: EmailPreview | null }
    >
  >;
  setBookingSendStates: SetState<Record<string, any>>;
  setResumeStates: SetState<Record<string, any>>;
  setResumeEmailPreviews: SetState<Record<string, EmailPreview>>;
  setResumeInfos: SetState<Record<string, ResumeInfo>>;
  setResumeSendStates: SetState<Record<string, any>>;
  setOfferStates: SetState<Record<string, any>>;
  setOfferInfos: SetState<Record<string, OfferInfo>>;
  setOfferFormOpen: SetState<Record<string, boolean>>;
  setOfferDrafts: SetState<Record<string, OfferDraft>>;
  setOfferEmailPreviews: SetState<Record<string, EmailPreview>>;
  setOfferSendStates: SetState<Record<string, any>>;
};

export function createInterviewResumeOfferHandlers(
  d: InterviewResumeOfferDeps,
) {
  // ---- Interview / booking link ----

  const handlePrepareBookingLink = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    if (!candidateId || !d.selectedId) return;
    d.setInterviewStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    d.setBookingPrepared((prev) => {
      const next = { ...prev };
      delete next[candidate.id];
      return next;
    });
    try {
      const result = (await d.dataProvider.prepareBookingLink(
        candidateId,
        Number(d.selectedId),
      )) as InterviewResult;
      if (result.already_booked) {
        d.setInterviewResults((prev) => ({ ...prev, [candidate.id]: result }));
        d.notify(INTERVIEW_STATUS_LABELS[result.status!], { type: "info" });
      } else if (result.prepared && result.booking_link_url) {
        d.setInterviewResults((prev) => ({
          ...prev,
          [candidate.id]: {
            already_booked: false,
            prepared: true,
            booking_link_url: result.booking_link_url,
            candidate_email: result.candidate_email,
            email_sent: false,
          },
        }));
        d.setBookingPrepared((prev) => ({
          ...prev,
          [candidate.id]: {
            booking_link_url: result.booking_link_url!,
            email_preview: result.email_preview ?? null,
          },
        }));
        d.notify(
          result.email_preview
            ? "Review the booking email below before sending"
            : "Review the booking link below before saving",
          { type: "info" },
        );
      }
      d.setInterviewStates((prev) => ({ ...prev, [candidate.id]: "done" }));
    } catch (error: any) {
      d.setInterviewStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to prepare booking link", {
        type: "error",
      });
    }
  };

  const handleConfirmSendBookingLink = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    const prepared = d.bookingPrepared[candidate.id];
    if (!candidateId || !d.selectedId || !prepared) return;
    d.setBookingSendStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    try {
      const preview = prepared.email_preview;
      const result = (await d.dataProvider.sendBookingLink(
        candidateId,
        Number(d.selectedId),
        {
          booking_link_url: prepared.booking_link_url,
          subject: preview?.subject,
          html: preview?.html,
        },
      )) as InterviewResult;
      d.setInterviewResults((prev) => ({ ...prev, [candidate.id]: result }));
      d.setBookingPrepared((prev) => {
        const next = { ...prev };
        delete next[candidate.id];
        return next;
      });
      d.notify(
        result.email_sent
          ? "Booking link saved and emailed to the candidate"
          : "Booking link saved — share it with the candidate manually",
        { type: "success" },
      );
      d.setBookingSendStates((prev) => ({ ...prev, [candidate.id]: "done" }));
    } catch (error: any) {
      d.setBookingSendStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to send booking link", {
        type: "error",
      });
    }
  };

  const handleCancelBookingPrepared = (candidateId: string) => {
    d.setBookingPrepared((prev) => {
      const next = { ...prev };
      delete next[candidateId];
      return next;
    });
    d.setInterviewResults((prev) => {
      const next = { ...prev };
      delete next[candidateId];
      return next;
    });
  };

  // ---- Resume ----

  const handlePrepareResumeRequest = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    if (!candidateId || !d.selectedId) return;
    d.setResumeStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    d.setResumeEmailPreviews((prev) => {
      const next = { ...prev };
      delete next[candidate.id];
      return next;
    });
    try {
      const result = await d.dataProvider.prepareRequestResume(
        candidateId,
        Number(d.selectedId),
      );
      d.setResumeEmailPreviews((prev) => ({
        ...prev,
        [candidate.id]: result.email_preview as EmailPreview,
      }));
      d.setResumeStates((prev) => ({ ...prev, [candidate.id]: "done" }));
      d.notify("Review the resume request email below before sending", {
        type: "info",
      });
    } catch (error: any) {
      d.setResumeStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to prepare resume request", {
        type: "error",
      });
    }
  };

  const handleConfirmSendResumeRequest = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    const preview = d.resumeEmailPreviews[candidate.id];
    if (!candidateId || !d.selectedId || !preview) return;
    d.setResumeSendStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    try {
      const result = await d.dataProvider.requestCandidateResume(
        candidateId,
        Number(d.selectedId),
        { subject: preview.subject, html: preview.html },
      );
      d.setResumeSendStates((prev) => ({ ...prev, [candidate.id]: "done" }));
      d.setResumeEmailPreviews((prev) => {
        const next = { ...prev };
        delete next[candidate.id];
        return next;
      });
      d.notify(
        result.resume_status === "received"
          ? "Already have a resume on file -- sent another request anyway"
          : "Resume request sent",
        { type: "success" },
      );
      const current = d.resumeInfos[candidate.id];
      d.setResumeInfos((prev) => ({
        ...prev,
        [candidate.id]: {
          resume_status: result.resume_status,
          resume_original_filename: current?.resume_original_filename ?? null,
          resume_received_at: current?.resume_received_at ?? null,
          resume_reply_text: current?.resume_reply_text ?? null,
        },
      }));
    } catch (error: any) {
      d.setResumeSendStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to send resume request", {
        type: "error",
      });
    }
  };

  const handleCancelResumePreview = (candidateId: string) => {
    d.setResumeEmailPreviews((prev) => {
      const next = { ...prev };
      delete next[candidateId];
      return next;
    });
  };

  const handleCheckForResume = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    if (!candidateId) return;
    d.setResumeStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    try {
      const info = (await d.dataProvider.getCandidateResumeInfo(
        candidateId,
      )) as ResumeInfo;
      d.setResumeInfos((prev) => ({ ...prev, [candidate.id]: info }));
      d.setResumeStates((prev) => ({ ...prev, [candidate.id]: "done" }));
      d.notify(RESUME_STATUS_LABELS[info.resume_status], {
        type: info.resume_status === "received" ? "success" : "info",
      });
    } catch (error: any) {
      d.setResumeStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to check resume status", {
        type: "error",
      });
    }
  };

  // ---- Offer ----

  const handleToggleOfferForm = (candidate: PdlCandidate) => {
    d.setOfferFormOpen((prev) => ({
      ...prev,
      [candidate.id]: !prev[candidate.id],
    }));
    d.setOfferDrafts((prev) => ({
      ...prev,
      [candidate.id]: prev[candidate.id] ?? { ...EMPTY_OFFER_DRAFT },
    }));
  };

  const handleOfferDraftChange = (
    candidateKey: string,
    field: keyof OfferDraft,
    value: string,
  ) => {
    d.setOfferDrafts((prev) => ({
      ...prev,
      [candidateKey]: {
        ...(prev[candidateKey] ?? EMPTY_OFFER_DRAFT),
        [field]: value,
      },
    }));
  };

  const handlePrepareOffer = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    const draft = d.offerDrafts[candidate.id];
    if (!candidateId || !d.selectedId || !draft) return;
    d.setOfferStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    d.setOfferEmailPreviews((prev) => {
      const next = { ...prev };
      delete next[candidate.id];
      return next;
    });
    try {
      const result = await d.dataProvider.prepareOffer(
        candidateId,
        Number(d.selectedId),
        {
          position_title: draft.position_title,
          compensation_amount: draft.compensation_amount
            ? Number(draft.compensation_amount)
            : null,
          compensation_currency: draft.compensation_currency,
          compensation_frequency: draft.compensation_frequency,
          start_date: draft.start_date || null,
          expiry_date: draft.expiry_date || null,
          benefits_summary: draft.benefits_summary || null,
        },
      );
      d.setOfferInfos((prev) => ({
        ...prev,
        [candidate.id]: result.offer as OfferInfo,
      }));
      d.setOfferEmailPreviews((prev) => ({
        ...prev,
        [candidate.id]: result.email_preview as EmailPreview,
      }));
      d.setOfferStates((prev) => ({ ...prev, [candidate.id]: "done" }));
      d.notify("Review the offer email below before sending", { type: "info" });
    } catch (error: any) {
      d.setOfferStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to prepare offer", { type: "error" });
    }
  };

  const handleConfirmSendOffer = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    const preview = d.offerEmailPreviews[candidate.id];
    if (!candidateId || !d.selectedId || !preview) return;
    d.setOfferSendStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    try {
      const result = await d.dataProvider.sendOffer(
        candidateId,
        Number(d.selectedId),
        {
          subject: preview.subject,
          html: preview.html,
        },
      );
      d.setOfferInfos((prev) => ({
        ...prev,
        [candidate.id]: result.offer as OfferInfo,
      }));
      d.setOfferEmailPreviews((prev) => {
        const next = { ...prev };
        delete next[candidate.id];
        return next;
      });
      d.setOfferStates((prev) => ({ ...prev, [candidate.id]: "done" }));
      d.setOfferFormOpen((prev) => ({ ...prev, [candidate.id]: false }));
      d.notify("Offer sent", { type: "success" });
    } catch (error: any) {
      d.setOfferSendStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to send offer", { type: "error" });
    }
  };

  const handleCancelOfferPreview = (candidateId: string) => {
    d.setOfferEmailPreviews((prev) => {
      const next = { ...prev };
      delete next[candidateId];
      return next;
    });
  };

  const handleCheckOffer = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    if (!candidateId || !d.selectedId) return;
    d.setOfferStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    try {
      const info = (await d.dataProvider.getCandidateOffer(
        candidateId,
        Number(d.selectedId),
      )) as OfferInfo | null;
      if (info) {
        d.setOfferInfos((prev) => ({ ...prev, [candidate.id]: info }));
        d.notify(OFFER_STATUS_LABELS[info.status], {
          type: info.status === "accepted" ? "success" : "info",
        });
      }
      d.setOfferStates((prev) => ({ ...prev, [candidate.id]: "done" }));
    } catch (error: any) {
      d.setOfferStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to check offer status", {
        type: "error",
      });
    }
  };

  const handleMarkOfferStatus = async (
    candidate: PdlCandidate,
    status: "accepted" | "declined" | "negotiating",
  ) => {
    const info = d.offerInfos[candidate.id];
    if (!info) return;
    try {
      await d.dataProvider.updateOfferStatus(info.id, status);
      d.setOfferInfos((prev) => ({
        ...prev,
        [candidate.id]: { ...info, status },
      }));
      d.notify(OFFER_STATUS_LABELS[status], { type: "success" });
    } catch (error: any) {
      d.notify(error?.message || "Failed to update offer status", {
        type: "error",
      });
    }
  };

  return {
    handlePrepareBookingLink,
    handleConfirmSendBookingLink,
    handleCancelBookingPrepared,
    handlePrepareResumeRequest,
    handleConfirmSendResumeRequest,
    handleCancelResumePreview,
    handleCheckForResume,
    handleToggleOfferForm,
    handleOfferDraftChange,
    handlePrepareOffer,
    handleConfirmSendOffer,
    handleCancelOfferPreview,
    handleCheckOffer,
    handleMarkOfferStatus,
  };
}

import type { CrmDataProvider } from "../providers/types";
import { mergeCandidatesAcrossSources } from "./mergeCandidates";
import type {
  ExaResult,
  FreePortalResult,
  PdlCandidate,
} from "./sourcingTypes";

type SetState<T> = React.Dispatch<React.SetStateAction<T>>;
type NotifyFn = (msg: string, opts: { type: string }) => void;

export type FreePortalSearchDeps = {
  dataProvider: CrmDataProvider;
  notify: NotifyFn;
  selectedId: string;
  freePortalCandidates: PdlCandidate[];
  freePortalNotes: string[];
  setFreePortalLoading: SetState<boolean>;
  setFreePortalCandidates: SetState<PdlCandidate[]>;
  setFreePortalNotes: SetState<string[]>;
  setFreePortalSearched: SetState<boolean>;
  setXrayLoading: SetState<boolean>;
  setCandidateDbIds: SetState<Record<string, number>>;
};

// Free-portal sourcing is permanently retired (product decision; Crustdata is the
// sole sourcing vendor). Keep false — not a temporary flag.
const FREE_PORTALS_ENABLED = false;

export function createFreePortalAndXrayHandlers(d: FreePortalSearchDeps) {
  const handleSearchFreePortals = async () => {
    if (!FREE_PORTALS_ENABLED) {
      d.notify("Free portal sourcing is not available.", {
        type: "info",
      });
      return;
    }
    if (!d.selectedId) return;
    d.setFreePortalLoading(true);
    try {
      const [freePortalOutcome, exaOutcome] = await Promise.allSettled([
        d.dataProvider.sourceFreePortalCandidates(
          Number(d.selectedId),
          10,
        ) as Promise<FreePortalResult>,
        d.dataProvider.sourceExaCandidates(
          Number(d.selectedId),
          10,
        ) as Promise<ExaResult>,
      ]);
      const freePortalCandidatesRaw =
        freePortalOutcome.status === "fulfilled"
          ? (freePortalOutcome.value.candidates ?? [])
          : [];
      const exaCandidatesRaw =
        exaOutcome.status === "fulfilled"
          ? (exaOutcome.value.candidates ?? [])
          : [];
      const combinedNotes: string[] = [];
      if (freePortalOutcome.status === "fulfilled") {
        combinedNotes.push(...(freePortalOutcome.value.notes ?? []));
      } else {
        combinedNotes.push(
          `Free portals: search failed this time (non-fatal). ${(freePortalOutcome as any).reason?.message ?? ""}`,
        );
      }
      if (exaOutcome.status === "fulfilled") {
        combinedNotes.push(...(exaOutcome.value.notes ?? []));
      } else {
        combinedNotes.push(
          `Exa: search failed this time (non-fatal). ${(exaOutcome as any).reason?.message ?? ""}`,
        );
      }
      const { merged, mergedAwayCount } =
        mergeCandidatesAcrossSources<PdlCandidate>([
          freePortalCandidatesRaw,
          exaCandidatesRaw,
        ]);
      if (mergedAwayCount > 0) {
        combinedNotes.push(
          `${mergedAwayCount} candidate(s) appeared in more than one source and were merged.`,
        );
      }
      d.setFreePortalCandidates(merged);
      d.setFreePortalNotes(combinedNotes);
      d.setFreePortalSearched(true);
      const seededDbIds: Record<string, number> = {};
      merged.forEach((c) => {
        if (c._already_saved && c._candidate_id)
          seededDbIds[c.id] = c._candidate_id;
      });
      d.setCandidateDbIds((prev) => ({ ...prev, ...seededDbIds }));
    } catch (error: any) {
      d.notify(error?.message || "Failed to search free & low-cost portals", {
        type: "error",
      });
    } finally {
      d.setFreePortalLoading(false);
    }
  };

  const handleSearchXray = async () => {
    if (!d.selectedId) return;
    d.setXrayLoading(true);
    try {
      const result = (await d.dataProvider.sourceXrayCandidates(
        Number(d.selectedId),
      )) as FreePortalResult;
      const combinedNotes = [...d.freePortalNotes, ...(result.notes ?? [])];
      const { merged, mergedAwayCount } =
        mergeCandidatesAcrossSources<PdlCandidate>([
          d.freePortalCandidates,
          result.candidates ?? [],
        ]);
      if (mergedAwayCount > 0) {
        combinedNotes.push(
          `${mergedAwayCount} candidate(s) from X-ray merged with existing results.`,
        );
      }
      d.setFreePortalCandidates(merged);
      d.setFreePortalNotes(combinedNotes);
      d.setFreePortalSearched(true);
      const seededDbIds: Record<string, number> = {};
      merged.forEach((c) => {
        if (c._already_saved && c._candidate_id)
          seededDbIds[c.id] = c._candidate_id;
      });
      d.setCandidateDbIds((prev) => ({ ...prev, ...seededDbIds }));
    } catch (error: any) {
      d.notify(error?.message || "Failed to run X-ray search", {
        type: "error",
      });
    } finally {
      d.setXrayLoading(false);
    }
  };

  return { handleSearchFreePortals, handleSearchXray };
}

import type { CrmDataProvider } from "../providers/types";
import { loadSourcingSnapshot } from "./sourcingSessionSnapshot";
import {
  sortCandidatesForDisplay,
  type CandidateSortField,
  type ContextualizeResult,
  type CriteriaImpact,
  type MustHaveCheck,
  type PdlCandidate,
  type RoleBriefDetail,
  type RoleBriefOption,
