export type DiscoverySearchDeps = {
  dataProvider: CrmDataProvider;
  notify: NotifyFn;
  selectedId: string;
  size: number;
  sortField: CandidateSortField;
  sortByMatchEvidence: boolean;
  sortByYearsExperience: boolean;
  sortByCompanySize: boolean;
