  setNlText: SetState<string>;
  setNlParsing: SetState<boolean>;
  setRoleBriefs: SetState<RoleBriefOption[]>;
  setEvidenceExpanded: SetState<Record<string, boolean>>;
  setEvidenceStates: SetState<Record<string, any>>;
  setEvidenceResults: SetState<Record<string, MustHaveCheck[]>>;
  setCalibrationLoading: SetState<boolean>;
  setCalibrationStarted: SetState<boolean>;
  setCalibrationCandidates: SetState<PdlCandidate[]>;
  setCriteriaImpact: SetState<CriteriaImpact | null>;
  setCriteriaImpactLoading: SetState<boolean>;
  setCriteriaActionStates: SetState<Record<number, "idle" | "working">>;
  setSteeringText: SetState<string>;
  setSteeringState: SetState<"idle" | "loading" | "done">;
  setSteeringResult: SetState<ContextualizeResult | null>;
  setSteeringApplyState: SetState<"idle" | "applying" | "applied">;
  setRoleBriefDetail: SetState<RoleBriefDetail | null>;
  roleBriefDetail: RoleBriefDetail | null;
  // helpers from main hook
  resetSearchUiState: () => void;
  loadRoleBriefContext: (id: string) => void;
  applySourcingSnapshot: (snap: any, source: "session" | "server") => void;
};

export function createDiscoverySearchHandlers(d: DiscoverySearchDeps) {
  // Fire-and-forget: rank candidates with LLM and annotate top 25 with _llm_rank + _llm_why_fit.
  // Updates candidates state in place; does not block the fetch flow.
  const applyLlmRanks = async (candidates: PdlCandidate[]) => {
    if (candidates.length === 0) return;
    try {
      const summaries = candidates.map((c) => ({
        id: c.id,
        full_name: c.full_name ?? null,
        job_title: c.job_title ?? null,
        job_company_name: c.job_company_name ?? null,
        location_name: c.location_name ?? null,
        skills: c.skills ?? null,
        years_experience: c.years_experience ?? null,
      }));
      const ranked = await d.dataProvider.rankDiscoveryBatch(
        summaries,
        (d.roleBriefDetail ?? {}) as Record<string, unknown>,
      );
      if (!ranked.length) return;
      const byId = new Map(ranked.map((r) => [r.id, r]));
      d.setCandidates((prev) => {
        const updated = prev.map((c) => {
          const r = byId.get(c.id);
          return r ? { ...c, _llm_rank: r.rank, _llm_why_fit: r.why_fit } : c;
        });
        // Re-sort: ranked top-25 first (by llm_rank), then unranked (by existing score)
        const ranked25 = updated
          .filter((c) => c._llm_rank != null)
          .sort((a, b) => (a._llm_rank ?? 99) - (b._llm_rank ?? 99));
        const rest = updated.filter((c) => c._llm_rank == null);
        return [...ranked25, ...rest];
      });
    } catch {
      // Non-fatal — ranking failure never breaks the main flow
    }
  };

  const handleDiscoveryEvidence = async (candidate: PdlCandidate) => {
    if (!d.selectedId) return;
    d.setEvidenceStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    try {
      const result = await d.dataProvider.scoreDiscoveryEvidence(
        Number(d.selectedId),
        candidate as Record<string, unknown>,
      );
      d.setEvidenceResults((prev) => ({
        ...prev,
        [candidate.id]: result.must_haves_check ?? [],
      }));
      d.setEvidenceStates((prev) => ({ ...prev, [candidate.id]: "done" }));
    } catch (error: any) {
      d.setEvidenceStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to load match evidence", {
        type: "error",
      });
    }
  };

  const CRITERIA_IMPACT_DISABLED = false;
  const handleRefreshCriteriaImpact = async () => {
    if (!d.selectedId) return;
    if (CRITERIA_IMPACT_DISABLED) {
      d.notify("Control panel refresh is temporarily disabled.", {
        type: "warning",
      });
      return;
    }
    d.setCriteriaImpactLoading(true);
    try {
      const result = await d.dataProvider.getRoleBriefCriteriaImpact(
        Number(d.selectedId),
      );
      d.setCriteriaImpact(result);
    } catch (error: any) {
      d.notify(error?.message || "Failed to load the control panel", {
        type: "error",
      });
    } finally {
      d.setCriteriaImpactLoading(false);
    }
  };

  const handleRoleBriefChange = (value: string) => {
    d.resetSearchUiState();
    d.setSelectedId(value);
    d.loadRoleBriefContext(value);
  };

  const handleDismissClarifyingQuestions = async () => {
    if (!d.selectedId) return;
    d.setRoleBriefDetail((current: any) =>
      current ? { ...current, clarifying_questions_dismissed: true } : current,
    );
    try {
      await d.dataProvider.update("deals", {
        id: Number(d.selectedId),
        data: { clarifying_questions_dismissed: true },
        previousData: { id: Number(d.selectedId) },
      });
    } catch (error: any) {
      d.notify(error?.message || "Failed to dismiss", { type: "error" });
    }
  };

  const handleNlSearch = async () => {
    if (!d.nlText.trim()) {
      d.notify("Describe who you're looking for first", { type: "warning" });
      return;
    }
    d.setNlParsing(true);
    try {
      const parsed = await d.dataProvider.parseJobDescription(d.nlText);
      const { data: created } = await d.dataProvider.create("deals", {
        data: {
          name: parsed.title || d.nlText.slice(0, 60),
          stage: "sourcing",
          jd_text: d.nlText,
          seniority: parsed.seniority,
          location: parsed.location,
          industry: parsed.industry,
          employment_type: parsed.employment_type,
          years_experience_min: parsed.years_experience_min,
          years_experience_max: parsed.years_experience_max,
          required_skills: parsed.required_skills ?? [],
          must_have_keywords: parsed.must_have_keywords ?? [],
          nice_to_have_keywords: parsed.nice_to_have_keywords ?? [],
          preference_tiers:
            parsed.preference_tiers && parsed.preference_tiers.length > 0
              ? parsed.preference_tiers
              : null,
          clarifying_questions:
            parsed.clarifying_questions &&
            parsed.clarifying_questions.length > 0
              ? parsed.clarifying_questions
              : null,
          role_status: "new",
          contact_ids: [],
        },
      });
      d.notify("Search criteria extracted -- review below before previewing", {
        type: "success",
      });
      d.setRoleBriefs((current) => [
        { id: created.id, name: created.name },
        ...current,
      ]);
      d.setNlText("");
      handleRoleBriefChange(String(created.id));
    } catch (error: any) {
      d.notify(error?.message || "Failed to parse that search", {
        type: "error",
      });
    } finally {
      d.setNlParsing(false);
    }
  };

  const handlePreview = async () => {
    if (!d.selectedId) {
      d.notify("Pick a role brief first", { type: "warning" });
      return;
    }
    d.setPreviewLoading(true);
    d.setCandidates([]);
    d.setScrollToken(null);
    d.setSaveStates({});
    try {
      const data = (await d.dataProvider.sourceCandidates(
        Number(d.selectedId),
        1,
        null,
        true,
      )) as SourceResult;
      d.setRoleBriefTitle(data.role_brief.title);
      d.setTotal(data.total);
      d.setNotes(data.notes);
      d.setStage("previewed");
    } catch (error: any) {
      d.notify(error?.message || "Failed to preview matches", {
        type: "error",
      });
    } finally {
      d.setPreviewLoading(false);
    }
  };

  const handleFetch = async () => {
    if (!d.selectedId) return;
    d.setFetchLoading(true);
    try {
      const data = (await d.dataProvider.sourceCandidates(
        Number(d.selectedId),
        d.size,
      )) as SourceResult;
      const sorted = sortCandidatesForDisplay(
        data.candidates,
        d.sortField,
        d.sortByMatchEvidence,
        d.sortByYearsExperience,
        d.sortByCompanySize,
      );
      d.setCandidates(sorted);
      d.setScrollToken(data.scroll_token);
      d.setTotal(data.total);
      d.setTotalMatchesAll(data.total_matches_all);
      d.setNotes(data.notes);
      const seeded: Record<string, SaveState> = {};
      const seededDbIds: Record<string, number> = {};
      for (const candidate of data.candidates) {
        if (candidate._already_saved) seeded[candidate.id] = "saved";
        if (candidate._candidate_id)
          seededDbIds[candidate.id] = candidate._candidate_id;
      }
      d.setSaveStates(seeded);
      d.setCandidateDbIds((prev) => ({ ...prev, ...seededDbIds }));
      d.setStage("fetched");
      d.resetPagination();
      // Auto-expand why-fit for all; pre-load evidence only for top 25
      d.setEvidenceExpanded(
        Object.fromEntries(data.candidates.map((c) => [c.id, true])),
      );
      void Promise.allSettled(
        sorted
          .slice(0, 25)
          .filter((c) => !seededDbIds[c.id])
          .map((c) => handleDiscoveryEvidence(c)),
      );
      // LLM pre-rank (fire-and-forget; annotates top 25 and re-sorts candidates state)
      void applyLlmRanks(sorted);
    } catch (error: any) {
      d.notify(error?.message || "Failed to fetch candidates", {
        type: "error",
      });
    } finally {
      d.setFetchLoading(false);
    }
  };

  const handleSourceCandidates = async () => {
    if (!d.selectedId) return;
    d.setPreviewLoading(true);
    d.setCandidates([]);
    d.setScrollToken(null);
    d.setSaveStates({});
    try {
      const preview = (await d.dataProvider.sourceCandidates(
        Number(d.selectedId),
        1,
        null,
        true,
      )) as SourceResult;
      d.setRoleBriefTitle(preview.role_brief.title);
      d.setTotal(preview.total);
      d.setNotes(preview.notes);
      d.setStage("previewed");
    } catch (error: any) {
      d.notify(error?.message || "Failed to search for candidates", {
        type: "error",
      });
      d.setPreviewLoading(false);
      return;
    }
    d.setPreviewLoading(false);
    d.setFetchLoading(true);
    try {
      const data = (await d.dataProvider.sourceCandidates(
        Number(d.selectedId),
        d.size,
      )) as SourceResult;
      const sorted = sortCandidatesForDisplay(
        data.candidates,
        d.sortField,
        d.sortByMatchEvidence,
        d.sortByYearsExperience,
        d.sortByCompanySize,
      );
      d.setCandidates(sorted);
      d.setScrollToken(data.scroll_token);
      d.setTotal(data.total);
      d.setTotalMatchesAll(data.total_matches_all);
      d.setNotes(data.notes);
      const seeded: Record<string, SaveState> = {};
      const seededDbIds: Record<string, number> = {};
      for (const candidate of data.candidates) {
        if (candidate._already_saved) seeded[candidate.id] = "saved";
        if (candidate._candidate_id)
          seededDbIds[candidate.id] = candidate._candidate_id;
      }
      d.setSaveStates(seeded);
      d.setCandidateDbIds((prev) => ({ ...prev, ...seededDbIds }));
      d.setStage("fetched");
      d.resetPagination();
      // Auto-expand why-fit for all candidates; pre-load evidence for top 25
      d.setEvidenceExpanded(
        Object.fromEntries(data.candidates.map((c) => [c.id, true])),
      );
      void Promise.allSettled(
        sorted
          .slice(0, 25)
          .filter((c) => !seededDbIds[c.id])
          .map((c) => handleDiscoveryEvidence(c)),
      );
      // LLM pre-rank (fire-and-forget; annotates top 25 and re-sorts candidates state)
      void applyLlmRanks(sorted);
    } catch (error: any) {
      d.notify(error?.message || "Failed to search for candidates", {
        type: "error",
      });
    } finally {
      d.setFetchLoading(false);
    }
  };

  const handleSearchWider = async () => {
    if (!d.selectedId || !d.scrollToken) return;
    d.setWideningLoading(true);
    try {
      const data = (await d.dataProvider.sourceCandidates(
        Number(d.selectedId),
        d.size,
        d.scrollToken,
      )) as SourceResult;
      d.setCandidates((prev) =>
        sortCandidatesForDisplay(
          [...prev, ...data.candidates],
          d.sortField,
          d.sortByMatchEvidence,
          d.sortByYearsExperience,
          d.sortByCompanySize,
        ),
      );
      d.setScrollToken(data.scroll_token);
      d.setTotalMatchesAll(data.total_matches_all);
      d.setNotes(data.notes);
      const seeded: Record<string, SaveState> = {};
      const seededDbIds: Record<string, number> = {};
      for (const candidate of data.candidates) {
        if (candidate._already_saved) seeded[candidate.id] = "saved";
        if (candidate._candidate_id)
          seededDbIds[candidate.id] = candidate._candidate_id;
      }
      d.setSaveStates((prev) => ({ ...prev, ...seeded }));
      d.setCandidateDbIds((prev) => ({ ...prev, ...seededDbIds }));
    } catch (error: any) {
      d.notify(error?.message || "Failed to fetch more candidates", {
        type: "error",
      });
    } finally {
      d.setWideningLoading(false);
    }
  };

  const handleRestoreLastSearch = async () => {
    if (!d.selectedId) {
      d.notify("Pick a role brief first", { type: "warning" });
      return;
    }
    const sessionSnap = loadSourcingSnapshot(d.selectedId);
    if (sessionSnap?.candidates?.length) {
      d.applySourcingSnapshot(sessionSnap as any, "session");
      void Promise.allSettled(
        sessionSnap.candidates
          .filter((c) => !(sessionSnap as any).candidateDbIds[c.id])
          .map((c) => handleDiscoveryEvidence(c as PdlCandidate)),
      );
      return;
    }
    d.setRestoreLoading(true);
    try {
      const data = await d.dataProvider.rehydrateDiscoveryCandidates(
        Number(d.selectedId),
      );
      const sorted = sortCandidatesForDisplay(
        data.candidates as PdlCandidate[],
        d.sortField,
        d.sortByMatchEvidence,
        d.sortByYearsExperience,
        d.sortByCompanySize,
      );
      const seeded: Record<string, SaveState> = {};
      const seededDbIds: Record<string, number> = {};
      for (const candidate of data.candidates) {
        if (candidate._already_saved) seeded[candidate.id] = "saved";
        if (candidate._candidate_id)
          seededDbIds[candidate.id] = candidate._candidate_id;
      }
      d.applySourcingSnapshot(
        {
          version: 1,
          savedAt: new Date().toISOString(),
          dealId: d.selectedId,
          stage: "fetched",
          candidates: sorted,
          scrollToken: data.scroll_token,
          total: data.total,
          totalMatchesAll: data.total_matches_all,
          notes: data.notes,
          saveStates: seeded,
          candidateDbIds: seededDbIds,
        } as any,
        "server",
      );
      void Promise.allSettled(
        sorted
          .filter((c) => !seededDbIds[c.id])
          .map((c) => handleDiscoveryEvidence(c)),
      );
    } catch (error: any) {
      d.notify(error?.message || "Could not restore last search", {
        type: "error",
      });
    } finally {
      d.setRestoreLoading(false);
    }
  };

  const handleSteeringContextualize = async () => {
    if (!d.selectedId || !d.steeringText.trim()) return;
    d.setSteeringState("loading");
    try {
      const result = await d.dataProvider.contextualizeCalibrationFeedback(
        Number(d.selectedId),
        d.steeringText.trim(),
      );
      d.setSteeringResult(result);
    } catch (error: any) {
      d.notify(
        error?.message ||
          "Failed to check whether this implies a search criterion",
        { type: "error" },
      );
    } finally {
      d.setSteeringState("done");
    }
  };

  const handleApplySteeringCriterion = async () => {
    if (!d.steeringResult?.criterion || !d.selectedId) return;
    d.setSteeringApplyState("applying");
    try {
      await d.dataProvider.applyLearnedCriterion(
        Number(d.selectedId),
        d.steeringResult.criterion,
      );
      d.setSteeringApplyState("applied");
      d.notify("Criterion applied to future searches for this role", {
        type: "success",
      });
      d.setSteeringText("");
      d.setSteeringResult(null);
      d.setSteeringState("idle");
      d.setSteeringApplyState("idle");
      void handleRefreshCriteriaImpact();
    } catch (error: any) {
      d.setSteeringApplyState("idle");
      d.notify(error?.message || "Failed to apply criterion", {
        type: "error",
      });
    }
  };

  const handleRelaxCriterion = async (criterionId: number) => {
    d.setCriteriaActionStates((prev) => ({
      ...prev,
      [criterionId]: "working",
    }));
    try {
      await d.dataProvider.relaxLearnedCriterion(criterionId);
      await handleRefreshCriteriaImpact();
    } catch (error: any) {
      d.notify(error?.message || "Failed to relax criterion", {
        type: "error",
      });
    } finally {
      d.setCriteriaActionStates((prev) => ({ ...prev, [criterionId]: "idle" }));
    }
  };

  const handleReapplyCriterion = async (criterionId: number) => {
    d.setCriteriaActionStates((prev) => ({
      ...prev,
      [criterionId]: "working",
    }));
    try {
      await d.dataProvider.reapplyLearnedCriterion(criterionId);
      await handleRefreshCriteriaImpact();
    } catch (error: any) {
      d.notify(error?.message || "Failed to reapply criterion", {
        type: "error",
      });
    } finally {
      d.setCriteriaActionStates((prev) => ({ ...prev, [criterionId]: "idle" }));
    }
  };

  return {
    handleRoleBriefChange,
    handleDismissClarifyingQuestions,
    handleNlSearch,
    handlePreview,
    handleFetch,
    handleSourceCandidates,
    handleSearchWider,
    handleRestoreLastSearch,
    handleDiscoveryEvidence,
    handleRefreshCriteriaImpact,
    handleRelaxCriterion,
    handleReapplyCriterion,
    handleSteeringContextualize,
    handleApplySteeringCriterion,
  };
}

import { useEffect, useRef, useState } from "react";
import { useDataProvider, useNotify } from "ra-core";
import type { CrmDataProvider } from "../providers/types";
import {
  loadSourcingSnapshot,
  saveSourcingSnapshot,
} from "./sourcingSessionSnapshot";
import { createDiscoverySearchHandlers } from "./useDiscoverySearch";
import { createFreePortalAndXrayHandlers } from "./useFreePortalAndXraySearch";
import { createCalibrationFlowHandlers } from "./useCalibrationFlow";
import { createEnrichmentActionHandlers } from "./useCandidateEnrichmentActions";
import { createOutreachActionHandlers } from "./useOutreachActions";
import { createInterviewResumeOfferHandlers } from "./useInterviewResumeOfferActions";

import {
  sortCandidatesForDisplay,
  type CandidateSortField,
  type CalibrationEntryState,
  type CriteriaImpact,
  type ContextualizeResult,
  type ContactEnrichResult,
  type DevSignalEnrichResult,
  type EmailPreview,
  type EnrichState,
  type FitAssessmentResult,
  type FullProfileData,
  type InterviewResult,
  type MustHaveCheck,
  type OfferDraft,
  type OfferInfo,
  type OutreachPrepared,
  type PdlCandidate,
  type ResumeInfo,
  type RoleBriefDetail,
  type RoleBriefOption,
  type SaveState,
  type ScoreResult,
  type Stage,
} from "./sourcingTypes";

interface UseCandidateSourcingParams {
  initialRoleBriefId?: string;
  resetPagination: () => void;
  onCandidateSaved?: (candidateId: number, name: string) => void;
}

export function useCandidateSourcing({
  initialRoleBriefId,
  resetPagination,
  onCandidateSaved,
}: UseCandidateSourcingParams) {
  const dataProvider = useDataProvider<CrmDataProvider>();
  const notify = useNotify();

  const controlPanelRef = useRef<HTMLDivElement | null>(null);
  const steeringInputRef = useRef<HTMLInputElement | null>(null);

  const [roleBriefs, setRoleBriefs] = useState<RoleBriefOption[]>([]);
  const [selectedId, setSelectedId] = useState<string>("");
  const [size, setSize] = useState(100);

  const [stage, setStage] = useState<Stage>("idle");
  const [previewLoading, setPreviewLoading] = useState(false);
  const [fetchLoading, setFetchLoading] = useState(false);
  const [wideningLoading, setWideningLoading] = useState(false);
  const [bulkSelected, setBulkSelected] = useState<Set<string>>(new Set());
  const [bulkPreparing, setBulkPreparing] = useState(false);
  const [_bulkQueue, setBulkQueue] = useState<
    Array<{ candidateKey: string; prepared: OutreachPrepared }>
  >([]);
  const [_bulkQueueIdx, setBulkQueueIdx] = useState(0);
  const [restoreLoading, setRestoreLoading] = useState(false);

  const [roleBriefTitle, setRoleBriefTitle] = useState<string | null>(null);
  const [total, setTotal] = useState(0);
  const [totalMatchesAll, setTotalMatchesAll] = useState<number | null>(null);
  const [notes, setNotes] = useState<string[]>([]);
  const [candidates, setCandidates] = useState<PdlCandidate[]>([]);
  const [sortField, setSortField] = useState<CandidateSortField>("default");
  const [sortByMatchEvidence, setSortByMatchEvidence] = useState(false);
  const [sortByYearsExperience, setSortByYearsExperience] = useState(false);
  const [sortByCompanySize, setSortByCompanySize] = useState(false);
  const [scrollToken, setScrollToken] = useState<string | null>(null);
  const [saveStates, setSaveStates] = useState<Record<string, SaveState>>({});
  const [candidateDbIds, setCandidateDbIds] = useState<Record<string, number>>(
    {},
  );

  const [contactEnrichStates, setContactEnrichStates] = useState<
    Record<string, EnrichState>
  >({});
  const [contactEnrichResults, setContactEnrichResults] = useState<
    Record<string, ContactEnrichResult>
  >({});
  const [devSignalEnrichStates, setDevSignalEnrichStates] = useState<
    Record<string, EnrichState>
  >({});
  const [devSignalEnrichResults, setDevSignalEnrichResults] = useState<
    Record<string, DevSignalEnrichResult>
  >({});
  const [fullProfileStates, setFullProfileStates] = useState<
    Record<string, EnrichState>
  >({});
  const [fullProfileData, setFullProfileData] = useState<
    Record<string, FullProfileData>
  >({});
  const [fullProfileExpanded, setFullProfileExpanded] = useState<
    Record<string, boolean>
  >({});
  const [scoreStates, setScoreStates] = useState<Record<string, EnrichState>>(
    {},
  );
  const [evidenceExpanded, setEvidenceExpanded] = useState<
    Record<string, boolean>
  >({});
  const [evidenceStates, setEvidenceStates] = useState<
    Record<string, EnrichState>
  >({});
  const [evidenceResults, setEvidenceResults] = useState<
    Record<string, MustHaveCheck[]>
  >({});
  const [scoreResults, setScoreResults] = useState<Record<string, ScoreResult>>(
    {},
  );
  const [fitStates, setFitStates] = useState<Record<string, EnrichState>>({});
  const [fitResults, setFitResults] = useState<
    Record<string, FitAssessmentResult>
  >({});
  const [interviewStates, setInterviewStates] = useState<
    Record<string, EnrichState>
  >({});
  const [interviewResults, setInterviewResults] = useState<
    Record<string, InterviewResult>
  >({});
  const [resumeStates, setResumeStates] = useState<Record<string, EnrichState>>(
    {},
  );
  const [resumeInfos, setResumeInfos] = useState<Record<string, ResumeInfo>>(
    {},
  );
  const [resumeEmailPreviews, setResumeEmailPreviews] = useState<
    Record<string, EmailPreview>
  >({});
  const [resumeSendStates, setResumeSendStates] = useState<
    Record<string, EnrichState>
  >({});
  const [outreachStates, setOutreachStates] = useState<
    Record<string, EnrichState>
  >({});
  const [outreachSendStates, setOutreachSendStates] = useState<
    Record<string, EnrichState>
  >({});
  const [outreachPrepared, setOutreachPrepared] = useState<
    Record<string, OutreachPrepared>
  >({});
  const [offerStates, setOfferStates] = useState<Record<string, EnrichState>>(
    {},
  );
  const [offerInfos, setOfferInfos] = useState<Record<string, OfferInfo>>({});
  const [offerFormOpen, setOfferFormOpen] = useState<Record<string, boolean>>(
    {},
  );
  const [offerDrafts, setOfferDrafts] = useState<Record<string, OfferDraft>>(
    {},
  );
  const [offerEmailPreviews, setOfferEmailPreviews] = useState<
    Record<string, EmailPreview>
  >({});
  const [offerSendStates, setOfferSendStates] = useState<
    Record<string, EnrichState>
  >({});
  const [bookingPrepared, setBookingPrepared] = useState<
    Record<
      string,
      { booking_link_url: string; email_preview: EmailPreview | null }
    >
  >({});
  const [bookingSendStates, setBookingSendStates] = useState<
    Record<string, EnrichState>
  >({});

  const [calibrationLoading, setCalibrationLoading] = useState(false);
  const [calibrationStarted, setCalibrationStarted] = useState(false);
  const [calibrationCandidates, setCalibrationCandidates] = useState<
    PdlCandidate[]
  >([]);
  const [calibrationReasons, setCalibrationReasons] = useState<
    Record<string, string>
  >({});
  const [calibrationEntryStates, setCalibrationEntryStates] = useState<
    Record<string, CalibrationEntryState>
  >({});
  const [existingCalibrationFeedback, setExistingCalibrationFeedback] =
    useState<Array<{ source_id: string; fit: boolean }>>([]);

  const [contextualizeStates, setContextualizeStates] = useState<
    Record<string, "idle" | "loading" | "done">
  >({});
  const [contextualizeResults, setContextualizeResults] = useState<
    Record<string, ContextualizeResult>
  >({});
  const [applyStates, setApplyStates] = useState<
    Record<string, "idle" | "applying" | "applied">
  >({});

  const [steeringText, setSteeringText] = useState("");
  const [steeringState, setSteeringState] = useState<
    "idle" | "loading" | "done"
  >("idle");
  const [steeringResult, setSteeringResult] =
    useState<ContextualizeResult | null>(null);
  const [steeringApplyState, setSteeringApplyState] = useState<
    "idle" | "applying" | "applied"
  >("idle");

  const [criteriaImpact, setCriteriaImpact] = useState<CriteriaImpact | null>(
    null,
  );
  const [criteriaImpactLoading, setCriteriaImpactLoading] = useState(false);
  const [criteriaActionStates, setCriteriaActionStates] = useState<
    Record<number, "idle" | "working">
  >({});

  const [roleBriefDetail, setRoleBriefDetail] =
    useState<RoleBriefDetail | null>(null);

  const [freePortalLoading, setFreePortalLoading] = useState(false);
  const [freePortalCandidates, setFreePortalCandidates] = useState<
    PdlCandidate[]
  >([]);
  const [freePortalNotes, setFreePortalNotes] = useState<string[]>([]);
  const [freePortalSearched, setFreePortalSearched] = useState(false);
  const [xrayLoading, setXrayLoading] = useState(false);
  const [nlText, setNlText] = useState("");
  const [nlParsing, setNlParsing] = useState(false);

  // -------------------------------------------------------------------------
  // Internal helpers
  // -------------------------------------------------------------------------

  const resetSearchUiState = () => {
    setStage("idle");
    setTotal(0);
    setNotes([]);
    setCandidates([]);
    setScrollToken(null);
    setSaveStates({});
    setCandidateDbIds({});
    setContactEnrichStates({});
    setContactEnrichResults({});
    setDevSignalEnrichStates({});
    setDevSignalEnrichResults({});
    setFullProfileStates({});
    setFullProfileData({});
    setFullProfileExpanded({});
    setScoreStates({});
    setScoreResults({});
    setEvidenceStates({});
    setEvidenceResults({});
    setEvidenceExpanded({});
    setFitStates({});
    setFitResults({});
    setCalibrationLoading(false);
    setCalibrationStarted(false);
    setCalibrationCandidates([]);
    setCalibrationReasons({});
    setCalibrationEntryStates({});
    setExistingCalibrationFeedback([]);
    setContextualizeStates({});
    setContextualizeResults({});
    setApplyStates({});
    setCriteriaImpact(null);
    setCriteriaActionStates({});
    setRoleBriefDetail(null);
  };

  const loadRoleBriefContext = (value: string) => {
    if (!value) return;
    dataProvider
      .getCalibrationFeedback(Number(value))
      .then((rows) =>
        setExistingCalibrationFeedback(
          (rows as any[]).map((r) => ({ source_id: r.source_id, fit: r.fit })),
        ),
      )
      .catch(() => {});

    dataProvider
      .getOne("deals", { id: Number(value) })
      .then(({ data }) =>
        setRoleBriefDetail(data as unknown as RoleBriefDetail),
      )
      .catch(() => {});
  };

  const applySourcingSnapshot = (
    snapshot: ReturnType<typeof loadSourcingSnapshot> & object,
    source: "session" | "server",
    silent = false,
  ) => {
    setSelectedId((snapshot as any).dealId);
    setStage((snapshot as any).stage);
    setCandidates((snapshot as any).candidates as PdlCandidate[]);
    setScrollToken((snapshot as any).scrollToken);
    setTotal((snapshot as any).total);
    setTotalMatchesAll((snapshot as any).totalMatchesAll);
    setNotes((snapshot as any).notes);
    setSaveStates((snapshot as any).saveStates as Record<string, SaveState>);
    setCandidateDbIds((snapshot as any).candidateDbIds);
    setEvidenceExpanded(
      Object.fromEntries(
        ((snapshot as any).candidates as PdlCandidate[]).map((c) => [
          c.id,
          true,
        ]),
      ),
    );
    loadRoleBriefContext((snapshot as any).dealId);
    if (!silent) {
      notify(
        source === "session"
          ? `Restored ${(snapshot as any).candidates.length} candidate(s) from this browser session (no new search credits).`
          : `Restored ${(snapshot as any).candidates.length} candidate(s) from your last search on this role.`,
        { type: "success" },
      );
    }
  };

  // -------------------------------------------------------------------------
  // Effects
  // -------------------------------------------------------------------------

  useEffect(() => {
    dataProvider
      .getList("deals", {
        pagination: { page: 1, perPage: 100 },
        sort: { field: "id", order: "DESC" },
        filter: {},
      })
      .then(({ data }) => {
        setRoleBriefs((data as any[]).map((d) => ({ id: d.id, name: d.name })));
      })
      .catch(() => {
        notify("Failed to load role briefs", { type: "error" });
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    setCandidates((prev) =>
      prev.length > 0
        ? sortCandidatesForDisplay(
            prev,
            sortField,
            sortByMatchEvidence,
            sortByYearsExperience,
            sortByCompanySize,
          )
        : prev,
    );
  }, [
    sortField,
    sortByMatchEvidence,
    sortByYearsExperience,
    sortByCompanySize,
  ]);

  useEffect(() => {
    if (!selectedId || stage !== "fetched" || candidates.length === 0) return;
    saveSourcingSnapshot({
      version: 1,
      savedAt: new Date().toISOString(),
      dealId: selectedId,
      stage,
      candidates,
      scrollToken,
      total,
      totalMatchesAll,
      notes,
      saveStates,
      candidateDbIds,
    });
  }, [
    selectedId,
    stage,
    candidates,
    scrollToken,
    total,
    totalMatchesAll,
    notes,
    saveStates,
    candidateDbIds,
  ]);

  useEffect(() => {
    if (!initialRoleBriefId) return;
    const snapshot = loadSourcingSnapshot(initialRoleBriefId);
    if (snapshot?.candidates?.length) {
      // silent=true: auto-restore on mount should not show a toast every time
      // the tab remounts. Toast only fires on explicit "Restore last search" click.
      applySourcingSnapshot(snapshot as any, "session", true);
    } else {
      setSelectedId(initialRoleBriefId);
      loadRoleBriefContext(initialRoleBriefId);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialRoleBriefId]);

  // -------------------------------------------------------------------------
  // Handler factories — each factory receives current state/setters as deps
  // -------------------------------------------------------------------------

  // RA's notify type uses `NotificationType` (a union) but all handler factories
  // declare a looser `string` type for the opts.type field — cast to align them.
  const notifyLoose = notify as (msg: string, opts: { type: string }) => void;

  const discoveryHandlers = createDiscoverySearchHandlers({
    dataProvider,
    notify: notifyLoose,
    selectedId,
    size,
    sortField,
    sortByMatchEvidence,
    sortByYearsExperience,
    sortByCompanySize,
    scrollToken,
    total,
    nlText,
    steeringText,
    steeringResult,
    candidateDbIds,
    setSelectedId,
    resetPagination,
    setStage,
    setCandidates,
    setScrollToken,
    setTotal,
    setTotalMatchesAll,
    setNotes,
    setSaveStates,
    setCandidateDbIds,
    setPreviewLoading,
    setFetchLoading,
    setWideningLoading,
    setRestoreLoading,
    setRoleBriefTitle,
    setNlText,
    setNlParsing,
    setRoleBriefs,
    setEvidenceExpanded,
    setEvidenceStates,
    setEvidenceResults,
    setCalibrationLoading,
    setCalibrationStarted,
    setCalibrationCandidates,
    setCriteriaImpact,
    setCriteriaImpactLoading,
    setCriteriaActionStates,
    setSteeringText,
