    selectedId,
    freePortalCandidates,
    freePortalNotes,
    setFreePortalLoading,
    setFreePortalCandidates,
    setFreePortalNotes,
    setFreePortalSearched,
    setXrayLoading,
    setCandidateDbIds,
  });

  const calibrationHandlers = createCalibrationFlowHandlers({
    dataProvider,
    notify: notifyLoose,
    selectedId,
    calibrationReasons,
    contextualizeResults,
    setCalibrationLoading,
    setCalibrationStarted,
    setCalibrationCandidates,
    setNotes,
    setTotal,
    setCalibrationEntryStates,
    setContextualizeStates,
    setContextualizeResults,
    setApplyStates,
    handleRefreshCriteriaImpact: discoveryHandlers.handleRefreshCriteriaImpact,
  });

  const enrichmentHandlers = createEnrichmentActionHandlers({
    dataProvider,
    notify: notifyLoose,
    selectedId,
    candidateDbIds,
    fullProfileData,
    setContactEnrichStates,
    setContactEnrichResults,
    setDevSignalEnrichStates,
    setDevSignalEnrichResults,
    setFullProfileStates,
    setFullProfileData,
    setFullProfileExpanded,
    setScoreStates,
    setScoreResults,
    setFitStates,
    setFitResults,
  });

  const outreachHandlers = createOutreachActionHandlers({
    dataProvider,
    notify: notifyLoose,
    selectedId,
    candidates,
    bulkSelected,
    candidateDbIds,
    outreachPrepared,
    onCandidateSaved,
    setOutreachStates,
    setOutreachPrepared,
    setOutreachSendStates,
    setSaveStates,
    setCandidateDbIds,
    setBulkPreparing,
    setBulkQueue,
    setBulkQueueIdx,
    setBulkSelected,
  });

  const interviewResumeOfferHandlers = createInterviewResumeOfferHandlers({
    dataProvider,
    notify: notifyLoose,
    selectedId,
    candidateDbIds,
    bookingPrepared,
    resumeEmailPreviews,
    resumeInfos,
    offerDrafts,
    offerEmailPreviews,
    offerInfos,
    setInterviewStates,
    setInterviewResults,
    setBookingPrepared,
    setBookingSendStates,
    setResumeStates,
    setResumeEmailPreviews,
    setResumeInfos,
    setResumeSendStates,
    setOfferStates,
    setOfferInfos,
    setOfferFormOpen,
    setOfferDrafts,
    setOfferEmailPreviews,
    setOfferSendStates,
  });

  const canSearchWider = Boolean(scrollToken) && candidates.length < total;

  return {
    // Refs
    controlPanelRef,
    steeringInputRef,
    // Core state
    roleBriefs,
    selectedId,
    size,
    setSize,
    stage,
    previewLoading,
    fetchLoading,
    wideningLoading,
    bulkSelected,
    setBulkSelected,
    bulkPreparing,
    restoreLoading,
    roleBriefTitle,
    total,
    totalMatchesAll,
    notes,
    candidates,
    sortField,
    setSortField,
    sortByMatchEvidence,
    setSortByMatchEvidence,
    sortByYearsExperience,
    setSortByYearsExperience,
    sortByCompanySize,
    setSortByCompanySize,
    scrollToken,
    saveStates,
    setSaveStates,
    candidateDbIds,
    setCandidateDbIds,
    // Enrich state
    contactEnrichStates,
