}

import type { CrmDataProvider } from "../providers/types";
import {
  ACTION_LABELS,
  FIT_BUCKET_LABELS,
  type ContactEnrichResult,
  type DevSignalEnrichResult,
  type FitAssessmentResult,
  type FullProfileData,
  type FullProfileEnrichResult,
  type PdlCandidate,
  type ScoreResult,
} from "./sourcingTypes";

type SetState<T> = React.Dispatch<React.SetStateAction<T>>;
type NotifyFn = (msg: string, opts: { type: string }) => void;

export type EnrichmentActionsDeps = {
  dataProvider: CrmDataProvider;
  notify: NotifyFn;
  selectedId: string;
  candidateDbIds: Record<string, number>;
  fullProfileData: Record<string, FullProfileData>;
  setContactEnrichStates: SetState<Record<string, any>>;
  setContactEnrichResults: SetState<Record<string, ContactEnrichResult>>;
  setDevSignalEnrichStates: SetState<Record<string, any>>;
  setDevSignalEnrichResults: SetState<Record<string, DevSignalEnrichResult>>;
  setFullProfileStates: SetState<Record<string, any>>;
  setFullProfileData: SetState<Record<string, FullProfileData>>;
  setFullProfileExpanded: SetState<Record<string, boolean>>;
  setScoreStates: SetState<Record<string, any>>;
  setScoreResults: SetState<Record<string, ScoreResult>>;
  setFitStates: SetState<Record<string, any>>;
  setFitResults: SetState<Record<string, FitAssessmentResult>>;
};

export function createEnrichmentActionHandlers(d: EnrichmentActionsDeps) {
  const handleEnrichContact = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    if (!candidateId) return;
    d.setContactEnrichStates((prev) => ({
      ...prev,
      [candidate.id]: "loading",
    }));
    try {
      const result = (await d.dataProvider.enrichCandidateContact(
        candidateId,
      )) as ContactEnrichResult;
      d.setContactEnrichResults((prev) => ({
        ...prev,
        [candidate.id]: result,
      }));
      d.setContactEnrichStates((prev) => ({ ...prev, [candidate.id]: "done" }));
      d.notify(
        result.status === "enriched"
          ? `Contact found via ${result.source}`
          : result.status === "not_found"
            ? "No contact info found"
            : "Contact enrichment failed -- see notes",
        { type: result.status === "enriched" ? "success" : "warning" },
      );
    } catch (error: any) {
      d.setContactEnrichStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to enrich contact", { type: "error" });
    }
  };

  const handleEnrichDevSignals = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    if (!candidateId) return;
    d.setDevSignalEnrichStates((prev) => ({
      ...prev,
      [candidate.id]: "loading",
    }));
    try {
      const result = (await d.dataProvider.enrichCandidateDevSignals(
        candidateId,
      )) as DevSignalEnrichResult;
      d.setDevSignalEnrichResults((prev) => ({
        ...prev,
        [candidate.id]: result,
      }));
      d.setDevSignalEnrichStates((prev) => ({
        ...prev,
        [candidate.id]: "done",
      }));
      d.notify(
        result.status === "enriched"
          ? "Dev signal(s) found"
          : result.status === "not_found"
            ? "No confident dev-signal match found"
            : "Dev-signal enrichment failed -- see notes",
        { type: result.status === "enriched" ? "success" : "warning" },
      );
    } catch (error: any) {
      d.setDevSignalEnrichStates((prev) => ({
        ...prev,
        [candidate.id]: "idle",
      }));
      d.notify(error?.message || "Failed to enrich dev signals", {
        type: "error",
      });
    }
  };

  const handleViewFullProfile = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    if (!candidateId) return;
    const alreadyHaveData = d.fullProfileData[candidate.id];
    if (alreadyHaveData) {
      d.setFullProfileExpanded((prev) => ({
        ...prev,
        [candidate.id]: !prev[candidate.id],
      }));
      return;
    }
    d.setFullProfileStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    try {
      const enrichResult = (await d.dataProvider.enrichCandidateWorkHistory(
        candidateId,
      )) as FullProfileEnrichResult;
      const profile = (await d.dataProvider.getCandidateFullProfile(
        candidateId,
      )) as FullProfileData;
      d.setFullProfileData((prev) => ({ ...prev, [candidate.id]: profile }));
      d.setFullProfileStates((prev) => ({ ...prev, [candidate.id]: "done" }));
      d.setFullProfileExpanded((prev) => ({ ...prev, [candidate.id]: true }));
      d.notify(
        enrichResult.status === "enriched"
          ? `Full profile loaded via ${enrichResult.source} (${enrichResult.experience_count} jobs, ${enrichResult.education_count} education)`
          : enrichResult.status === "not_found"
            ? "No full profile found for this candidate"
            : "Full profile lookup failed -- see notes",
        { type: enrichResult.status === "enriched" ? "success" : "warning" },
      );
    } catch (error: any) {
      d.setFullProfileStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to load full profile", {
        type: "error",
      });
    }
  };

  const handleScoreCandidate = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    if (!candidateId || !d.selectedId) return;
    d.setScoreStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    try {
      const result = (await d.dataProvider.scoreCandidate(
        candidateId,
        Number(d.selectedId),
      )) as ScoreResult;
      d.setScoreResults((prev) => ({ ...prev, [candidate.id]: result }));
      d.setScoreStates((prev) => ({ ...prev, [candidate.id]: "done" }));
      d.notify(
        `${result.verdict} (${result.overall_score}/100) -- recommended: ${ACTION_LABELS[result.recommended_action]}`,
        {
          type: result.recommended_action === "reject" ? "warning" : "success",
        },
      );
    } catch (error: any) {
      d.setScoreStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to score candidate", {
        type: "error",
      });
    }
  };

  const handleAssessFit = async (candidate: PdlCandidate) => {
    const candidateId = d.candidateDbIds[candidate.id];
    if (!candidateId || !d.selectedId) return;
    d.setFitStates((prev) => ({ ...prev, [candidate.id]: "loading" }));
    try {
      const result = (await d.dataProvider.assessCandidateFit(
        candidateId,
        Number(d.selectedId),
      )) as FitAssessmentResult;
      d.setFitResults((prev) => ({ ...prev, [candidate.id]: result }));
      d.setFitStates((prev) => ({ ...prev, [candidate.id]: "done" }));
      d.notify(FIT_BUCKET_LABELS[result.fit_bucket], {
        type: result.fit_bucket === "not_a_fit" ? "warning" : "success",
      });
    } catch (error: any) {
      d.setFitStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      d.notify(error?.message || "Failed to assess candidate fit", {
        type: "error",
      });
    }
  };

  return {
    handleEnrichContact,
    handleEnrichDevSignals,
    handleViewFullProfile,
    handleScoreCandidate,
    handleAssessFit,
  };
}

import type { CrmDataProvider } from "../providers/types";
import {
  sortCandidatesForDisplay,
  type CalibrationEntryState,
  type ContextualizeResult,
  type PdlCandidate,
  type SourceResult,
} from "./sourcingTypes";

type SetState<T> = React.Dispatch<React.SetStateAction<T>>;
type NotifyFn = (msg: string, opts: { type: string }) => void;

export type CalibrationFlowDeps = {
  dataProvider: CrmDataProvider;
  notify: NotifyFn;
  selectedId: string;
  calibrationReasons: Record<string, string>;
  contextualizeResults: Record<string, ContextualizeResult>;
  setCalibrationLoading: SetState<boolean>;
  setCalibrationStarted: SetState<boolean>;
  setCalibrationCandidates: SetState<PdlCandidate[]>;
  setNotes: SetState<string[]>;
  setTotal: SetState<number>;
  setCalibrationEntryStates: SetState<Record<string, CalibrationEntryState>>;
  setContextualizeStates: SetState<Record<string, "idle" | "loading" | "done">>;
  setContextualizeResults: SetState<Record<string, ContextualizeResult>>;
  setApplyStates: SetState<Record<string, "idle" | "applying" | "applied">>;
  handleRefreshCriteriaImpact: () => Promise<void>;
};

export function createCalibrationFlowHandlers(d: CalibrationFlowDeps) {
  const handleContextualize = async (
    candidate: PdlCandidate,
    reason: string,
  ) => {
    d.setContextualizeStates((prev) => ({
      ...prev,
      [candidate.id]: "loading",
    }));
    try {
      const result = await d.dataProvider.contextualizeCalibrationFeedback(
        Number(d.selectedId),
        reason,
        candidate._match_evidence,
      );
      d.setContextualizeResults((prev) => ({
        ...prev,
        [candidate.id]: result,
      }));
    } catch (error: any) {
      d.notify(
        error?.message ||
          "Failed to check whether this reason implies a search criterion",
        { type: "error" },
      );
    } finally {
      d.setContextualizeStates((prev) => ({ ...prev, [candidate.id]: "done" }));
    }
  };

  const handleStartCalibration = async (provider?: string) => {
    if (!d.selectedId) return;
    d.setCalibrationLoading(true);
    try {
      const data = (await d.dataProvider.sourceCandidates(
        Number(d.selectedId),
        3,
        null,
        false,
        provider,
      )) as SourceResult;
      d.setCalibrationCandidates(
        sortCandidatesForDisplay(
          data.candidates,
          "default",
          true,
          false,
          false,
        ),
      );
      d.setCalibrationStarted(true);
      d.setNotes(data.notes);
      d.setTotal(data.total);
    } catch (error: any) {
      d.notify(error?.message || "Failed to pull candidates to calibrate on", {
        type: "error",
      });
    } finally {
      d.setCalibrationLoading(false);
    }
  };

  const handleSubmitCalibrationJudgment = async (
    candidate: PdlCandidate,
    fit: boolean,
  ) => {
    const reason = (d.calibrationReasons[candidate.id] ?? "").trim();
    if (!reason) {
      d.notify("A reason is required before submitting", { type: "warning" });
      return;
    }
    d.setCalibrationEntryStates((prev) => ({
      ...prev,
      [candidate.id]: "submitting",
    }));
    try {
      await d.dataProvider.submitCalibrationFeedback(
        Number(d.selectedId),
        candidate.id,
        fit,
        reason,
        {
          full_name: candidate.full_name,
          job_title: candidate.job_title,
          job_company_name: candidate.job_company_name,
          location_name: candidate.location_name,
          linkedin_url: candidate.linkedin_url,
          skills: candidate.skills,
          _match_score: candidate._match_score,
        },
      );
      d.setCalibrationEntryStates((prev) => ({
        ...prev,
        [candidate.id]: "submitted",
      }));
      d.notify(fit ? "Marked as a fit" : "Marked as not a fit", {
        type: "success",
      });
      if (!fit) void handleContextualize(candidate, reason);
    } catch (error: any) {
      d.setCalibrationEntryStates((prev) => ({
        ...prev,
        [candidate.id]: "idle",
      }));
      d.notify(error?.message || "Failed to save judgment", { type: "error" });
    }
  };

  const handleApplyCriterion = async (candidateId: string) => {
    const result = d.contextualizeResults[candidateId];
    if (!result?.criterion) return;
    d.setApplyStates((prev) => ({ ...prev, [candidateId]: "applying" }));
    try {
      await d.dataProvider.applyLearnedCriterion(
        Number(d.selectedId),
        result.criterion,
      );
      d.setApplyStates((prev) => ({ ...prev, [candidateId]: "applied" }));
      d.notify("Criterion applied to future searches for this role", {
        type: "success",
      });
      void d.handleRefreshCriteriaImpact();
    } catch (error: any) {
      d.setApplyStates((prev) => ({ ...prev, [candidateId]: "idle" }));
      d.notify(error?.message || "Failed to apply criterion", {
        type: "error",
      });
    }
  };

  return {
    handleStartCalibration,
    handleSubmitCalibrationJudgment,
    handleApplyCriterion,
  };
}

import { useDataProvider, useNotify } from "ra-core";
import type { CrmDataProvider } from "../providers/types";
import type { PdlCandidate, SaveState } from "./sourcingTypes";
import type React from "react";

interface UseAddToPipelineParams {
  selectedId: string;
  candidateDbIds: Record<string, number>;
  setCandidateDbIds: React.Dispatch<
    React.SetStateAction<Record<string, number>>
  >;
  setSaveStates: React.Dispatch<
    React.SetStateAction<Record<string, SaveState>>
  >;
  onCandidateSaved?: (candidateId: number, name: string) => void;
}

export function useAddToPipeline({
  selectedId,
  candidateDbIds,
  setCandidateDbIds,
  setSaveStates,
  onCandidateSaved,
}: UseAddToPipelineParams) {
  const dataProvider = useDataProvider<CrmDataProvider>();
  const notify = useNotify();

  const handleAddToPipeline = async (candidate: PdlCandidate) => {
    if (!selectedId) return;
    setSaveStates((prev) => ({ ...prev, [candidate.id]: "saving" }));
    try {
      const outcome = await dataProvider.saveSourcedCandidate(
        Number(selectedId),
        candidate,
      );
      setSaveStates((prev) => ({ ...prev, [candidate.id]: "saved" }));
      if (outcome.candidate_id) {
        setCandidateDbIds((prev) => ({
          ...prev,
          [candidate.id]: outcome.candidate_id,
        }));
      }
      notify(
        outcome.status === "created"
          ? "Added to pipeline"
          : "Already in your candidates -- linked to this role",
        { type: "success" },
      );
      if (outcome.candidate_id && onCandidateSaved) {
        const name =
          [candidate.full_name].filter(Boolean).join(" ") ||
          `Candidate #${outcome.candidate_id}`;
        onCandidateSaved(outcome.candidate_id, name);
      }
    } catch (error: any) {
      setSaveStates((prev) => ({ ...prev, [candidate.id]: "idle" }));
      notify(error?.message || "Failed to add candidate", { type: "error" });
    }
  };

  const isAlreadySaved = (candidateVendorId: string) =>
    Boolean(candidateDbIds[candidateVendorId]);

  return { handleAddToPipeline, isAlreadySaved };
}

