// Agent H, sourcing sidebar (2026-07-21): the persistent, always-there
// sourcing conversation Harsha asked for -- "let recruiters breathe"
// means generous spacing and a calm, uncluttered thread, not a dense
// command bar. Docked to the right edge, toggleable, survives navigating
// within the session (thread state lives in useSourcingThread, owned by
// whichever page mounts this). Vendor names are deliberately anonymized
// ("developer & community search", "web search") -- Harsha's explicit
// call not to expose sourcing vendors to end users.
import { useNavigate } from "react-router";
import { useQueryClient } from "@tanstack/react-query";
import { useDataProvider } from "ra-core";
import { useRef, useState } from "react";

import type { CrmDataProvider } from "../providers/types";
import type { Deal } from "../types";
import "../inbox/agent-h-theme.css";
import { useSourcingThread } from "./useSourcingThread";
import { useVoiceInput } from "./useVoiceInput";
import type { SourcingStep, ThreadItem } from "./sourcingThreadTypes";

const STEP_DOT: Record<SourcingStep["status"], string> = {
  pending: "var(--ah-text-3)",
  active: "var(--ah-accent)",
  done: "var(--ah-good)",
};

const StepRow = ({ step }: { step: SourcingStep }) => (
  <div
    style={{
      display: "flex",
      alignItems: "center",
      gap: 9,
      fontSize: 12.5,
      padding: "3px 0",
    }}
  >
    <div
      style={{
        width: 6,
        height: 6,
        borderRadius: "50%",
        flexShrink: 0,
        background: STEP_DOT[step.status],
        ...(step.status === "active"
          ? { animation: "ah-pulse 1.2s infinite" }
          : {}),
      }}
    />
    <span
      style={{
        color:
          step.status === "pending" ? "var(--ah-text-3)" : "var(--ah-text-2)",
      }}
    >
      {step.label}
      {step.status === "done" ? " — done" : step.status === "active" ? "…" : ""}
    </span>
  </div>
);

const ThreadEntry = ({ item }: { item: ThreadItem }) => {
  if (item.kind === "user") {
    return (
      <div
        style={{
          alignSelf: "flex-end",
          maxWidth: "85%",
          background: "var(--ah-accent-chip)",
          color: "var(--ah-text-1)",
          borderRadius: 12,
          padding: "9px 13px",
          fontSize: 13.5,
        }}
      >
        {item.text}
      </div>
    );
  }

  if (item.kind === "assistant") {
    const color =
      item.tone === "error"
        ? "var(--ah-danger)"
        : item.tone === "success"
          ? "var(--ah-good)"
          : "var(--ah-text-2)";
    return (
      <div style={{ fontSize: 13, color, lineHeight: 1.5 }}>{item.text}</div>
    );
  }

  // kind === "sourcing"
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      <div
        className="ah-glass-card"
        style={{
          padding: "12px 14px",
          display: "flex",
          flexDirection: "column",
          gap: 2,
        }}
      >
        <div
          style={{ fontSize: 12, color: "var(--ah-text-3)", marginBottom: 4 }}
        >
          Sourcing for {item.dealName}
        </div>
        {item.steps.map((step) => (
          <StepRow key={step.key} step={step} />
        ))}
        {item.error && (
          <div
            style={{ fontSize: 12.5, color: "var(--ah-danger)", marginTop: 6 }}
          >
            {item.error}
          </div>
        )}
      </div>

      {item.result && (
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          <div style={{ fontSize: 12, color: "var(--ah-text-3)" }}>
            Found {item.result.foundCount}
            {item.result.filteredCount > 0
              ? `, ${item.result.filteredCount} filtered as not relevant`
              : ""}
          </div>
          {item.result.foundCount > 0 && (
            <div style={{ fontSize: 12, color: "var(--ah-text-3)" }}>
              Open the role to review and add candidates to your pipeline.
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export const SourcingSidebar = ({
  open,
  onClose,
  openDeals,
}: {
  open: boolean;
  onClose: () => void;
  openDeals: Deal[];
}) => {
  const navigate = useNavigate();
  const dataProvider = useDataProvider<CrmDataProvider>();
  const queryClient = useQueryClient();
  const [value, setValue] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);

  const { thread, submit, isBusy } = useSourcingThread({
    dataProvider,
    queryClient,
    openDeals: openDeals.map((d) => ({ id: d.id, name: d.name })),
    onNavigate: navigate,
  });

  const {
    isSupported: voiceSupported,
    isListening,
    toggleListening,
  } = useVoiceInput((transcript) => {
    setValue((prev) => (prev ? `${prev} ${transcript}` : transcript));
  });

  const runSubmit = () => {
    if (!value.trim() || isBusy) return;
    submit(value);
    setValue("");
  };

  if (!open) return null;

  return (
    <div
      className="ah-theme"
      style={{
        position: "fixed",
        top: 0,
        right: 0,
        height: "100vh",
        width: 380,
        zIndex: 60,
        background: "var(--ah-bg-1)",
        borderLeft: "1px solid var(--ah-border)",
        boxShadow:
          "-8px 0 24px color-mix(in oklch, var(--foreground) 8%, transparent)",
        display: "flex",
        flexDirection: "column",
      }}
    >
      <div
        style={{
          padding: "18px 20px 14px",
          borderBottom: "1px solid var(--ah-border)",
          display: "flex",
          alignItems: "center",
          gap: 8,
          flexShrink: 0,
        }}
      >
        <span style={{ fontSize: 14, fontWeight: 600 }}>Sourcing</span>
        <div
          onClick={onClose}
          style={{
            marginLeft: "auto",
            cursor: "pointer",
            color: "var(--ah-text-3)",
            fontSize: 18,
            lineHeight: 1,
          }}
          aria-label="Close sourcing panel"
        >
          &times;
        </div>
      </div>

      <div
        style={{
          flex: 1,
          overflowY: "auto",
          padding: "20px",
          display: "flex",
          flexDirection: "column",
          gap: 20,
        }}
      >
        {thread.length === 0 && (
          <div
            style={{
              fontSize: 13,
              color: "var(--ah-text-3)",
              lineHeight: 1.6,
              padding: "8px 2px",
            }}
          >
            <p style={{ marginBottom: 8 }}>
              Use this chat to refine your search criteria — say things like:
            </p>
            <ul
              style={{
                paddingLeft: 16,
                display: "flex",
                flexDirection: "column",
                gap: 4,
              }}
            >
              <li>"Relax the company size requirement"</li>
              <li>"We also need Kubernetes experience"</li>
              <li>"Remove the Python requirement"</li>
              <li>"Continue sourcing for [role name]"</li>
            </ul>
          </div>
        )}
        {thread.map((item) => (
          <ThreadEntry key={item.id} item={item} />
        ))}
      </div>

      <div
        style={{
          borderTop: "1px solid var(--ah-border)",
          padding: 14,
          display: "flex",
          gap: 8,
          alignItems: "center",
          flexShrink: 0,
        }}
      >
        {voiceSupported && (
          <button
            className="ah-btn-ghost"
            onClick={toggleListening}
            aria-label={
              isListening ? "Stop listening" : "Talk instead of typing"
            }
            style={{
              width: 34,
              height: 34,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
              borderColor: isListening ? "var(--ah-accent)" : undefined,
              color: isListening ? "var(--ah-accent)" : undefined,
            }}
          >
            &#127908;
          </button>
        )}
        <input
          ref={inputRef}
          type="text"
          value={value}
          disabled={isBusy}
          placeholder={
            isBusy ? "Working on it…" : "Tighten, loosen, or refine the search…"
          }
          onChange={(e) => setValue(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              runSubmit();
            }
          }}
          style={{
            flex: 1,
            background: "var(--ah-glass)",
            border: "1px solid var(--ah-border)",
            borderRadius: 100,
            padding: "8px 14px",
            outline: "none",
            color: "var(--ah-text-1)",
            fontSize: 13.5,
          }}
        />
        <button
          className="ah-btn-primary"
          onClick={runSubmit}
          disabled={isBusy}
          aria-label="Send"
          style={{
            width: 34,
            height: 34,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 13,
            flexShrink: 0,
            opacity: isBusy ? 0.5 : 1,
          }}
        >
          &#8593;
        </button>
      </div>
    </div>
  );
};

// Extracted panel components for SourceCandidatesPage — pure display,
// all state/handlers flow in via the `s` sourcing context prop.

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  AH_CALLOUT_WARN,
  buildXrayQueries,
  sourcingPanelClass,
  titleCase,
} from "./sourcingTypes";
import { CalibrationFeedbackWidget } from "./CandidateResultsList";
import type { useCandidateSourcing } from "./useCandidateSourcing";

type SourcingContext = ReturnType<typeof useCandidateSourcing>;

// Disabled while per-criterion preview API spend is unbounded; flip to true
// to re-enable once a server-side fix lands.
const CRITERIA_IMPACT_DISABLED = false;

// ---------------------------------------------------------------------------
// RoleBriefPanel — compact collapsible "Searching for:" chip
// ---------------------------------------------------------------------------

export function RoleBriefPanel({
  s,
  embedded,
}: {
  s: SourcingContext;
  embedded: boolean;
}) {
  const d = s.roleBriefDetail;
  const [expanded, setExpanded] = useState(false);
  if (!d) return null;

  // Build a compact one-liner summary
  const summaryParts = [
    d.seniority ? `${d.seniority} ` : "",
    d.name ?? "(untitled role)",
    d.location ? ` · ${d.location}` : "",
    d.years_experience_min || d.years_experience_max
      ? ` · ${d.years_experience_min ?? "0"}–${d.years_experience_max ?? "any"}y exp`
      : "",
  ].join("");

  return (
    <div className={sourcingPanelClass(embedded, "p-3")}>
      <button
        type="button"
        onClick={() => setExpanded((v) => !v)}
        className="w-full flex items-center justify-between gap-2 text-left"
      >
        <div className="flex items-center gap-2 flex-wrap min-w-0">
          <span className="text-xs font-medium text-muted-foreground uppercase tracking-wide shrink-0">
            Searching for
          </span>
          <span className="text-sm font-medium truncate">{summaryParts}</span>
        </div>
        <span className="text-xs text-muted-foreground shrink-0">
          {expanded ? "▲" : "▼"}
        </span>
      </button>

      {expanded && (
        <div className="mt-3 border-t pt-3">
          <ul className="text-sm list-disc pl-4 flex flex-col gap-0.5">
            {d.must_have_keywords && d.must_have_keywords.length > 0 && (
              <li>Must have: {d.must_have_keywords.join(", ")}</li>
            )}
            {d.required_skills && d.required_skills.length > 0 && (
              <li>Skills: {d.required_skills.join(", ")}</li>
            )}
            {d.nice_to_have_keywords && d.nice_to_have_keywords.length > 0 && (
              <li>Nice to have: {d.nice_to_have_keywords.join(", ")}</li>
            )}
            {d.industry && <li>Industry (preferred): {d.industry}</li>}
            {(d.company_type || d.company_size_min || d.company_size_max) && (
              <li>
                Companies:{" "}
                {[
                  d.company_type,
                  d.company_size_min || d.company_size_max
                    ? `${d.company_size_min ?? "any"}–${d.company_size_max ?? "any"} employees`
                    : null,
                ]
                  .filter(Boolean)
                  .join(", ")}
              </li>
            )}
            {d.excluded_companies && d.excluded_companies.length > 0 && (
              <li>Excluding: {d.excluded_companies.join(", ")}</li>
            )}
            {d.past_titles && d.past_titles.length > 0 && (
              <li>Boosting past titles: {d.past_titles.join(", ")}</li>
            )}
            {d.past_companies && d.past_companies.length > 0 && (
              <li>Boosting past companies: {d.past_companies.join(", ")}</li>
            )}
          </ul>

          {d.clarifying_questions &&
            d.clarifying_questions.length > 0 &&
            !d.clarifying_questions_dismissed && (
              <div
                className={`flex flex-col gap-2 mt-2 rounded-md p-3 ${AH_CALLOUT_WARN}`}
              >
                <h4 className="text-xs font-medium">
                  Worth confirming before sourcing further
                </h4>
                <ul className="list-disc pl-5 text-xs">
                  {d.clarifying_questions.map((question, i) => (
                    <li key={i}>{question}</li>
                  ))}
                </ul>
                <div>
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={s.handleDismissClarifyingQuestions}
                  >
                    Dismiss
                  </Button>
                </div>
              </div>
            )}

          {d.preference_tiers && d.preference_tiers.length > 0 && (
            <div className="flex flex-col gap-1.5 mt-2 border-t pt-2">
              {[...d.preference_tiers]
                .sort((a, b) => a.rank - b.rank)
                .map((tier) => (
                  <div key={tier.rank} className="text-sm">
                    <span className="font-medium">{tier.label}: </span>
                    {tier.keywords.join(", ")}
                    {tier.condition && (
                      <span className="text-muted-foreground">
                        {" "}
                        ({tier.condition})
                      </span>
                    )}
                  </div>
                ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// SourcingControlPanel — learned-criteria impact only.
// Criteria refinement (tighten / loosen / add) is handled by the
// SourcingSidebar chat — type there rather than duplicating an input here.
// ---------------------------------------------------------------------------

export function SourcingControlPanel({
  s,
  embedded,
  onOpenSidebar,
}: {
  s: SourcingContext;
  embedded: boolean;
  onOpenSidebar?: () => void;
}) {
  if (!s.selectedId) return null;
  // Nothing to show if criteria impact is disabled and nothing is loaded
  const hasCriteria = s.criteriaImpact && s.criteriaImpact.criteria.length > 0;
  if (!hasCriteria && !s.criteriaImpactLoading && !CRITERIA_IMPACT_DISABLED)
    return null;

  return (
    <div
      ref={s.controlPanelRef}
      className={sourcingPanelClass(embedded, "flex flex-col gap-2 p-4")}
    >
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-medium">Learned criteria</h3>
        {!CRITERIA_IMPACT_DISABLED && (
          <Button
            size="sm"
            variant="outline"
            onClick={s.handleRefreshCriteriaImpact}
            disabled={s.criteriaImpactLoading}
          >
            {s.criteriaImpactLoading
              ? "Computing..."
              : s.criteriaImpact
                ? "Refresh"
                : "Load"}
          </Button>
        )}
      </div>

      {onOpenSidebar && (
        <p className="text-xs text-muted-foreground">
          To tighten or loosen the search, type in the chat sidebar.{" "}
          <button
            type="button"
            onClick={onOpenSidebar}
            className="underline cursor-pointer"
          >
            Open sidebar
          </button>
        </p>
      )}

      {s.criteriaImpact && (
        <>
          {s.criteriaImpact.criteria.length === 0 ? (
            <p className="text-xs text-muted-foreground">
              No criteria learned from calibration feedback yet.
            </p>
          ) : (
            <>
              <p className="text-xs text-muted-foreground">
                {s.criteriaImpact.base_total ?? "?"} candidates match · active
                learned criteria below.
              </p>
              <ul className="flex flex-col gap-1.5">
                {s.criteriaImpact.criteria.map((c) => {
                  const actionState = s.criteriaActionStates[c.id] ?? "idle";
                  return (
                    <li
                      key={c.id}
                      className="flex items-center justify-between gap-3 text-xs border rounded-md p-2"
                    >
                      <div className="flex flex-col gap-0.5">
                        <span
                          className={
                            c.status === "relaxed"
                              ? "text-muted-foreground line-through"
                              : ""
                          }
                        >
                          {c.label}
                        </span>
                        <span className="text-muted-foreground">
                          {c.status === "active"
                            ? c.rejected_count !== null
                              ? `${c.rejected_count} rejected`
                              : "reject count unavailable"
                            : c.rejected_count !== null
                              ? `would reject ${c.rejected_count} if reapplied`
                              : "reapply impact unavailable"}
                        </span>
                      </div>
                      <Button
                        size="sm"
                        variant="outline"
                        disabled={actionState === "working"}
                        onClick={() =>
                          c.status === "active"
                            ? s.handleRelaxCriterion(c.id)
                            : s.handleReapplyCriterion(c.id)
                        }
                      >
                        {actionState === "working"
                          ? "Working..."
                          : c.status === "active"
                            ? "Relax"
                            : "Reapply"}
                      </Button>
                    </li>
                  );
                })}
              </ul>
            </>
          )}
        </>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// SearchActionsSection — simplified accordion or preview/restore buttons
// X-ray links moved to a discreet "Advanced ›" toggle at the top.
// ---------------------------------------------------------------------------

export function SearchActionsSection({
  s,
  simplified,
}: {
  s: SourcingContext;
  simplified: boolean;
}) {
  const [showAdvanced, setShowAdvanced] = useState(false);
  const xrayQueries = s.roleBriefDetail
    ? buildXrayQueries(s.roleBriefDetail)
    : [];

  if (simplified) {
    return (
      <div className="flex flex-col gap-3">
        <div className="flex flex-wrap items-center gap-2">
          <Button
            onClick={s.handlePreview}
            disabled={s.previewLoading || !s.selectedId}
            variant="outline"
            size="sm"
          >
            {s.previewLoading ? "Searching..." : "Preview match count"}
          </Button>
          {s.selectedId && s.candidates.length === 0 && (
            <Button
              variant="outline"
              size="sm"
              onClick={s.handleRestoreLastSearch}
              disabled={
                s.restoreLoading ||
                s.previewLoading ||
                s.fetchLoading ||
                !s.selectedId
              }
            >
              {s.restoreLoading ? "Restoring..." : "Restore last search"}
            </Button>
          )}
          {xrayQueries.length > 0 && (
            <button
              type="button"
              onClick={() => setShowAdvanced((v) => !v)}
              className="text-xs text-muted-foreground hover:text-foreground underline"
            >
              Advanced {showAdvanced ? "▲" : "›"}
            </button>
          )}
        </div>

        {showAdvanced && (
          <div className="pl-3 border-l border-border flex flex-col gap-4">
            <div className="flex flex-col gap-2">
              <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
                X-ray search (open in new tab)
              </p>
              <div className="flex flex-wrap gap-2">
                {xrayQueries.map((q) => (
                  <a
                    key={q.url}
                    href={q.url}
                    target="_blank"
                    rel="noreferrer"
                    className="text-xs underline text-muted-foreground hover:text-foreground"
                  >
                    {q.label}
                  </a>
                ))}
              </div>
            </div>
            <div className="flex flex-col gap-2">
              <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
                Free &amp; low-cost sources
              </p>
              <div className="flex flex-wrap gap-2">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={s.handleSearchFreePortals}
                  disabled={s.freePortalLoading}
                >
                  {s.freePortalLoading
                    ? "Searching..."
                    : s.freePortalSearched
                      ? "Search again (GitHub, Stack Exchange, Exa)"
                      : "Search GitHub, Stack Exchange, Exa"}
                </Button>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={s.handleSearchXray}
                  disabled={s.xrayLoading}
                >
                  {s.xrayLoading
                    ? "Searching..."
                    : "Run X-ray search (LinkedIn)"}
                </Button>
              </div>
              {s.freePortalNotes.length > 0 && (
                <ul className="text-muted-foreground text-xs list-disc pl-4">
                  {s.freePortalNotes.map((note, i) => (
                    <li key={i}>{note}</li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-2">
      <div className="flex flex-wrap items-center gap-2">
        <Button
          onClick={s.handlePreview}
          disabled={s.previewLoading || !s.selectedId}
        >
          {s.previewLoading ? "Searching..." : "Preview matches"}
        </Button>
        {s.selectedId && s.candidates.length === 0 && (
          <Button
            variant="outline"
            onClick={s.handleRestoreLastSearch}
            disabled={
              s.restoreLoading ||
              s.previewLoading ||
              s.fetchLoading ||
              !s.selectedId
            }
          >
            {s.restoreLoading ? "Restoring..." : "Restore last search"}
          </Button>
        )}
        {xrayQueries.length > 0 && (
          <button
            type="button"
            onClick={() => setShowAdvanced((v) => !v)}
            className="text-xs text-muted-foreground hover:text-foreground underline"
          >
            Advanced {showAdvanced ? "▲" : "›"}
          </button>
        )}
      </div>
      {s.selectedId && s.candidates.length === 0 && (
        <p className="text-xs text-muted-foreground max-w-xl">
