                  {q.label}
                </a>
              ))}
            </div>
          </div>
          <Button
            size="sm"
            variant="outline"
            onClick={s.handleSearchFreePortals}
            disabled={s.freePortalLoading}
          >
            {s.freePortalLoading
              ? "Searching..."
              : "Search GitHub, Stack Exchange, Exa"}
          </Button>
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
