import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { useCandidateSourcing } from "./useCandidateSourcing";
import { useSourcingPagination } from "./useSourcingPagination";
import { useAddToPipeline } from "./useAddToPipeline";
import {
  FreePortalCandidateList,
  MainCandidateList,
} from "./CandidateResultsList";
import {
  CalibrationSection,
  FreePortalSection,
  RoleBriefPanel,
  SearchActionsSection,
  SourcingControlPanel,
  XrayAssistSection,
} from "./SourcingPanels";
import "../inbox/agent-h-theme.css";

// `initialRoleBriefId` is passed so this component behaves as a "sourcing
// panel" for one already-chosen role brief — no dropdown, no NL-search
// toggle, no page-level heading (the workspace page owns that). Standalone
// use at `/source-candidates` (no prop) keeps working exactly as before.
export const SourceCandidatesPage = ({
  initialRoleBriefId,
  onCandidateSaved,
  simplified = false,
  onOpenSidebar,
}: {
  initialRoleBriefId?: string;
  onCandidateSaved?: (candidateId: number, name: string) => void;
  simplified?: boolean;
  /** Called when the user clicks "Relax"/"Tighten" — caller opens the sidebar chat. */
  onOpenSidebar?: () => void;
} = {}) => {
  const embedded = Boolean(initialRoleBriefId);

  const {
    visibleCount,
    showMore,
    reset: resetPagination,
  } = useSourcingPagination();

  const s = useCandidateSourcing({
    initialRoleBriefId,
    resetPagination,
    onCandidateSaved,
  });

  const { handleAddToPipeline } = useAddToPipeline({
    selectedId: s.selectedId,
    candidateDbIds: s.candidateDbIds,
    setCandidateDbIds: s.setCandidateDbIds,
    setSaveStates: s.setSaveStates,
    onCandidateSaved,
  });

  return (
    <div
      className={
        embedded
          ? "flex flex-col gap-4"
          : "flex flex-col gap-6 max-w-3xl mx-auto p-6"
      }
    >
      {!embedded && (
        <div>
          <h1 className="text-2xl font-semibold">Source Candidates</h1>
          <p className="text-muted-foreground text-sm">
            Pick a role brief and source the best matches. Results are sorted by
            fit score. Click "Add to pipeline" on anyone worth tracking.
          </p>
        </div>
      )}

      {!embedded && (
        <div className="flex flex-col gap-2 border rounded-lg p-4">
          <Label htmlFor="nl-search">
            Paste a job description, or describe the role in your own words
          </Label>
          <textarea
            id="nl-search"
            className="border rounded-md p-2 text-sm min-h-24"
            value={s.nlText}
            onChange={(e) => s.setNlText(e.target.value)}
            placeholder="Paste the full JD here, or just: Python developer in Bengaluru with 5-8 years, currently at a startup or product company, strong in FastAPI, AWS and Docker"
          />
          <div>
            <Button onClick={s.handleNlSearch} disabled={s.nlParsing}>
              {s.nlParsing ? "Parsing..." : "Create role brief & search"}
            </Button>
          </div>
        </div>
      )}

      {!embedded && (
        <div className="flex flex-col gap-2">
          <Label htmlFor="role-brief">Or pick an existing role brief</Label>
          <select
            id="role-brief"
            className="border border-input bg-background text-foreground rounded-md h-9 px-2"
            value={s.selectedId}
            onChange={(e) => s.handleRoleBriefChange(e.target.value)}
          >
            <option value="">Select a role brief...</option>
            {s.roleBriefs.map((rb) => (
              <option key={rb.id} value={rb.id}>
                {rb.name} (#{rb.id})
              </option>
            ))}
          </select>
        </div>
      )}

      {/* Compact role brief chip — collapses to one line, expands on click */}
      <RoleBriefPanel s={s} embedded={embedded} />

      {/* One-click "Source candidates" for embedded/simplified view */}
      {simplified && s.selectedId && s.stage === "idle" && (
        <div className="flex flex-col gap-2">
          <Button
            size="lg"
            onClick={s.handleSourceCandidates}
            disabled={s.previewLoading || s.fetchLoading}
            className="self-start"
          >
            {s.previewLoading
              ? "Searching…"
              : s.fetchLoading
                ? "Fetching candidates…"
                : "Source candidates"}
          </Button>
          <p className="text-xs text-muted-foreground">
            Fetches up to 100 people matching this role — ranked by fit, top 25
            shown with a brief explanation of why they could be a match. All 100
            are saved to your pipeline.
          </p>
        </div>
      )}

      {/* Learned criteria panel — sidebar chat is primary for refinement */}
      <SourcingControlPanel
        s={s}
        embedded={embedded}
        onOpenSidebar={onOpenSidebar}
      />

      {/* Search actions: preview + restore + Advanced › (X-ray, free portals) */}
      <SearchActionsSection s={s} simplified={simplified} />

      {/* Free portal results (non-simplified standalone only) */}
      {s.selectedId && !simplified && <FreePortalSection s={s} />}

      {s.freePortalCandidates.length > 0 && (
        <FreePortalCandidateList
          s={s}
          handleAddToPipeline={handleAddToPipeline}
        />
      )}

      {/* X-ray Assist only shown on standalone route (not embedded) */}
      {!simplified && <XrayAssistSection s={s} />}

      {s.stage !== "idle" && (
        <div className="flex flex-col gap-4 border rounded-lg p-4">
          <div>
            <h2 className="text-lg font-medium">
              {s.total} match{s.total === 1 ? "" : "es"} for {s.roleBriefTitle}
            </h2>
            {s.notes.length > 0 && (
              <ul className="text-muted-foreground text-xs list-disc pl-4 mt-1">
                {s.notes.map((note, i) => (
                  <li key={i}>{note}</li>
                ))}
              </ul>
            )}
          </div>

          <CalibrationSection s={s} />

          {s.stage === "fetched" && s.candidates.length === 0 && (
            <p className="text-muted-foreground text-sm">
              No candidates matched this query.
            </p>
          )}

          {s.stage === "fetched" && s.candidates.length > 0 && (
            <MainCandidateList
              s={s}
              handleAddToPipeline={handleAddToPipeline}
              visibleCount={visibleCount}
              showMore={showMore}
              embedded={embedded}
              onOpenSidebar={onOpenSidebar}
            />
          )}
        </div>
      )}
    </div>
  );
};

SourceCandidatesPage.path = "/source-candidates";

import { Button } from "@/components/ui/button";
import { AH_CALLOUT_WARN, type OutreachPrepared } from "./sourcingTypes";

const CONNECTION_CHAR_LIMIT_OUTREACH = 300;

export function OutreachPreviewPanel({
  prepared,
  onPreparedChange,
  onConfirm,
  onCancel,
  confirming,
}: {
  prepared: OutreachPrepared;
  onPreparedChange: (next: OutreachPrepared) => void;
  onConfirm: () => void;
  onCancel: () => void;
  confirming: boolean;
}) {
  const inputClass =
    "border border-input bg-background text-foreground rounded px-2 py-1 text-xs w-full";
  const isLinkedIn =
    prepared.channel === "linkedin_connection" ||
    prepared.channel === "linkedin_inmail";
  const charCount = prepared.message_body?.length ?? 0;
  const overLimit =
    prepared.channel === "linkedin_connection" &&
    charCount > CONNECTION_CHAR_LIMIT_OUTREACH;

  return (
    <div className={AH_CALLOUT_WARN}>
      {isLinkedIn ? (
        <>
          <p className="text-xs font-medium">
            Review before sending —{" "}
            {prepared.channel === "linkedin_inmail"
              ? "LinkedIn InMail (open profile)"
              : "LinkedIn connection note"}
          </p>
          <label className="flex flex-col gap-1 text-xs text-muted-foreground">
            Message
            <textarea
              className={`${inputClass} ${overLimit ? "border-destructive" : ""}`}
              rows={prepared.channel === "linkedin_connection" ? 4 : 6}
              value={prepared.message_body ?? ""}
              onChange={(e) =>
                onPreparedChange({ ...prepared, message_body: e.target.value })
              }
            />
          </label>
          <p
            className={`text-xs ${overLimit ? "text-destructive font-medium" : "text-muted-foreground"}`}
          >
            {prepared.channel === "linkedin_connection" &&
              `${charCount}/${CONNECTION_CHAR_LIMIT_OUTREACH} chars${overLimit ? " — trim before sending" : ""}`}
          </p>
          {prepared.cap_remaining !== null && (
            <p className="text-xs text-muted-foreground">
              {prepared.cap_remaining} sends remaining today
            </p>
          )}
          {prepared.dual_channel && prepared.email_preview && (
            <div className="border-t pt-2 flex flex-col gap-2">
              <label className="flex items-center gap-2 text-xs cursor-pointer">
                <input
                  type="checkbox"
                  checked={Boolean(prepared.send_email_too)}
                  onChange={(e) =>
                    onPreparedChange({
                      ...prepared,
                      send_email_too: e.target.checked,
                    })
                  }
                />
                Also send email to {prepared.email_preview.to}
              </label>
              {prepared.send_email_too && (
                <>
                  <label className="flex flex-col gap-1 text-xs text-muted-foreground">
                    Subject
                    <input
                      className={inputClass}
                      value={prepared.email_preview.subject}
                      onChange={(e) =>
                        onPreparedChange({
                          ...prepared,
                          email_preview: {
                            ...prepared.email_preview!,
                            subject: e.target.value,
                          },
                        })
                      }
                    />
                  </label>
                  <label className="flex flex-col gap-1 text-xs text-muted-foreground">
                    Email body
                    <textarea
                      className={inputClass}
                      rows={4}
                      value={prepared.email_preview.html}
                      onChange={(e) =>
                        onPreparedChange({
                          ...prepared,
                          email_preview: {
                            ...prepared.email_preview!,
                            html: e.target.value,
                          },
                        })
                      }
                    />
                  </label>
                </>
              )}
            </div>
          )}
        </>
      ) : prepared.email_preview ? (
        <>
          <p className="text-xs font-medium">
            Review before sending to {prepared.email_preview.to}
          </p>
          <label className="flex flex-col gap-1 text-xs text-muted-foreground">
            Subject
            <input
              className={inputClass}
              value={prepared.email_preview.subject}
              onChange={(e) =>
                onPreparedChange({
                  ...prepared,
                  email_preview: {
                    ...prepared.email_preview!,
                    subject: e.target.value,
                  },
                })
              }
            />
          </label>
          <label className="flex flex-col gap-1 text-xs text-muted-foreground">
            Email body (HTML)
            <textarea
              className={inputClass}
              rows={5}
              value={prepared.email_preview.html}
              onChange={(e) =>
                onPreparedChange({
                  ...prepared,
                  email_preview: {
                    ...prepared.email_preview!,
                    html: e.target.value,
                  },
                })
              }
            />
          </label>
        </>
      ) : (
        <p className="text-xs text-muted-foreground">Outreach ready to send.</p>
      )}
      <div className="flex gap-2">
        <Button
          size="sm"
          disabled={confirming || overLimit}
          onClick={onConfirm}
        >
          {confirming ? "Sending..." : "Approve & send"}
        </Button>
        <Button
          size="sm"
          variant="outline"
          disabled={confirming}
          onClick={onCancel}
        >
          Cancel
        </Button>
      </div>
    </div>
  );
}

import { Link } from "react-router";
import { Button } from "@/components/ui/button";
import {
  AH_CALLOUT_WARN,
  sourcingPanelClass,
  getInitials,
  titleCase,
  type MustHaveCheck,
  type PdlCandidate,
} from "./sourcingTypes";
import type { useCandidateSourcing } from "./useCandidateSourcing";
import { CandidateQuickActionBar } from "./CandidateQuickActionBar";

type SourcingContext = ReturnType<typeof useCandidateSourcing>;

export function MainCandidateList({
  s,
  handleAddToPipeline,
  visibleCount,
  showMore,
  embedded,
  onOpenSidebar,
}: {
  s: SourcingContext;
  handleAddToPipeline: (candidate: PdlCandidate) => void;
  visibleCount: number;
  showMore: (total: number) => void;
  embedded: boolean;
  onOpenSidebar?: () => void;
}) {
  return (
    <div className="flex flex-col gap-3">
      {/* Funnel bar + sort controls */}
      {s.stage === "fetched" && s.candidates.length > 0 && (
        <div
          className={sourcingPanelClass(
            embedded,
            "flex items-center justify-between gap-3 flex-wrap p-3",
            "md",
          )}
        >
          <div className="flex items-center gap-3 flex-wrap">
            <div className="text-sm text-muted-foreground">
              {s.totalMatchesAll !== null
                ? `${s.totalMatchesAll.toLocaleString()} candidates match · `
                : ""}
              <span className="text-foreground font-medium">
                {s.candidates.length} fetched
              </span>
              {s.candidates.length > 25 && (
                <span className="text-muted-foreground">
                  {" "}
                  · showing top 25 first
                </span>
              )}
            </div>
            <Button
              size="sm"
              variant="outline"
              onClick={() => {
                if (onOpenSidebar) {
                  onOpenSidebar();
                } else {
                  s.controlPanelRef.current?.scrollIntoView({
                    behavior: "smooth",
                    block: "center",
                  });
                }
              }}
            >
              Relax criteria
            </Button>
            <Button
              size="sm"
              variant="outline"
              onClick={() => {
                if (onOpenSidebar) {
                  onOpenSidebar();
                } else {
                  s.controlPanelRef.current?.scrollIntoView({
                    behavior: "smooth",
                    block: "center",
                  });
                }
              }}
            >
              Tighten
            </Button>
          </div>
          <div className="flex items-center gap-3 flex-wrap">
            <label className="flex items-center gap-2 text-xs text-muted-foreground">
              Sort by
              <select
                className="border border-input bg-background text-foreground rounded-md h-8 px-2 text-xs"
                value={s.sortField}
                onChange={(e) => s.setSortField(e.target.value as any)}
              >
                <option value="default">Default order</option>
                <option value="name">Name (A&ndash;Z)</option>
                <option value="location">Location</option>
              </select>
            </label>
            <label className="flex items-center gap-2 text-xs bg-accent/40 rounded-md px-2 py-1.5 cursor-pointer">
              <input
                type="checkbox"
                checked={s.sortByMatchEvidence}
                onChange={(e) => s.setSortByMatchEvidence(e.target.checked)}
              />
              Sort by match evidence
            </label>
          </div>
        </div>
      )}

      {s.stage === "fetched" && s.candidates.length > 0 && (
        <div className="flex items-center justify-between gap-3 -mt-2">
          <p className="text-xs text-muted-foreground">
            {s.candidates.some((c) => c._llm_rank != null)
              ? "Top 25 ranked by AI fit — best matches first."
              : s.candidates.some((c) => typeof c._match_score === "number")
                ? "Sorted by match score (highest first)."
                : "Candidates shown in discovery order."}{" "}
          </p>
          {s.bulkSelected.size > 0 && (
            <div className="flex items-center gap-2">
              <span className="text-xs text-muted-foreground">
                {s.bulkSelected.size} selected
              </span>
              <Button
                size="sm"
                variant="outline"
                onClick={() => s.setBulkSelected(new Set())}
              >
                Clear
              </Button>
              <Button
                size="sm"
                disabled={s.bulkPreparing}
                onClick={s.handleBulkPrepareOutreach}
              >
                {s.bulkPreparing
                  ? "Preparing..."
                  : `Prepare outreach (${s.bulkSelected.size})`}
              </Button>
            </div>
          )}
        </div>
      )}

      {/* Candidate cards */}
      {(() => {
        const hasLlmRanks = s.candidates.some((c) => c._llm_rank != null);
        const ranked25Count = hasLlmRanks
          ? s.candidates.filter((c) => c._llm_rank != null).length
          : 0;
        return s.candidates.slice(0, visibleCount).map((candidate, idx) => {
          const saveState = s.saveStates[candidate.id] ?? "idle";
          const candidateId = s.candidateDbIds[candidate.id];
          const evidenceState = s.evidenceStates[candidate.id] ?? "idle";
          const evidenceResult = s.evidenceResults[candidate.id];
          const isFirstUnranked =
            hasLlmRanks && candidate._llm_rank == null && idx === ranked25Count;

          return (
            <div key={candidate.id}>
              {isFirstUnranked && (
                <div className="flex items-center gap-2 py-2 my-1">
                  <div className="flex-1 border-t border-dashed" />
                  <span className="text-xs text-muted-foreground shrink-0">
                    Additional candidates ({s.candidates.length - ranked25Count}{" "}
                    more)
                  </span>
                  <div className="flex-1 border-t border-dashed" />
                </div>
              )}
              <div className="border rounded-md p-3 flex flex-col gap-3">
                <div className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    aria-label={`Select ${candidate.full_name ?? candidate.id} for bulk outreach`}
                    checked={s.bulkSelected.has(candidate.id)}
                    onChange={(e) => {
                      s.setBulkSelected((prev) => {
                        const next = new Set(prev);
                        if (e.target.checked) next.add(candidate.id);
                        else next.delete(candidate.id);
                        return next;
                      });
                    }}
                    className="w-4 h-4 shrink-0"
                  />
                  <div className="flex-1">
                    <CandidateQuickActionBar emails={candidate.emails} />
                  </div>
                </div>
                <div className="flex items-start justify-between gap-3">
                  <div className="flex gap-3">
                    <div
                      className="w-10 h-10 rounded-full bg-muted flex items-center justify-center text-sm font-medium text-muted-foreground shrink-0"
                      aria-hidden="true"
                    >
                      {getInitials(candidate.full_name)}
                    </div>
                    <div>
                      <div className="font-medium">
                        {candidateId ? (
                          <Link
                            to={`/candidates/${candidateId}/show`}
                            className="hover:underline"
                          >
                            {titleCase(candidate.full_name) ??
                              "(name unavailable)"}
                          </Link>
                        ) : (
                          (titleCase(candidate.full_name) ??
                          "(name unavailable)")
                        )}
                      </div>
                      <div className="text-sm text-muted-foreground">
                        {titleCase(candidate.job_title)}
                        {candidate.job_company_name
                          ? ` at ${titleCase(candidate.job_company_name)}`
                          : ""}
                      </div>
                      <div className="text-sm text-muted-foreground">
                        {titleCase(candidate.location_name)}
                      </div>
                      <div className="flex items-center gap-2 mt-1">
                        {candidate.linkedin_url && (
                          <a
                            href={`https://${candidate.linkedin_url}`}
                            target="_blank"
                            rel="noreferrer"
                            className="text-xs ah-link"
                          >
                            LinkedIn
                          </a>
                        )}
                      </div>
                      {candidate.skills && candidate.skills.length > 0 && (
                        <div className="text-xs text-muted-foreground mt-1">
                          Skills: {candidate.skills.slice(0, 10).join(", ")}
                        </div>
                      )}
                      {candidate._llm_why_fit && (
                        <div className="text-xs mt-1 text-muted-foreground italic">
                          {candidate._llm_why_fit}
                        </div>
                      )}
                      {candidate._match_evidence && (
                        <div className={`text-xs mt-1 ${AH_CALLOUT_WARN}`}>
                          {candidate._match_evidence}
                        </div>
                      )}
                    </div>
                  </div>

                  <Button
                    variant={saveState === "saved" ? "outline" : "default"}
                    disabled={saveState === "saving" || saveState === "saved"}
                    onClick={() => handleAddToPipeline(candidate)}
                    className="shrink-0"
                  >
                    {saveState === "saved"
                      ? "Added"
                      : saveState === "saving"
                        ? "Adding..."
                        : "Add to pipeline"}
                  </Button>
                </div>

                {/* Why this could be a fit — auto-expanded for scored candidates */}
                {s.selectedId && (
                  <div className="border-t pt-2">
                    <button
                      type="button"
                      onClick={() => {
                        const isOpen = Boolean(
                          s.evidenceExpanded[candidate.id],
                        );
                        s.setEvidenceExpanded((prev) => ({
                          ...prev,
                          [candidate.id]: !isOpen,
                        }));
                        if (
                          !isOpen &&
                          !evidenceResult &&
                          evidenceState === "idle"
                        ) {
                          s.handleDiscoveryEvidence(candidate);
                        }
                      }}
                      className="text-xs ah-link flex items-center gap-1"
                    >
                      Why this could be a fit
                      <span aria-hidden="true">
                        {s.evidenceExpanded[candidate.id] ? "▲" : "▼"}
                      </span>
                    </button>
                    {s.evidenceExpanded[candidate.id] && (
                      <div className="mt-2 flex flex-col gap-1">
                        {evidenceState === "loading" && (
                          <p className="text-xs text-muted-foreground">
                            Gathering evidence...
                          </p>
                        )}
                        {(() => {
                          const checks = evidenceResult;
                          if (evidenceState === "loading" || !checks)
                            return null;
                          if (checks.length === 0) {
                            return (
                              <p className="text-xs text-muted-foreground">
                                No specific evidence available for this
                                candidate.
                              </p>
                            );
                          }
                          return checks.map((m: MustHaveCheck, i: number) => (
                            <div
                              key={i}
                              className="text-xs flex items-center gap-1.5"
                            >
                              <span
                                className={
                                  m.status === "found"
                                    ? "ah-text-good"
                                    : m.status === "inferred"
                                      ? "ah-text-warn"
                                      : "ah-text-danger"
                                }
                                aria-hidden="true"
                              >
                                {m.status === "found"
                                  ? "✓"
                                  : m.status === "inferred"
                                    ? "~"
                                    : "✗"}
                              </span>
                              <span>{m.requirement}</span>
                            </div>
                          ));
                        })()}
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          );
        });
      })()}

      {s.stage === "fetched" && visibleCount < s.candidates.length && (
        <Button variant="outline" onClick={() => showMore(s.candidates.length)}>
          Show more ({s.candidates.length - visibleCount} remaining)
        </Button>
      )}

      {s.stage === "fetched" && (
        <div className="flex flex-col gap-1">
          <Button
            variant="outline"
            onClick={s.handleSearchWider}
            disabled={!s.canSearchWider || s.wideningLoading}
          >
            {s.wideningLoading
              ? "Fetching more..."
              : s.canSearchWider
                ? `Search wider (${s.candidates.length} of ${s.total} reviewed)`
                : `All ${s.total} match(es) reviewed`}
          </Button>
          <p className="text-muted-foreground text-xs">
            Pulls the next batch further down this same search — not a
            different, looser search.
          </p>
        </div>
      )}
    </div>
  );
}

import { Button } from "@/components/ui/button";
import { AH_CALLOUT_WARN, type PdlCandidate } from "./sourcingTypes";
import type { useCandidateSourcing } from "./useCandidateSourcing";
import { CalibrationFeedbackWidget } from "./CalibrationFeedbackWidget";
import { CandidateActionsPanel } from "./CandidateActionsPanel";
import { CandidateQuickActionBar } from "./CandidateQuickActionBar";
import { OutreachPreviewPanel } from "./OutreachPreviewPanel";

type SourcingContext = ReturnType<typeof useCandidateSourcing>;

export function FreePortalCandidateList({
  s,
  handleAddToPipeline,
}: {
  s: SourcingContext;
  handleAddToPipeline: (candidate: PdlCandidate) => void;
}) {
  if (s.freePortalCandidates.length === 0) return null;
  return (
    <ul className="flex flex-col gap-2">
      {s.freePortalCandidates.map((candidate) => {
        const saveState = s.saveStates[candidate.id] ?? "idle";
        const candidateId = s.candidateDbIds[candidate.id];
        const contactState = s.contactEnrichStates[candidate.id] ?? "idle";
        const contactResult = s.contactEnrichResults[candidate.id];
        const devSignalState = s.devSignalEnrichStates[candidate.id] ?? "idle";
        const devSignalResult = s.devSignalEnrichResults[candidate.id];
        const interviewState = s.interviewStates[candidate.id] ?? "idle";
        const interviewResult = s.interviewResults[candidate.id];
        const resumeState = s.resumeStates[candidate.id] ?? "idle";
        const resumeInfo = s.resumeInfos[candidate.id];
        const calibEntryState =
          s.calibrationEntryStates[candidate.id] ?? "idle";
        const calibSubmitted = calibEntryState === "submitted";

        return (
          <li
            key={candidate.id}
            className="flex flex-col gap-3 border rounded-md p-3 text-sm"
          >
            <CandidateQuickActionBar
              emails={candidate.emails}
              linkedInUrl={candidate.linkedin_url}
              isLinkedInSource={Boolean(candidate.linkedin_url)}
              outreachState={s.outreachStates[candidate.id] ?? "idle"}
              onLinkedInOutreach={() => s.handleOutreachFromSearch(candidate)}
            />
            <div className="flex items-center justify-between gap-3">
              <div className="flex flex-col gap-0.5">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="font-medium">
                    {candidate.full_name ?? candidate.id}
                  </span>
                  <span className="text-xs uppercase text-muted-foreground border rounded px-1">
                    {candidate._source_vendor}
                  </span>
                  {candidate._all_portals &&
                    candidate._all_portals.length > 1 &&
                    candidate._all_portals
                      .filter((p) => p.vendor !== candidate._source_vendor)
                      .map((p, i) => (
                        <span
                          key={i}
                          className="text-xs uppercase text-muted-foreground border rounded px-1"
                        >
                          +{p.vendor}
                        </span>
                      ))}
                  {(candidate._source_vendor === "huggingface" ||
                    candidate._source_vendor === "kaggle" ||
                    candidate._source_vendor === "exa") &&
                    s.roleBriefDetail?.location &&
                    !/remote/i.test(s.roleBriefDetail.location) && (
                      <span className="text-xs ah-text-warn border border-current rounded px-1">
                        location unverified
                      </span>
                    )}
                </div>
                {candidate.job_title && (
                  <span className="text-muted-foreground text-xs">
                    {candidate.job_title}
                  </span>
                )}
                {candidate.location_name && (
                  <span className="text-muted-foreground text-xs">
                    {candidate.location_name}
                  </span>
                )}
                {candidate._match_evidence && (
                  <div className={`text-xs mt-1 ${AH_CALLOUT_WARN}`}>
                    Why this surfaced: {candidate._match_evidence}
                  </div>
                )}
                <div className="flex gap-2 flex-wrap">
                  {candidate._portal_url && (
                    <a
                      href={candidate._portal_url}
                      target="_blank"
                      rel="noreferrer"
                      className="text-xs underline text-muted-foreground"
                    >
                      View profile
                    </a>
                  )}
                  {candidate._all_portals
                    ?.filter((p) => p.url && p.url !== candidate._portal_url)
                    .map((p, i) => (
                      <a
                        key={i}
                        href={p.url ?? undefined}
                        target="_blank"
                        rel="noreferrer"
                        className="text-xs underline text-muted-foreground"
                      >
                        View on {p.vendor}
                      </a>
                    ))}
                </div>
              </div>
              <Button
                size="sm"
                variant="outline"
                disabled={saveState !== "idle" || candidate._already_saved}
                onClick={() => handleAddToPipeline(candidate)}
              >
                {candidate._already_saved
                  ? "Already saved"
                  : saveState === "saving"
                    ? "Saving..."
                    : saveState === "saved"
                      ? "Saved"
                      : "Add to pipeline"}
              </Button>
            </div>

            {candidateId && (
              <CandidateActionsPanel
                candidate={candidate}
                showFullProfile={false}
                contactState={contactState}
                contactResult={contactResult}
                onEnrichContact={() => s.handleEnrichContact(candidate)}
                devSignalState={devSignalState}
                devSignalResult={devSignalResult}
                onEnrichDevSignals={() => s.handleEnrichDevSignals(candidate)}
                fullProfileState="idle"
                fullProfile={undefined}
                fullProfileIsOpen={false}
                onViewFullProfile={() => {}}
                interviewState={interviewState}
                interviewResult={interviewResult}
                onCreateBookingLink={() =>
                  s.handlePrepareBookingLink(candidate)
                }
                bookingAwaitingConfirm={!!s.bookingPrepared[candidate.id]}
                bookingEmailPreview={
                  s.bookingPrepared[candidate.id]
                    ? s.bookingPrepared[candidate.id]!.email_preview
                    : undefined
                }
                onBookingPreviewChange={(next) =>
                  s.setBookingPrepared((prev) => {
                    const current = prev[candidate.id];
                    if (!current) return prev;
                    return {
                      ...prev,
                      [candidate.id]: { ...current, email_preview: next },
                    };
                  })
                }
                onConfirmSendBookingLink={() =>
                  s.handleConfirmSendBookingLink(candidate)
                }
                onCancelBookingPreview={() =>
                  s.handleCancelBookingPrepared(String(candidate.id))
                }
                bookingSendState={s.bookingSendStates[candidate.id] ?? "idle"}
                resumeState={resumeState}
                resumeInfo={resumeInfo}
                onRequestResume={() => s.handleRequestResume(candidate)}
                onCheckForResume={() => s.handleCheckForResume(candidate)}
                resumeEmailPreview={s.resumeEmailPreviews[candidate.id]}
                onResumePreviewChange={(next) =>
                  s.setResumeEmailPreviews((prev) => ({
                    ...prev,
                    [candidate.id]: next,
                  }))
                }
                onConfirmSendResume={() =>
                  s.handleConfirmSendResumeRequest(candidate)
                }
                onCancelResumePreview={() =>
                  s.handleCancelResumePreview(String(candidate.id))
                }
                resumeSendState={s.resumeSendStates[candidate.id] ?? "idle"}
                hasEmail={
                  Boolean(candidate.emails?.length) ||
                  Boolean(s.contactEnrichResults[candidate.id]?.email)
                }
                candidateLinkedInUrl={candidate.linkedin_url}
                onPrepareOutreach={() => s.handlePrepareOutreach(candidate)}
                outreachState={s.outreachStates[candidate.id] ?? "idle"}
              />
            )}
            {candidateId && s.outreachPrepared[candidate.id] && (
              <OutreachPreviewPanel
                prepared={s.outreachPrepared[candidate.id]}
                onPreparedChange={(next) =>
                  s.setOutreachPrepared((prev) => ({
                    ...prev,
                    [candidate.id]: next,
                  }))
                }
                onConfirm={() => s.handleConfirmSendOutreach(candidate)}
                onCancel={() =>
                  s.setOutreachPrepared((prev) => {
                    const next = { ...prev };
                    delete next[candidate.id];
                    return next;
                  })
                }
                confirming={s.outreachSendStates[candidate.id] === "loading"}
              />
            )}

            <CalibrationFeedbackWidget
              reason={s.calibrationReasons[candidate.id] ?? ""}
              onReasonChange={(value) =>
                s.setCalibrationReasons((prev) => ({
                  ...prev,
                  [candidate.id]: value,
                }))
              }
              submitted={calibSubmitted}
              entryState={calibEntryState}
              onSubmitJudgment={(fit) =>
                s.handleSubmitCalibrationJudgment(candidate, fit)
              }
              contextualizeState={s.contextualizeStates[candidate.id]}
              contextualizeResult={s.contextualizeResults[candidate.id]}
              applyState={s.applyStates[candidate.id] ?? "idle"}
              onApplyCriterion={() => s.handleApplyCriterion(candidate.id)}
            />
          </li>
        );
      })}
    </ul>
  );
}

