// See docs/adr/ADR-617f-phase-c-human-in-the-loop-approval.md

import type { QueryClient } from "@tanstack/react-query";
import type { Identifier } from "ra-core";
import type { CrmDataProvider } from "../providers/types";
import type { Deal, RoleConversationTurn } from "../types";
import {
  type ConversationTurnMetadata,
  getActionTier,
  isLeavesPlatformAction,
} from "./agentActionTiers";

type ParsedCommand = Awaited<ReturnType<CrmDataProvider["parseAgentCommand"]>>;

export type ParseCandidateRef = { id: number; name: string };

export type RoleAgentOrchestratorDeps = {
  dealId: string;
  deal: Deal | undefined;
  openDeals: Deal[];
  dataProvider: CrmDataProvider;
  queryClient: QueryClient;
  navigate: (path: string) => void;
  invalidateTranscript: () => void;
  pipelineCandidates?: ParseCandidateRef[];
  selectedCandidates?: ParseCandidateRef[];
};

function turnIdempotencyKey(dealId: string, suffix: string) {
  return `${dealId}:${suffix}:${crypto.randomUUID()}`;
}

function resolveCandidateId(
  parsed: ParsedCommand,
  selectedCandidates: ParseCandidateRef[],
): number | null {
  if (parsed.candidate_id != null) return parsed.candidate_id;
  if (parsed.use_selected_candidates && selectedCandidates.length === 1) {
    return selectedCandidates[0].id;
  }
  return null;
}

async function appendRecruiterTurn(
  deps: RoleAgentOrchestratorDeps,
  content: string,
  metadata: ConversationTurnMetadata,
  inReplyTo?: Identifier | null,
): Promise<RoleConversationTurn> {
  return (await deps.dataProvider.createRoleConversationTurn(deps.dealId, {
    content,
    metadata,
    in_reply_to: inReplyTo ?? null,
    idempotency_key: turnIdempotencyKey(deps.dealId, "recruiter"),
  })) as RoleConversationTurn;
}

async function appendAgentTurn(
  deps: RoleAgentOrchestratorDeps,
  content: string,
  metadata: ConversationTurnMetadata,
  inReplyTo?: Identifier | null,
): Promise<RoleConversationTurn> {
  return (await deps.dataProvider.appendAgentConversationTurn(deps.dealId, {
    content,
    metadata,
    in_reply_to: inReplyTo ?? null,
    idempotency_key: turnIdempotencyKey(deps.dealId, "agent"),
  })) as RoleConversationTurn;
}

async function executeReversibleOrRead(
  deps: RoleAgentOrchestratorDeps,
  parsed: ParsedCommand,
): Promise<{ summary: string; undo?: ConversationTurnMetadata["undo"] }> {
  if (parsed.action === "create_role") {
    deps.navigate("/");
    return { summary: parsed.explanation };
  }

  const sourcingActions = [
    "start_sourcing",
    "calibration_yes",
    "show_more_like_this",
    "relax_and_research",
  ];
  if (deps.deal?.sourcing_paused && sourcingActions.includes(parsed.action)) {
    return {
      summary:
        "Sourcing is paused for this role — resume it from the role header before continuing.",
    };
  }

  if (parsed.action === "start_sourcing") {
    const batch = await deps.dataProvider.startCalibrationSourcing(deps.dealId);
    if (batch.candidates.length === 0) {
      return {
        summary:
          "I couldn't find candidates to show right now. Try relaxing the criteria or searching again.",
      };
    }
    void appendCalibrationCardTurns(deps, batch);
    // Surface Talent Bench note when saved search results were reused.
    const prefix = batch.bench_note ? `${batch.bench_note} ` : "";
    return {
      summary: `${prefix}Found ${batch.pool_size} candidates. Here are the top ${batch.candidates.length}:`,
    };
  }

  if (
    parsed.action === "calibration_yes" ||
    parsed.action === "show_more_like_this"
  ) {
    const batch = await deps.dataProvider.calibrationNextBatch(deps.dealId);
    if (batch.pool_exhausted && batch.candidates.length === 0) {
      return {
        summary:
          "I've shown everyone in the current pool. Say 'relax and search again' to widen the criteria, or 'start sourcing' to pull a fresh batch.",
      };
    }
    void appendCalibrationCardTurns(deps, batch);
    return {
      summary: batch.pool_exhausted
        ? `Last ${batch.candidates.length} from the current pool:`
        : `Here are the next ${batch.candidates.length}:`,
    };
  }

  if (parsed.action === "calibration_no") {
    await appendAgentTurn(
      deps,
      "Got it — what didn't fit? (e.g. seniority, location, company size, tech stack)",
      { kind: "calibration_question" },
    );
    deps.invalidateTranscript();
    return { summary: "" };
  }

  if (parsed.action === "relax_and_research") {
    const batch = await deps.dataProvider.startCalibrationSourcing(deps.dealId);
    if (batch.candidates.length === 0) {
      return {
        summary:
          "Searched with wider criteria but still found no new candidates. Try adjusting the role requirements.",
      };
    }
    void appendCalibrationCardTurns(deps, batch);
    const prefix = batch.bench_note
      ? `${batch.bench_note} `
      : "Searching with wider criteria… ";
    return {
      summary: `${prefix}Here are the top ${batch.candidates.length} from a fresh pull:`,
    };
  }

  if (parsed.action === "show_roles") {
    deps.navigate("/");
    return { summary: parsed.explanation };
  }

  if (parsed.action === "show_candidates" && parsed.deal_id != null) {
    deps.navigate(`/roles/${parsed.deal_id}`);
    return { summary: parsed.explanation };
  }

  if (parsed.action === "continue_sourcing" && parsed.deal_id != null) {
    const result = await deps.dataProvider.continueSourcingForDeal(
      parsed.deal_id,
    );
    const filteredNote =
      result.filteredCount > 0
        ? `, ${result.filteredCount} filtered as not relevant`
        : "";
    // Show found candidates as calibration-style cards so the recruiter
    // can explicitly add each one to the pipeline (T1: no auto-save).
    if (result.candidates.length > 0) {
      const top5 = result.candidates.slice(0, 5);
      void appendCalibrationCardTurns(deps, {
        candidates: top5.map((c) => ({
          external_id: c.id,
          name: c.full_name ?? `Candidate ${c.id}`,
          headline:
            [c.job_title, c.job_company_name].filter(Boolean).join(" at ") ||
            null,
          why_fit: "",
          match_score: null,
          linkedin_url: c.linkedin_url ?? null,
          from_bench: false,
        })),
        pool_size: result.foundCount,
        cursor: 0,
        pool_exhausted: true,
      });
    }
    return {
      summary:
        result.foundCount === 0
          ? `No candidates found${filteredNote}.`
          : `Found ${result.foundCount} candidate${result.foundCount === 1 ? "" : "s"}${filteredNote} — click "Add to pipeline" on any card to save.`,
    };
  }

  if (parsed.action === "relax_criterion" && parsed.criterion_id != null) {
    await deps.dataProvider.relaxLearnedCriterion(parsed.criterion_id);
    deps.queryClient.invalidateQueries({
      queryKey: ["inbox_per_deal_signals"],
    });
    return {
      summary: parsed.explanation,
      undo: {
        action: "note_only",
        params: { criterion_id: parsed.criterion_id },
      },
    };
  }

  if (parsed.action === "unknown") {
    return { summary: parsed.explanation };
  }

  return {
    summary:
      parsed.explanation ||
      "I understood the request but can't run that action in this context yet.",
  };
}

async function buildTier3ProposalMetadata(
  deps: RoleAgentOrchestratorDeps,
  parsed: ParsedCommand,
): Promise<ConversationTurnMetadata> {
  const selectedCandidates = deps.selectedCandidates ?? [];
  const candidateId = resolveCandidateId(parsed, selectedCandidates);
  const dealId = (parsed.deal_id as number | undefined) ?? Number(deps.dealId);

  const params: Record<string, unknown> = {
    deal_id: dealId,
    criterion_id: parsed.criterion_id,
    use_selected_candidates: parsed.use_selected_candidates,
    candidate_id: candidateId,
  };

  const base: ConversationTurnMetadata = {
    kind: "proposal",
    tier: "leaves_platform",
    action: parsed.action,
    status: "pending",
    explanation: parsed.explanation,
    params,
  };

  if (parsed.action === "request_resume" && candidateId && dealId) {
    try {
      const result = await deps.dataProvider.prepareRequestResume(
        candidateId,
        dealId,
      );
      return {
        ...base,
        email_preview:
          result.email_preview as ConversationTurnMetadata["email_preview"],
      };
    } catch (error) {
      return {
        ...base,
        explanation: `${parsed.explanation} (${error instanceof Error ? error.message : "Couldn't prepare the email preview"})`,
      };
    }
  }

  if (parsed.action === "send_first_outreach" && candidateId && dealId) {
    try {
      const result = await deps.dataProvider.prepareFirstOutreach(
        candidateId,
        dealId,
      );
      if (result.channel === "email" && result.email_preview) {
        return {
          ...base,
          email_preview:
            result.email_preview as ConversationTurnMetadata["email_preview"],
        };
      }
      if (
        (result.channel === "linkedin_connection" ||
          result.channel === "linkedin_inmail") &&
        result.message_body &&
        result.linkedin_provider_id
      ) {
        return {
          ...base,
          linkedin_preview: {
            channel: result.channel,
            message_body: result.message_body,
            char_count: result.char_count ?? result.message_body.length,
            is_open_profile: result.is_open_profile ?? false,
            linkedin_provider_id: result.linkedin_provider_id,
            cap_remaining: result.cap_remaining ?? undefined,
            drafted_by: result.drafted_by,
          } as ConversationTurnMetadata["linkedin_preview"],
        };
      }
      return base;
    } catch (error) {
      return {
        ...base,
        explanation: `${parsed.explanation} (${error instanceof Error ? error.message : "Couldn't prepare the outreach preview"})`,
      };
    }
  }

  if (isLeavesPlatformAction(parsed.action) && !candidateId) {
    return {
      ...base,
      explanation: `${parsed.explanation} (Select a candidate in the table or name someone from the pipeline so I know who to contact.)`,
    };
  }

  return base;
}

// TASK-002: JD paste detection and conversational intake in role transcript.
// Called when the recruiter pastes a long JD-like text in the role command bar.
// Parses it with Claude, updates the deal, and asks clarifying questions in transcript.
export async function dispatchJdPasteCommand(
  deps: RoleAgentOrchestratorDeps,
  jdText: string,
): Promise<void> {
  // Append the recruiter's text as a command turn (truncated for display).
  const displayText =
    jdText.length > 300
      ? `${jdText.slice(0, 300)}… (${jdText.length - 300} more chars)`
      : jdText;
  await appendRecruiterTurn(deps, displayText, { kind: "command" });

  // Parse the JD.
  let parsed: Awaited<ReturnType<typeof deps.dataProvider.parseJobDescription>>;
  try {
    parsed = await deps.dataProvider.parseJobDescription(jdText);
  } catch (error) {
    await appendAgentTurn(
      deps,
      `Couldn't parse that job description: ${error instanceof Error ? error.message : "unknown error"}. Try shortening it or pasting just the key requirements.`,
      { kind: "result", status: "executed" },
    );
    deps.invalidateTranscript();
    return;
  }

  // Update the deal record with parsed structured fields.
  try {
    await deps.dataProvider.update("deals", {
      id: deps.dealId,
      data: {
        name: parsed.title ?? deps.deal?.name,
        seniority: parsed.seniority,
        location: parsed.location,
        industry: parsed.industry,
        years_experience_min: parsed.years_experience_min,
        years_experience_max: parsed.years_experience_max,
        required_skills: parsed.required_skills,
        must_have_keywords: parsed.must_have_keywords,
        nice_to_have_keywords: parsed.nice_to_have_keywords,
        preference_tiers: parsed.preference_tiers,
        clarifying_questions: parsed.clarifying_questions,
        clarifying_questions_dismissed: false,
      },
      previousData: deps.deal ?? {},
    });
    deps.queryClient.invalidateQueries({ queryKey: ["deals", deps.dealId] });
  } catch {
    // Non-fatal: still show the summary even if the update fails.
  }

  // Build a readable summary of what was parsed.
  const skillsSummary =
    (parsed.required_skills ?? parsed.must_have_keywords ?? [])
      .slice(0, 5)
      .join(", ") || "not specified";
  const expSummary =
    parsed.years_experience_min != null || parsed.years_experience_max != null
      ? `${parsed.years_experience_min ?? 0}–${parsed.years_experience_max ?? "∞"} years`
      : "not specified";
  const summaryLines = [
    `**Role:** ${parsed.title || "untitled"}`,
    `**Seniority:** ${parsed.seniority || "not specified"}`,
    `**Location:** ${parsed.location || "not specified"}`,
    `**Experience:** ${expSummary}`,
    `**Key skills:** ${skillsSummary}`,
  ].join("\n");

  // Build the agent response with summary + questions.
  const questionsBlock = parsed.clarifying_questions?.length
    ? `\n\nA few things I'm less sure about:\n${parsed.clarifying_questions.map((q) => `• ${q}`).join("\n")}\n\nAnswer any of these, or say 'start sourcing' when you're ready.`
    : "\n\nEverything looks clear. Say 'start sourcing' to begin.";

  const agentContent = `Got it \u2014 here's what I parsed:\n\n${summaryLines}${questionsBlock}`;

  await appendAgentTurn(deps, agentContent, {
    kind: "result",
    action: "create_role",
    status: "executed",
  });
  deps.invalidateTranscript();
}

// TASK-003: After sourcing runs (continue_sourcing), append candidate card
// turns to the transcript so the recruiter sees fit signals inline.
export async function appendCandidateCardTurns(
  deps: RoleAgentOrchestratorDeps,
  candidates: Array<{
    id: number;
    first_name: string | null;
    last_name: string | null;
    job_title: string | null;
    job_company_name: string | null;
    linkedin_url: string | null;
    match_score: number | null;
    must_haves_check?: Array<{
      label: string;
      status: "found" | "inferred" | "missing";
    }>;
  }>,
): Promise<void> {
  const dealId = Number(deps.dealId);
  const top = candidates.slice(0, 5);
  for (const c of top) {
    const name =
      [c.first_name, c.last_name].filter(Boolean).join(" ") ||
      `Candidate #${c.id}`;
    const headline = [c.job_title, c.job_company_name]
      .filter(Boolean)
      .join(" at ");
    await appendAgentTurn(
      deps,
      `${name}${headline ? ` — ${headline}` : ""}${c.match_score != null ? ` (match ${Math.round(c.match_score * 100)}%)` : ""}`,
      {
        kind: "candidate_card",
        candidate_card: {
          candidate_id: c.id,
          deal_id: dealId,
          name,
          headline: headline || null,
          linkedin_url: c.linkedin_url,
          match_score: c.match_score,
          must_haves: (c.must_haves_check ?? []).slice(0, 3),
        },
      },
    );
  }
  deps.invalidateTranscript();
}

// Loop B calibration: append candidate cards from a CalibrationBatch.
// Uses external_id (vendor id) as the card identifier since these candidates
// are not yet saved to deal_candidates (cache ≠ pipeline).
async function appendCalibrationCardTurns(
  deps: RoleAgentOrchestratorDeps,
  batch: Awaited<ReturnType<typeof deps.dataProvider.calibrationNextBatch>>,
): Promise<void> {
  const dealId = Number(deps.dealId);
  for (const c of batch.candidates) {
    await appendAgentTurn(
      deps,
      `${c.name}${c.headline ? ` — ${c.headline}` : ""}${c.why_fit ? `\n${c.why_fit}` : ""}`,
      {
        kind: "candidate_card",
        candidate_card: {
          candidate_id: 0,
          deal_id: dealId,
          name: c.name,
          headline: c.headline,
          linkedin_url: c.linkedin_url ?? null,
          location_name: c.location_name ?? null,
          match_score: c.match_score,
          must_haves: (c.must_haves ?? []).slice(0, 5),
          calibration_external_id: c.external_id,
          why_fit: c.why_fit,
        },
      },
    );
  }
  deps.invalidateTranscript();
}

// TASK-004: After a candidate is added to the pipeline, propose outreach
// in the transcript (Tier 3 gate — recruiter must approve before sending).
export async function proposeOutreachAfterPipelineAdd(
  deps: RoleAgentOrchestratorDeps,
  candidateId: number,
  candidateName: string,
): Promise<void> {
  const dealId = Number(deps.dealId);

  let metadata: ConversationTurnMetadata;
  try {
    const result = await deps.dataProvider.prepareFirstOutreach(
      candidateId,
      dealId,
    );

    const base: ConversationTurnMetadata = {
      kind: "proposal",
      tier: "leaves_platform",
      action: "send_first_outreach",
      status: "pending",
      explanation: `${candidateName} is now in the pipeline. Ready to reach out?`,
      params: { candidate_id: candidateId, deal_id: dealId },
    };

    if (
      (result.channel === "linkedin_connection" ||
        result.channel === "linkedin_inmail") &&
      result.message_body &&
      result.linkedin_provider_id
    ) {
      metadata = {
        ...base,
        linkedin_preview: {
          channel: result.channel,
          message_body: result.message_body,
          char_count: result.char_count ?? result.message_body.length,
          is_open_profile: result.is_open_profile ?? false,
          linkedin_provider_id: result.linkedin_provider_id,
          cap_remaining: result.cap_remaining ?? undefined,
          drafted_by: result.drafted_by,
        } as ConversationTurnMetadata["linkedin_preview"],
      };
    } else if (result.channel === "email" && result.email_preview) {
      metadata = {
        ...base,
        email_preview:
          result.email_preview as ConversationTurnMetadata["email_preview"],
      };
    } else {
      metadata = base;
    }
  } catch (err) {
    // Outreach not available — show a friendly message in the transcript
    // without exposing internal error details or vendor names.
    const rawMsg = err instanceof Error ? err.message : "";
    const friendlyMsg = /no email|no contact|linkedin outreach isn/i.test(
      rawMsg,
    )
      ? `${candidateName} is in the pipeline. To reach out, add contact details or connect LinkedIn in Preferences.`
      : `${candidateName} is in the pipeline. Outreach couldn't be prepared automatically — open the candidate record to try manually.`;
    try {
      await appendAgentTurn(deps, friendlyMsg, {
        kind: "result",
        action: "send_first_outreach",
        status: "cancelled",
      });
      deps.invalidateTranscript();
    } catch {
      // If even the transcript write fails, swallow so the caller stays clean.
    }
    return;
  }

  try {
    await appendAgentTurn(
      deps,
      metadata.explanation ?? `Ready to reach out to ${candidateName}?`,
      metadata,
    );
    deps.invalidateTranscript();
  } catch {
    // Non-fatal — outreach was prepared, transcript write failed.
  }
}

// Calibration No button: append recruiter turn and ask the follow-up question.
// Bypasses parse-agent-command — button intent is unambiguous.
// The caller sets pendingCalibrationQuestion so the next free-text goes to
// dispatchCalibrationRerank instead of the LLM router.
export async function dispatchCalibrationNo(
  deps: RoleAgentOrchestratorDeps,
): Promise<void> {
  await appendRecruiterTurn(deps, "Not a fit", { kind: "command" });
  await appendAgentTurn(
    deps,
    "Got it — what didn't fit? (e.g. seniority, location, company size, tech stack)",
    { kind: "calibration_question" },
  );
  deps.invalidateTranscript();
}

// Calibration Yes button: show the next batch of candidates.
// Bypasses parse-agent-command — button intent is unambiguous.
// Returns early (no-op) when sourcing is paused; caller shows the toast.
export async function dispatchCalibrationYes(
  deps: RoleAgentOrchestratorDeps,
): Promise<void> {
  if (deps.deal?.sourcing_paused) return;
  await appendRecruiterTurn(deps, "Yes, show more like this", {
    kind: "command",
  });
  const batch = await deps.dataProvider.calibrationNextBatch(deps.dealId);
  if (batch.pool_exhausted && batch.candidates.length === 0) {
    await appendAgentTurn(
      deps,
      "I've shown everyone in the current pool. Say 'relax and search again' to widen the criteria, or 'start sourcing' to pull a fresh batch.",
      { kind: "result", action: "calibration_yes", status: "executed" },
    );
  } else {
    await appendAgentTurn(
      deps,
      batch.pool_exhausted
        ? `Last ${batch.candidates.length} from the current pool:`
        : `Here are the next ${batch.candidates.length}:`,
      { kind: "result", action: "calibration_yes", status: "executed" },
    );
    void appendCalibrationCardTurns(deps, batch);
  }
  deps.invalidateTranscript();
}

// Called when the recruiter answers the "What didn't fit?" calibration question.
// Bypasses parse-agent-command — the context makes intent unambiguous.
// Best-effort: after reranking, tries to promote the reason into
// role_brief_learned_criteria so the NEXT paid search also benefits.
export async function dispatchCalibrationRerank(
  deps: RoleAgentOrchestratorDeps,
  reason: string,
): Promise<void> {
  await appendRecruiterTurn(deps, reason, { kind: "command" });
  const batch = await deps.dataProvider
    .calibrationRerank(deps.dealId, reason)
    .catch(() => null);
  if (!batch || batch.candidates.length === 0) {
    await appendAgentTurn(
      deps,
      "I've adjusted the search based on that feedback — but the current pool doesn't have more candidates to show. Say 'relax and search again' to pull fresh results.",
      { kind: "result", action: "calibration_no", status: "executed" },
    );
  } else {
    await appendAgentTurn(
      deps,
      `Got it — re-ranked based on that. Here are ${batch.candidates.length} better-fitting candidates:`,
      { kind: "result", action: "calibration_no", status: "executed" },
    );
    void appendCalibrationCardTurns(deps, batch);
  }
  deps.invalidateTranscript();
  // Non-blocking: promote applicable reason to a learned criterion so the next
  // search uses it, not just in-pool rerank. Errors are silently swallowed.
  void (async () => {
    try {
      const result = await deps.dataProvider.contextualizeCalibrationFeedback(
        deps.dealId,
        reason,
      );
      if (result.applicable && result.criterion) {
        await deps.dataProvider.applyLearnedCriterion(
          deps.dealId,
          result.criterion,
        );
      }
    } catch {
      // non-fatal
    }
  })();
}

export async function dispatchRoleAgentCommand(
  deps: RoleAgentOrchestratorDeps,
  commandText: string,
): Promise<void> {
  const dealIdNum = Number(deps.dealId);
  const selectedCandidates = deps.selectedCandidates ?? [];
  const pipelineCandidates = deps.pipelineCandidates ?? [];

  await appendRecruiterTurn(deps, commandText, { kind: "command" });

  const parsed = await deps.dataProvider.parseAgentCommand(commandText, {
    view: "canvas",
    open_deals: deps.openDeals.map((d) => ({ id: d.id, name: d.name })),
    current_deal_id: Number.isFinite(dealIdNum) ? dealIdNum : null,
    selected_candidates: selectedCandidates.map((c) => ({
      id: c.id,
      name: c.name,
    })),
    pipeline_candidates: pipelineCandidates.map((c) => ({
      id: c.id,
      name: c.name,
    })),
  });

  const tier = getActionTier(parsed.action);
  const proposalContent = parsed.explanation;

  if (isLeavesPlatformAction(parsed.action)) {
    const metadata = await buildTier3ProposalMetadata(deps, parsed);
    await appendAgentTurn(
      deps,
      metadata.explanation ?? proposalContent,
      metadata,
    );
    deps.invalidateTranscript();
    return;
  }

  const proposalTurn = await appendAgentTurn(deps, proposalContent, {
    kind: "proposal",
    tier,
    action: parsed.action,
    status: "executed",
    explanation: parsed.explanation,
    params: {
      deal_id: parsed.deal_id,
      criterion_id: parsed.criterion_id,
      candidate_id: resolveCandidateId(parsed, selectedCandidates),
    },
  });

  const { summary, undo } = await executeReversibleOrRead(deps, parsed);

  await appendAgentTurn(
    deps,
    summary,
    {
      kind: "result",
      tier,
      action: parsed.action,
      status: "executed",
      undo,
    },
    proposalTurn.id,
  );
  deps.invalidateTranscript();
}

export async function approveTier3Proposal(
  deps: RoleAgentOrchestratorDeps,
  proposalTurn: RoleConversationTurn,
  approvedPreview?: ConversationTurnMetadata["email_preview"],
  approvedLinkedInPreview?: ConversationTurnMetadata["linkedin_preview"],
): Promise<void> {
  const metadata = proposalTurn.metadata as
    | ConversationTurnMetadata
    | undefined;
  const action = metadata?.action;
  if (!action || !isLeavesPlatformAction(action)) {
    throw new Error("This turn is not a pending approval.");
  }

  await appendRecruiterTurn(
    deps,
    "Approved — send it.",
    { kind: "decision", outcome: "approved", action },
    proposalTurn.id,
  );

  const params = metadata.params ?? {};
  const candidateId = params.candidate_id as number | undefined;
  const dealId = (params.deal_id as number | undefined) ?? Number(deps.dealId);
  let resultSummary = "Done.";

  if (action === "send_offer" && candidateId && approvedPreview) {
    await deps.dataProvider.sendOffer(candidateId, dealId, {
      subject: approvedPreview.subject,
      html: approvedPreview.html,
    });
    resultSummary = `Offer email sent to ${approvedPreview.to}.`;
  } else if (
    action === "send_booking_link" &&
    candidateId &&
    metadata.booking_link_url
  ) {
    await deps.dataProvider.sendBookingLink(candidateId, dealId, {
      booking_link_url: metadata.booking_link_url,
      subject: approvedPreview?.subject,
      html: approvedPreview?.html,
    });
    resultSummary = "Booking link saved and email sent.";
  } else if (action === "request_resume" && candidateId && approvedPreview) {
    await deps.dataProvider.requestCandidateResume(candidateId, dealId, {
      subject: approvedPreview.subject,
      html: approvedPreview.html,
    });
    resultSummary = `Resume request sent to ${approvedPreview.to}.`;
  } else if (action === "send_first_outreach" && candidateId) {
    const linkedInPreview =
      approvedLinkedInPreview ?? metadata?.linkedin_preview;
    const emailPreviewForSend = approvedPreview;
    if (linkedInPreview) {
      await deps.dataProvider.sendFirstOutreach(candidateId, dealId, {
        channel: linkedInPreview.channel,
        message_body: linkedInPreview.message_body,
        linkedin_provider_id: linkedInPreview.linkedin_provider_id,
      });
      const channelLabel =
        linkedInPreview.channel === "linkedin_inmail"
          ? "LinkedIn InMail"
          : "LinkedIn connection request";
      resultSummary = `${channelLabel} sent.`;
    } else if (emailPreviewForSend) {
      await deps.dataProvider.sendFirstOutreach(candidateId, dealId, {
        channel: "email",
        subject: emailPreviewForSend.subject,
        html: emailPreviewForSend.html,
      });
      resultSummary = `Outreach email sent to ${emailPreviewForSend.to}.`;
    } else {
      await deps.dataProvider.sendFirstOutreach(candidateId, dealId);
      resultSummary = "Outreach sent.";
    }
  } else {
    resultSummary =
      metadata.explanation ??
      "Approved, but this action still needs wiring with a candidate context.";
  }

  await appendAgentTurn(
    deps,
    resultSummary,
    { kind: "result", action, status: "executed" },
    proposalTurn.id,
  );
  deps.invalidateTranscript();
}

export async function stopTier3Proposal(
  deps: RoleAgentOrchestratorDeps,
  proposalTurn: RoleConversationTurn,
): Promise<void> {
  const metadata = proposalTurn.metadata as
    | ConversationTurnMetadata
    | undefined;

  await appendRecruiterTurn(
    deps,
    "Stopped — don't send.",
    {
      kind: "decision",
      outcome: "stopped",
      action: metadata?.action,
    },
    proposalTurn.id,
  );

  await appendAgentTurn(
    deps,
    "Stopped. Nothing was sent.",
    { kind: "result", action: metadata?.action, status: "cancelled" },
    proposalTurn.id,
  );
  deps.invalidateTranscript();
}

export async function refineTier3Proposal(
  deps: RoleAgentOrchestratorDeps,
  proposalTurn: RoleConversationTurn,
  note: string,
  emailPreview?: ConversationTurnMetadata["email_preview"],
  linkedinPreview?: ConversationTurnMetadata["linkedin_preview"],
): Promise<void> {
  await appendRecruiterTurn(
    deps,
    note,
    {
      kind: "refinement",
      action: (proposalTurn.metadata as ConversationTurnMetadata | undefined)
        ?.action,
      email_preview: emailPreview,
      linkedin_preview: linkedinPreview,
    },
    proposalTurn.id,
  );
  deps.invalidateTranscript();
}

// See docs/adr/ADR-617f-phase-c-human-in-the-loop-approval.md

import type { Identifier } from "ra-core";

export type ActionTier = "read" | "reversible" | "leaves_platform";

export type ParsedAgentAction =
  | "create_role"
  | "start_sourcing"
  | "continue_sourcing"
  | "calibration_yes"
  | "calibration_no"
  | "show_more_like_this"
  | "relax_and_research"
  | "relax_criterion"
  | "request_resume"
  | "reject_candidates"
  | "show_candidates"
  | "show_roles"
  | "send_first_outreach"
  | "send_offer"
  | "send_booking_link"
  | "unknown";

export type ConversationTurnKind =
  | "command"
  | "proposal"
  | "refinement"
  | "decision"
  | "result"
  | "candidate_card"
  | "calibration_question"
  | "intent_update";

export type ConversationTurnMetadata = {
  kind?: ConversationTurnKind;
  tier?: ActionTier;
  action?: ParsedAgentAction | string;
  status?: "pending" | "executed" | "cancelled";
  outcome?: "approved" | "stopped";
  explanation?: string;
  params?: Record<string, unknown>;
  email_preview?: {
    to: string;
    reply_to?: string;
    subject: string;
    html: string;
  };
  linkedin_preview?: {
    channel: "linkedin_connection" | "linkedin_inmail";
    message_body: string;
    char_count: number;
    is_open_profile: boolean;
    linkedin_provider_id: string;
    cap_remaining?: number;
    drafted_by?: "claude" | "fallback_template";
  };
  booking_link_url?: string;
  undo?: {
    action: string;
    params: Record<string, unknown>;
  };
  // TASK-003: candidate card embedded in the transcript after sourcing runs.
  candidate_card?: {
    candidate_id: number;
    deal_id: number;
    name: string;
    headline: string | null;
    linkedin_url: string | null;
    location_name?: string | null;
    match_score: number | null;
    must_haves: Array<{
      label: string;
      status: "found" | "inferred" | "missing";
    }>;
    // Loop B calibration cards: external vendor id (not yet saved to pipeline).
    calibration_external_id?: string;
    why_fit?: string;
  };
};

const ACTION_TIERS: Record<ParsedAgentAction, ActionTier> = {
  show_roles: "read",
  show_candidates: "read",
  unknown: "read",
  create_role: "reversible",
  start_sourcing: "reversible",
  continue_sourcing: "reversible",
  calibration_yes: "reversible",
  calibration_no: "reversible",
  show_more_like_this: "reversible",
  relax_and_research: "reversible",
  relax_criterion: "reversible",
  reject_candidates: "reversible",
  request_resume: "leaves_platform",
  send_first_outreach: "leaves_platform",
  send_offer: "leaves_platform",
  send_booking_link: "leaves_platform",
};

export function getActionTier(action: string): ActionTier {
  return ACTION_TIERS[action as ParsedAgentAction] ?? "read";
}

export function isLeavesPlatformAction(action: string): boolean {
  return getActionTier(action) === "leaves_platform";
}

export function isPendingTier3Proposal(
  metadata: ConversationTurnMetadata | undefined,
): boolean {
  return (
    metadata?.kind === "proposal" &&
    metadata?.tier === "leaves_platform" &&
    metadata?.status === "pending"
  );
}

type TurnSummary = {
  id: Identifier;
  in_reply_to?: Identifier | null;
  metadata?: ConversationTurnMetadata;
};

export function getLatestEmailPreview(
  proposalTurnId: Identifier,
  turns: TurnSummary[],
): ConversationTurnMetadata["email_preview"] | undefined {
  const proposal = turns.find((t) => t.id === proposalTurnId);
  let preview = proposal?.metadata?.email_preview;

  for (const turn of turns) {
    if (
      turn.in_reply_to === proposalTurnId &&
      turn.metadata?.kind === "refinement" &&
      turn.metadata.email_preview
    ) {
      preview = turn.metadata.email_preview;
    }
  }

  return preview;
}

/** Like getLatestEmailPreview but for LinkedIn outreach previews. */
export function getLatestLinkedInPreview(
  proposalTurnId: Identifier,
  turns: TurnSummary[],
): ConversationTurnMetadata["linkedin_preview"] | undefined {
  const proposal = turns.find((t) => t.id === proposalTurnId);
  let preview = proposal?.metadata?.linkedin_preview;

  for (const turn of turns) {
    if (
      turn.in_reply_to === proposalTurnId &&
      turn.metadata?.kind === "refinement" &&
      turn.metadata.linkedin_preview
    ) {
      preview = turn.metadata.linkedin_preview;
    }
  }

  return preview;
}

import { useGetList, useDataProvider, useNotify } from "ra-core";
import { useState, useMemo } from "react";
import type { CrmDataProvider } from "../providers/types";
import type { RoleConversationTurn } from "../types";
import {
  type ConversationTurnMetadata,
  isPendingTier3Proposal,
} from "./agentActionTiers";
import { PendingApprovalCard } from "./PendingApprovalCard";
import { normalizeLinkedinUrl } from "../misc/normalizeLinkedinUrl";

// Loop B calibration: inline candidate card — pipeline action only.
// Yes / Not-a-fit appears once as a BatchFooter after the latest batch.
function CandidateCardTurn({
  metadata,
  onAddToPipeline,
  pipelineSaveState,
}: {
  metadata: NonNullable<ConversationTurnMetadata["candidate_card"]>;
  onAddToPipeline?: () => void;
  pipelineSaveState?: "idle" | "saving" | "saved";
}) {
  return (
    <li className="border rounded-md p-3 flex flex-col gap-1.5 text-sm bg-muted/20">
      <div className="font-medium flex items-center gap-2 flex-wrap">
        {metadata.name}
        {metadata.match_score != null && (
          <span className="text-xs font-normal text-muted-foreground border rounded px-1.5 py-0.5">
            Match {Math.round(metadata.match_score * 100)}%
          </span>
        )}
      </div>
      {metadata.headline && (
        <div className="text-xs text-muted-foreground">{metadata.headline}</div>
      )}
      {/* why_fit is always non-empty from the server; show it prominently */}
      {metadata.why_fit && (
        <div className="text-xs text-muted-foreground italic">
          {metadata.why_fit}
        </div>
      )}
      {metadata.location_name && (
        <div className="text-xs text-muted-foreground">
          📍 {metadata.location_name}
        </div>
      )}
      {(() => {
        const normalized = normalizeLinkedinUrl(metadata.linkedin_url);
        const href =
          normalized ??
          (metadata.linkedin_url
            ? `https://${metadata.linkedin_url.replace(/^https?:\/\//i, "")}`
            : null);
        return href ? (
          <a
            href={href}
            target="_blank"
            rel="noreferrer"
            className="text-xs text-blue-700 underline"
          >
            LinkedIn profile
          </a>
        ) : null;
      })()}
      {metadata.must_haves.length > 0 && (
        <ul className="flex flex-col gap-0.5 mt-0.5">
          {metadata.must_haves.map((m, i) => (
            <li key={i} className="text-xs flex items-center gap-1.5">
              <span
                className={
                  m.status === "found"
                    ? "text-green-600"
                    : m.status === "inferred"
                      ? "text-yellow-600"
                      : "text-red-500"
                }
              >
                {m.status === "found"
                  ? "✓"
                  : m.status === "inferred"
                    ? "~"
                    : "✗"}
              </span>
              {m.label}
            </li>
          ))}
        </ul>
      )}
      {onAddToPipeline && (
        <div className="flex gap-2 mt-2">
          <button
            type="button"
            className="text-xs border rounded px-2 py-1 transition-colors text-blue-700 border-blue-200 bg-blue-50/60 hover:bg-blue-100 disabled:opacity-50"
            onClick={onAddToPipeline}
            disabled={
              pipelineSaveState === "saving" || pipelineSaveState === "saved"
            }
          >
            {pipelineSaveState === "saved"
              ? "✓ Added to pipeline"
              : pipelineSaveState === "saving"
                ? "Adding…"
                : "+ Add to pipeline"}
          </button>
        </div>
      )}
    </li>
  );
}

// Batch-level calibration actions — shown once after the latest candidate batch.
function BatchFooter({
  onCalibrationYes,
  onCalibrationNo,
}: {
  onCalibrationYes?: () => void;
  onCalibrationNo?: () => void;
}) {
  if (!onCalibrationYes && !onCalibrationNo) return null;
  return (
    <div className="flex gap-2 flex-wrap pt-1 border-t border-dashed">
      {onCalibrationYes && (
        <button
          type="button"
          className="text-xs border rounded px-2 py-1 hover:bg-muted transition-colors text-green-700 border-green-200 bg-green-50/60"
          onClick={onCalibrationYes}
        >
          ✓ These look right — show more like this
        </button>
      )}
      {onCalibrationNo && (
        <button
          type="button"
          className="text-xs border rounded px-2 py-1 hover:bg-muted transition-colors text-muted-foreground"
          onClick={onCalibrationNo}
        >
          ✗ Not a fit
        </button>
      )}
    </div>
  );
}

type RoleConversationTranscriptProps = {
  dealId: string;
  onApprove: (
    turn: RoleConversationTurn,
    preview?: ConversationTurnMetadata["email_preview"],
    linkedinPreview?: ConversationTurnMetadata["linkedin_preview"],
  ) => void | Promise<void>;
  onStop: (turn: RoleConversationTurn) => void | Promise<void>;
  onRefine: (
    turn: RoleConversationTurn,
    preview?: ConversationTurnMetadata["email_preview"],
    linkedinPreview?: ConversationTurnMetadata["linkedin_preview"],
  ) => void | Promise<void>;
  actionBusy?: boolean;
  onCalibrationYes?: () => void;
  onCalibrationNo?: () => void;
};

export const RoleConversationTranscript = ({
  dealId,
  onApprove,
  onStop,
  onRefine,
  actionBusy = false,
  onCalibrationYes,
  onCalibrationNo,
}: RoleConversationTranscriptProps) => {
  const {
    data: turns,
    isPending,
    isError,
  } = useGetList<RoleConversationTurn>("role_conversation_turns", {
    filter: { deal_id: dealId },
    sort: { field: "created_at", order: "ASC" },
    pagination: { page: 1, perPage: 100 },
  });

  const dataProvider = useDataProvider<CrmDataProvider>();
  const notify = useNotify();
  const [pipelineSaveStates, setPipelineSaveStates] = useState<
    Record<string, "idle" | "saving" | "saved">
  >({});
  const [showHistory, setShowHistory] = useState(false);

  const handleAddToPipeline = async (
    cardMeta: NonNullable<ConversationTurnMetadata["candidate_card"]>,
  ) => {
    const extId = cardMeta.calibration_external_id;
    if (!extId) return;
    setPipelineSaveStates((prev) => ({ ...prev, [extId]: "saving" }));
    try {
      await dataProvider.saveSourcedCandidate(cardMeta.deal_id, {
        id: extId,
        full_name: cardMeta.name,
        linkedin_url: cardMeta.linkedin_url ?? null,
        // headline is "title at company" — store as job_title for display
        job_title: cardMeta.headline ?? null,
      });
      setPipelineSaveStates((prev) => ({ ...prev, [extId]: "saved" }));
      notify("Added to pipeline", { type: "success" });
    } catch (error: unknown) {
      setPipelineSaveStates((prev) => ({ ...prev, [extId]: "idle" }));
      const msg =
        error instanceof Error ? error.message : "Failed to add to pipeline";
      notify(msg, { type: "error" });
    }
  };

  const list = turns ?? [];

  // Pending approval turns must always be visible.
  const pendingApprovalIds = useMemo(
    () =>
      new Set(
        list
          .filter((t) => {
            const m = t.metadata as ConversationTurnMetadata | undefined;
            if (!isPendingTier3Proposal(m)) return false;
            return !list.some(
              (other) =>
                other.in_reply_to === t.id &&
                (other.metadata as ConversationTurnMetadata | undefined)
                  ?.kind === "decision",
            );
          })
          .map((t) => t.id),
      ),
    [list],
  );

  // Latest calibration batch: the trailing run of consecutive candidate_card turns.
  // These stay visible even when the transcript is collapsed.
  const latestBatchIds = useMemo(() => {
    const ids: string[] = [];
    for (let i = list.length - 1; i >= 0; i--) {
      const m = list[i].metadata as ConversationTurnMetadata | undefined;
      if (m?.kind === "candidate_card") {
        ids.unshift(String(list[i].id));
      } else if (m?.kind === "decision" || m?.kind === "refinement") {
        // skip invisible turns
        continue;
      } else {
        break;
      }
    }
    return new Set(ids);
  }, [list]);

  // In collapsed state: show the latest candidate batch + any pending approvals.
  // Falls back to last 2 rendered turns if there are no calibration cards.
  const visibleIds = useMemo(() => {
    if (showHistory) return null; // null = show all
    const rendered = list.filter((t) => {
      const m = t.metadata as ConversationTurnMetadata | undefined;
      return m?.kind !== "decision" && m?.kind !== "refinement";
    });
    if (latestBatchIds.size > 0) {
      return new Set([...latestBatchIds, ...pendingApprovalIds]);
    }
    return new Set([
      ...rendered.slice(-2).map((t) => String(t.id)),
      ...pendingApprovalIds,
    ]);
  }, [showHistory, list, pendingApprovalIds, latestBatchIds]);

  return (
    <div className="ah-panel p-4 flex flex-col gap-3">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-medium tracking-wide uppercase text-muted-foreground">
          Conversation
        </h3>
        {list.length > 2 && (
          <button
            type="button"
            className="text-xs text-muted-foreground hover:text-foreground underline underline-offset-2"
            onClick={() => setShowHistory((v) => !v)}
          >
            {showHistory ? "Collapse" : `Show history (${list.length} turns)`}
          </button>
        )}
      </div>

      {isPending ? (
        <p className="text-sm text-muted-foreground">Loading…</p>
      ) : isError ? (
        <p className="text-sm text-muted-foreground">
          Conversation history is not available yet — apply the latest database
          migration.
        </p>
      ) : !list.length ? (
        <p className="text-sm text-muted-foreground">
          Start sourcing to see Agent H's activity here.
        </p>
      ) : (
        <>
          <ul className="flex flex-col gap-3 max-h-[60vh] overflow-y-auto">
            {list.map((turn) => {
              if (visibleIds !== null && !visibleIds.has(String(turn.id)))
                return null;
              const metadata = turn.metadata as
                | ConversationTurnMetadata
                | undefined;

              if (isPendingTier3Proposal(metadata)) {
                const hasLaterDecision = list.some(
                  (other) =>
                    other.in_reply_to === turn.id &&
                    (other.metadata as ConversationTurnMetadata | undefined)
                      ?.kind === "decision",
                );
                if (hasLaterDecision) return null;

                return (
                  <PendingApprovalCard
                    key={turn.id}
                    turn={turn}
                    allTurns={list}
                    onApprove={onApprove}
                    onStop={onStop}
                    onRefine={onRefine}
                    busy={actionBusy}
                  />
                );
              }

              if (
                metadata?.kind === "decision" ||
                metadata?.kind === "refinement"
              ) {
                return null;
              }

              if (
                metadata?.kind === "candidate_card" &&
                metadata.candidate_card
              ) {
                const card = metadata.candidate_card;
                const extId = card.calibration_external_id;
                return (
                  <CandidateCardTurn
                    key={turn.id}
                    metadata={card}
                    onAddToPipeline={
                      extId ? () => handleAddToPipeline(card) : undefined
                    }
                    pipelineSaveState={
                      extId ? (pipelineSaveStates[extId] ?? "idle") : undefined
                    }
                  />
                );
              }

              if (metadata?.kind === "calibration_question") {
                return (
                  <li key={turn.id} className="flex flex-col gap-1 text-sm">
                    <span className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
                      Agent H
                    </span>
                    <span className="whitespace-pre-wrap text-foreground">
                      {turn.content}
                    </span>
                  </li>
                );
              }

              if (metadata?.kind === "intent_update") {
                return (
                  <li
                    key={turn.id}
                    className="rounded border border-border/50 bg-muted/40 px-3 py-2 text-xs space-y-0.5"
                  >
                    <span className="block font-semibold text-muted-foreground uppercase tracking-wide text-[10px] mb-1">
                      Sourcing intent updated
                    </span>
                    <span className="whitespace-pre-wrap text-foreground/80">
                      {turn.content}
                    </span>
                  </li>
                );
              }

              return (
                <li key={turn.id} className="flex flex-col gap-1 text-sm">
                  <span className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
                    {turn.speaker === "agent" ? "Agent H" : "You"}
                    {metadata?.kind === "result" ? " — result" : ""}
                  </span>
                  <span className="whitespace-pre-wrap">{turn.content}</span>
                </li>
              );
            })}
          </ul>
          {/* Batch footer — shown once after the latest candidate batch */}
          {latestBatchIds.size > 0 && (
            <BatchFooter
              onCalibrationYes={onCalibrationYes}
              onCalibrationNo={onCalibrationNo}
            />
          )}
        </>
      )}
    </div>
  );
};

import { useState } from "react";
import { Button } from "@/components/ui/button";
import type { RoleConversationTurn } from "../types";
import {
  type ConversationTurnMetadata,
  getLatestEmailPreview,
  getLatestLinkedInPreview,
} from "./agentActionTiers";

const CONNECTION_CHAR_LIMIT = 300;

type PendingApprovalCardProps = {
  turn: RoleConversationTurn;
  allTurns: RoleConversationTurn[];
  onApprove: (
    turn: RoleConversationTurn,
    preview?: ConversationTurnMetadata["email_preview"],
    linkedinPreview?: ConversationTurnMetadata["linkedin_preview"],
  ) => void | Promise<void>;
  onStop: (turn: RoleConversationTurn) => void | Promise<void>;
  onRefine: (
    turn: RoleConversationTurn,
    preview?: ConversationTurnMetadata["email_preview"],
    linkedinPreview?: ConversationTurnMetadata["linkedin_preview"],
  ) => void | Promise<void>;
  busy?: boolean;
};

export const PendingApprovalCard = ({
  turn,
  allTurns,
  onApprove,
  onStop,
  onRefine,
  busy = false,
}: PendingApprovalCardProps) => {
  const metadata = turn.metadata as ConversationTurnMetadata | undefined;
  const initialEmailPreview = getLatestEmailPreview(turn.id, allTurns);
  const initialLinkedInPreview = getLatestLinkedInPreview(turn.id, allTurns);

  const [emailPreview, setEmailPreview] = useState(initialEmailPreview);
  const [linkedinPreview, setLinkedInPreview] = useState(
    initialLinkedInPreview,
  );

  const inputClass =
    "border border-input bg-background text-foreground rounded px-2 py-1 text-xs w-full";

  const charCount = linkedinPreview?.message_body?.length ?? 0;
  const isConnectionChannel =
    linkedinPreview?.channel === "linkedin_connection";
  const overLimit = isConnectionChannel && charCount > CONNECTION_CHAR_LIMIT;

  return (
    <li className="border border-amber-300 bg-amber-50/80 rounded-md p-3 flex flex-col gap-2 text-sm">
      <div className="flex flex-col gap-1">
        <span className="text-xs font-medium uppercase tracking-wide text-amber-900">
          Pending approval — {metadata?.action ?? "action"}
        </span>
        <span className="whitespace-pre-wrap">{turn.content}</span>
      </div>

      {linkedinPreview ? (
        <>
          <div className="flex items-center justify-between text-xs text-muted-foreground">
            <span>
              {linkedinPreview.channel === "linkedin_inmail"
                ? "LinkedIn InMail (open profile)"
                : "LinkedIn connection note"}
            </span>
            <span
              className={overLimit ? "text-destructive font-medium" : undefined}
            >
              {charCount}
              {isConnectionChannel ? `/${CONNECTION_CHAR_LIMIT}` : ""} chars
            </span>
          </div>
          <label className="flex flex-col gap-1 text-xs text-muted-foreground">
            Message
            <textarea
              className={`${inputClass} ${overLimit ? "border-destructive" : ""}`}
              rows={isConnectionChannel ? 4 : 6}
              value={linkedinPreview.message_body}
              onChange={(e) =>
                setLinkedInPreview({
                  ...linkedinPreview,
                  message_body: e.target.value,
                  char_count: e.target.value.length,
                })
              }
            />
          </label>
          {overLimit && (
            <p className="text-xs text-destructive">
              Connection notes must be {CONNECTION_CHAR_LIMIT} characters or
              fewer. Trim the message before sending.
            </p>
          )}
          {linkedinPreview.cap_remaining !== undefined && (
            <p className="text-xs text-muted-foreground">
              {linkedinPreview.cap_remaining} sends remaining today
            </p>
          )}
          <Button
            size="sm"
            variant="outline"
            disabled={busy}
            onClick={() => onRefine(turn, undefined, linkedinPreview)}
          >
            Save edits
          </Button>
        </>
      ) : emailPreview ? (
        <>
          <label className="flex flex-col gap-1 text-xs text-muted-foreground">
            To
            <input className={inputClass} value={emailPreview.to} readOnly />
          </label>
          <label className="flex flex-col gap-1 text-xs text-muted-foreground">
            Subject
            <input
              className={inputClass}
              value={emailPreview.subject}
              onChange={(e) =>
                setEmailPreview({ ...emailPreview, subject: e.target.value })
              }
            />
          </label>
          <label className="flex flex-col gap-1 text-xs text-muted-foreground">
            Email body (HTML)
            <textarea
              className={inputClass}
              rows={5}
              value={emailPreview.html}
              onChange={(e) =>
                setEmailPreview({ ...emailPreview, html: e.target.value })
              }
            />
          </label>
          <Button
            size="sm"
            variant="outline"
            disabled={busy}
            onClick={() => onRefine(turn, emailPreview)}
          >
            Save edits
          </Button>
        </>
      ) : metadata?.booking_link_url ? (
        <a
          href={metadata.booking_link_url}
          target="_blank"
          rel="noreferrer"
          className="text-xs text-blue-700 underline break-all"
        >
          {metadata.booking_link_url}
        </a>
      ) : null}

      <div className="flex gap-2">
        <Button
          size="sm"
          disabled={busy || overLimit}
          onClick={() =>
            onApprove(
              turn,
              emailPreview ?? undefined,
              linkedinPreview ?? undefined,
            )
          }
        >
          {busy ? "Sending…" : "Approve & send"}
        </Button>
        <Button
          size="sm"
          variant="outline"
          disabled={busy}
          onClick={() => onStop(turn)}
        >
          Stop
        </Button>
      </div>
    </li>
  );
};

