    // an identical link (see undoRejectDealCandidate below).
    async rejectDealCandidate(dealCandidateId: Identifier) {
      const { data } = await baseDataProvider.delete("deal_candidates", {
        id: dealCandidateId,
        previousData: { id: dealCandidateId },
      });
