// AppShell (2026-07-26): Noon-style role-first layout replacing the old
// top-tab Header. Narrow 48px icon rail on the left; expandable 240px
// sidebar with the roles list; main content takes the rest.
// Orange active states (--sidebar-primary) on the rail + sidebar;
// deep-navy primary CTAs throughout the app via --primary.
// Mobile: icon rail collapses to a hamburger overlay sheet.
import { useState, useEffect } from "react";
import { Link, useLocation, useNavigate } from "react-router";
import {
  BarChart2,
  ChevronLeft,
  Home,
  Menu,
  Plus,
  Search,
  Settings,
  X,
} from "lucide-react";
import { useGetList, useGetIdentity } from "ra-core";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { UserMenu } from "@/components/admin/user-menu";
import { ThemeModeToggle } from "@/components/admin/theme-mode-toggle";
import { DropdownMenuItem } from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";

import type { Deal } from "../types";
import { useConfigurationContext } from "../root/ConfigurationContext";

type Tab = "all" | "mine";

const isRoleDetailPath = (path: string) => /^\/roles\/[^/]+/.test(path);

export const AppShell = ({ children }: { children: React.ReactNode }) => {
  const location = useLocation();
  // Default: collapse the roles rail when viewing a specific role workspace
  // (gives maximum screen real estate to the 3-pane layout).
  const [sidebarOpen, setSidebarOpen] = useState(
    () => !isRoleDetailPath(location.pathname),
  );
  const [mobileOpen, setMobileOpen] = useState(false);

  // Auto-manage sidebar when navigating between role list and role detail.
  useEffect(() => {
    if (isRoleDetailPath(location.pathname)) {
      setSidebarOpen(false);
    } else {
      setSidebarOpen(true);
    }
  }, [location.pathname]);

  return (
    <div className="flex h-screen overflow-hidden bg-background">
      {/* Mobile overlay */}
      {mobileOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/40 md:hidden"
          onClick={() => setMobileOpen(false)}
        />
      )}

      {/* Icon rail — always visible on desktop; hidden on mobile */}
      <aside className="hidden md:flex w-12 shrink-0 flex-col items-center border-r border-sidebar-border bg-sidebar py-3 gap-1 z-20">
        <RailTop
          onToggleSidebar={() => setSidebarOpen((v) => !v)}
          sidebarOpen={sidebarOpen}
          currentPath={location.pathname}
        />
        <div className="flex-1" />
        <RailBottom />
      </aside>

      {/* Mobile hamburger button */}
      <button
        className="md:hidden fixed top-3 left-3 z-50 rounded-lg border border-border bg-background p-2 shadow-sm"
        onClick={() => setMobileOpen((v) => !v)}
        aria-label="Open navigation"
      >
        {mobileOpen ? <X className="h-4 w-4" /> : <Menu className="h-4 w-4" />}
      </button>

      {/* Roles sidebar */}
      <aside
        className={cn(
          "shrink-0 border-r border-sidebar-border bg-sidebar overflow-hidden transition-all duration-200 z-30",
          // Desktop: inline, collapsible
          sidebarOpen ? "hidden md:flex md:w-60 flex-col" : "hidden md:hidden",
          // Mobile: overlay sheet
          mobileOpen
            ? "fixed inset-y-0 left-0 flex flex-col w-72 md:hidden"
            : "",
        )}
      >
        <RolesSidebar onClose={() => setMobileOpen(false)} />
      </aside>

      {/* Main content */}
      <div className="flex-1 flex flex-col min-w-0 overflow-auto">
        {children}
      </div>
    </div>
  );
};

/* ------------------------------------------------------------------ */
/* Icon rail                                                           */
/* ------------------------------------------------------------------ */

function RailTop({
  onToggleSidebar,
  sidebarOpen,
  currentPath,
}: {
  onToggleSidebar: () => void;
  sidebarOpen: boolean;
  currentPath: string;
}) {
  const { darkModeLogo, lightModeLogo, title } = useConfigurationContext();

  return (
    <>
      {/* Logo / collapse toggle */}
      <button
        onClick={onToggleSidebar}
        className="mb-2 rounded-lg p-1.5 hover:bg-sidebar-accent text-sidebar-foreground/60 hover:text-sidebar-foreground transition-colors"
        aria-label={sidebarOpen ? "Collapse sidebar" : "Expand sidebar"}
        title={sidebarOpen ? "Collapse sidebar" : "Expand sidebar"}
      >
        {sidebarOpen ? (
          <ChevronLeft className="h-4 w-4" />
        ) : (
          <>
            <img
              className="[.light_&]:hidden h-5 w-5 object-contain"
              src={darkModeLogo}
              alt={title}
            />
            <img
              className="[.dark_&]:hidden h-5 w-5 object-contain"
              src={lightModeLogo}
              alt={title}
            />
          </>
        )}
      </button>

      <RailIcon
        to="/"
        icon={<Home className="h-4 w-4" />}
        label="Home"
        active={currentPath === "/"}
      />
      <RailIcon
        to="/"
        icon={<Plus className="h-4 w-4" />}
        label="New role"
        active={false}
      />
    </>
  );
}

function RailBottom() {
  const location = useLocation();
  return (
    <>
      <RailIcon
        to="/analytics"
        icon={<BarChart2 className="h-4 w-4" />}
        label="Analytics"
        active={location.pathname.startsWith("/analytics")}
      />
      <RailIcon
        to="/preferences"
        icon={<Settings className="h-4 w-4" />}
        label="Preferences"
        active={location.pathname.startsWith("/preferences")}
      />
      <div className="mt-1">
        <UserMenu>
          <ProfileMenuItem />
        </UserMenu>
      </div>
      <ThemeModeToggle />
    </>
  );
}

function RailIcon({
  to,
  icon,
  label,
  active,
  disabled,
}: {
  to: string;
  icon: React.ReactNode;
  label: string;
  active: boolean;
  disabled?: boolean;
}) {
  if (disabled) {
    return (
      <span
        title={label}
        aria-label={label}
        className="rounded-lg p-2.5 text-sidebar-foreground/30 cursor-not-allowed"
      >
        {icon}
      </span>
    );
  }
  return (
    <Link
      to={to}
      title={label}
      aria-label={label}
      className={cn(
        "rounded-lg p-2.5 transition-colors",
        active
          ? "bg-sidebar-accent text-sidebar-primary"
          : "text-sidebar-foreground/60 hover:bg-sidebar-accent hover:text-sidebar-foreground",
      )}
    >
      {icon}
    </Link>
  );
}

function ProfileMenuItem() {
  return (
    <>
      <DropdownMenuItem asChild>
        <Link to="/profile" className="flex items-center gap-2">
          Profile
        </Link>
      </DropdownMenuItem>
      <DropdownMenuItem asChild>
        <Link to="/templates" className="flex items-center gap-2">
          Templates
        </Link>
      </DropdownMenuItem>
    </>
  );
}

/* ------------------------------------------------------------------ */
/* Roles sidebar                                                        */
/* ------------------------------------------------------------------ */

function RolesSidebar({ onClose }: { onClose: () => void }) {
  const [tab, setTab] = useState<Tab>("all");
  const [search, setSearch] = useState("");
  const location = useLocation();
  const navigate = useNavigate();
  const { identity } = useGetIdentity();
  const { darkModeLogo, lightModeLogo, title } = useConfigurationContext();

  const { data: deals = [] } = useGetList<Deal>("deals", {
    pagination: { page: 1, perPage: 50 },
    sort: { field: "updated_at", order: "DESC" },
    filter: { "archived_at@is": null },
  });

  const filtered = deals.filter((d) => {
    if (tab === "mine" && identity?.id && d.sales_id !== identity.id)
      return false;
    if (search && !d.name.toLowerCase().includes(search.toLowerCase()))
      return false;
    return true;
  });

  const activeRoleId = location.pathname.match(/^\/roles\/([^/]+)/)?.[1];

  return (
    <div className="flex flex-col h-full">
      {/* Header with logo + close (mobile only) */}
      <div className="flex items-center gap-2 px-3 py-3 border-b border-sidebar-border">
        <Link
          to="/"
          className="flex items-center gap-1.5 flex-1 min-w-0"
          onClick={onClose}
        >
          <img
            className="[.light_&]:hidden h-5 shrink-0"
            src={darkModeLogo}
            alt={title}
          />
          <img
            className="[.dark_&]:hidden h-5 shrink-0"
            src={lightModeLogo}
            alt={title}
          />
          <span className="font-semibold text-sm text-sidebar-foreground truncate">
            Agent H
          </span>
        </Link>
        <button
          className="md:hidden text-sidebar-foreground/50 hover:text-sidebar-foreground"
          onClick={onClose}
          aria-label="Close navigation"
        >
          <X className="h-4 w-4" />
        </button>
      </div>

      {/* New role CTA */}
      <div className="px-3 py-2">
        <Button
          size="sm"
          className="w-full justify-start gap-2"
          onClick={() => {
            navigate("/");
            onClose();
          }}
        >
          <Plus className="h-3.5 w-3.5" />
          New role
        </Button>
      </div>

      {/* Search */}
      <div className="px-3 pb-2">
        <div className="relative">
          <Search className="absolute left-2.5 top-2 h-3.5 w-3.5 text-sidebar-foreground/40 pointer-events-none" />
          <Input
            placeholder="Search roles…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="h-8 pl-8 text-sm bg-sidebar-accent/50 border-sidebar-border focus-visible:ring-sidebar-ring"
          />
        </div>
      </div>

      {/* All / Yours tabs */}
      <div className="flex gap-0 px-3 pb-2">
        {(["all", "mine"] as const).map((t) => (
          <button
            key={t}
            onClick={() => setTab(t)}
            className={cn(
              "flex-1 py-1 text-xs font-medium rounded-md transition-colors",
              tab === t
                ? "bg-sidebar-accent text-sidebar-primary"
                : "text-sidebar-foreground/50 hover:text-sidebar-foreground",
            )}
          >
            {t === "all" ? "All" : "Yours"}
          </button>
        ))}
      </div>

      {/* Roles list */}
      <nav className="flex-1 overflow-y-auto px-2 pb-4">
        {filtered.length === 0 ? (
          <div className="px-2 py-6 text-center text-xs text-sidebar-foreground/40">
            {search ? "No matching roles" : "No open roles"}
          </div>
        ) : (
          <ul className="flex flex-col gap-0.5">
            {filtered.map((deal) => {
              const isActive = activeRoleId === String(deal.id);
              return (
                <li key={deal.id}>
                  <Link
                    to={`/roles/${deal.id}`}
                    onClick={onClose}
                    className={cn(
                      "flex items-center gap-2 rounded-md px-2.5 py-2 text-sm transition-colors no-underline",
                      isActive
                        ? "bg-sidebar-accent text-sidebar-primary font-medium"
                        : "text-sidebar-foreground/70 hover:bg-sidebar-accent/60 hover:text-sidebar-foreground",
                    )}
                  >
                    <span className="truncate">{deal.name}</span>
                  </Link>
                </li>
              );
            })}
          </ul>
        )}
      </nav>
    </div>
  );
}

// Agent H Stage 2: JD Intake.
//
// Paste a job description, parse it into a structured role brief via
// dataProvider.parseJobDescription (which calls the parse-job-description
// edge function), review/edit the extracted fields, then save it as a
// role brief (a public.deals row -- see
// supabase/schemas/15_agent_h_structured_role_brief_fields.sql for why
// deals rather than a new table).
//
// Deliberately not built as a react-admin <Create> form: the two-phase
// "parse, then review/edit, then save" flow doesn't map cleanly onto a
// single-submit form, so this page manages its own local state and calls
// the data provider directly.

import { useState } from "react";
import { useDataProvider, useGetList, useNotify, useRedirect } from "ra-core";
import { useNavigate } from "react-router";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import type { CrmDataProvider } from "../providers/types";
import { AgentHShell } from "../shell/AgentHShell";
import { useJdIntakeShellContext } from "../shell/useShellContext";
import type { Deal } from "../types";
import "../inbox/agent-h-theme.css";

const SENIORITY_OPTIONS = [
  "intern",
  "entry_level",
  "mid_level",
  "senior",
  "staff",
  "principal",
  "manager",
  "director",
  "executive",
];

const EMPLOYMENT_TYPE_OPTIONS = [
  "full_time",
  "part_time",
  "contract",
  "contract_to_hire",
  "internship",
];

// Agent H, tiered preferences (2026-07-22): a JD like Epiq's -- "PRIMARY
// PREFERENCE: X... SECONDARY/ACCEPTABLE: Y..." -- describes a ranked
// fallback profile, not a single flat requirement set. Kept separate from
// must_have_keywords so the review UI can show "Primary preference" and
// "Secondary / acceptable" as distinct groups instead of one run-on
// sentence. Empty array is the common case (flat JD, no ranking).
type PreferenceTier = {
  rank: number;
  label: string;
  keywords: string[];
  condition: string | null;
};

type ParsedRoleBrief = {
  title: string;
  seniority: string;
  location: string;
  industry: string | null;
  employment_type: string;
  years_experience_min: number | null;
  years_experience_max: number | null;
  required_skills: string[];
  must_have_keywords: string[];
  nice_to_have_keywords: string[];
  preference_tiers: PreferenceTier[];
  // Ambiguities the parser flagged worth confirming before sourcing starts
  // (task #30). Read-only/dismissible advisory, not a back-and-forth
  // conversation -- see parse-job-description's header comment for why.
  clarifying_questions: string[];
  // Agent H: sourcing preferences, not JD facts -- these describe which
  // companies to pull CANDIDATES from, the opposite direction of
  // `industry` (which is inferred from the JD's own hiring company).
  // Never LLM-extracted from jd_text for that reason; the recruiter fills
  // these in at review time, same as the exclusion fields below.
  company_type: string | null;
  company_size_min: number | null;
  company_size_max: number | null;
  // Recruiter-entered hard excludes. Deliberately not parsed from the JD
  // either -- a JD describing the role essentially never names companies
  // or terms to avoid; that's sourcing judgment, not a JD fact.
  excluded_companies: string[];
  exclusion_keywords: string[];
  // Past-position search (2026-07-22): same "recruiter sourcing judgment,
  // never JD-parsed" treatment as excluded_companies/exclusion_keywords
  // above -- a JD describing the role being hired for doesn't name past
  // titles or employers a good candidate might have; that's the
  // recruiter's own sourcing intuition ("someone who used to be a Founding
  // Engineer," "worked at Microsoft at some point"). Boosts matches in
  // source-candidates-discovery's Coresignal query rather than requiring
  // them -- see that function's DiscoveryCriteria.pastTitles/pastCompanies.
  past_titles: string[];
  past_companies: string[];
};

const arrayToText = (values: string[] | undefined) => (values ?? []).join(", ");

const textToArray = (value: string) =>
  value
    .split(",")
    .map((v) => v.trim())
    .filter((v) => v.length > 0);

export const JdIntakePage = () => {
  const dataProvider = useDataProvider<CrmDataProvider>();
  const notify = useNotify();
  const redirect = useRedirect();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { data: openDeals } = useGetList<Deal>("deals", {
    pagination: { page: 1, perPage: 20 },
    sort: { field: "updated_at", order: "DESC" },
    filter: { "archived_at@is": null },
  });

  const [jdText, setJdText] = useState("");
  const [parsing, setParsing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [parsed, setParsed] = useState<ParsedRoleBrief | null>(null);
  const [skillsText, setSkillsText] = useState("");
  const [mustHaveText, setMustHaveText] = useState("");
  const [niceToHaveText, setNiceToHaveText] = useState("");
  const [excludedCompaniesText, setExcludedCompaniesText] = useState("");
  const [exclusionKeywordsText, setExclusionKeywordsText] = useState("");
  const [pastTitlesText, setPastTitlesText] = useState("");
  const [pastCompaniesText, setPastCompaniesText] = useState("");
  // Local-only until save -- the recruiter can dismiss the clarifying-
  // questions advisory during review; clarifying_questions_dismissed is
  // persisted as-is at create time so it doesn't resurface on the role
  // brief's own detail view.
  const [questionsDismissed, setQuestionsDismissed] = useState(false);

  const shellContext = useJdIntakeShellContext({
    parsedTitle: parsed?.title,
    hasJdText: jdText.trim().length > 0,
    isParsing: parsing,
    isSaving: saving,
  });

  const runFreeTextCommand = async (commandText: string) => {
    try {
      const command = await dataProvider.parseAgentCommand(commandText, {
        view: "inbox",
        open_deals: (openDeals ?? []).map((d) => ({ id: d.id, name: d.name })),
        current_deal_id: null,
      });

      if (command.action === "create_role") {
        toast(command.explanation);
      } else if (
        command.action === "continue_sourcing" &&
        command.deal_id != null
      ) {
        const dealName =
          openDeals?.find((d) => d.id === command.deal_id)?.name ?? "that role";
        const result = await dataProvider.continueSourcingForDeal(
          command.deal_id,
        );
        queryClient.invalidateQueries({ queryKey: ["inbox_per_deal_signals"] });
        const filteredNote =
          result.filteredCount > 0
            ? `, ${result.filteredCount} filtered as not relevant`
            : "";
        toast.success(
          `${dealName}: found ${result.foundCount} candidate${result.foundCount === 1 ? "" : "s"}${filteredNote} — open the role to add to pipeline`,
        );
      } else if (
        command.action === "relax_criterion" &&
        command.criterion_id != null
      ) {
        await dataProvider.relaxLearnedCriterion(command.criterion_id);
        queryClient.invalidateQueries({ queryKey: ["inbox_per_deal_signals"] });
        toast.success("Criterion relaxed");
      } else if (
        command.action === "show_candidates" &&
        command.deal_id != null
      ) {
        navigate(`/roles/${command.deal_id}`);
      } else if (command.action === "show_roles") {
        navigate("/deals");
      } else {
        toast(command.explanation);
      }
    } catch {
      toast.error("Couldn't run that command");
    }
  };

  const handleParse = async () => {
    if (!jdText.trim()) {
      notify("Paste a job description first", { type: "warning" });
      return;
    }
    setParsing(true);
    try {
      const result = await dataProvider.parseJobDescription(jdText);
      // Sourcing-preference/exclusion fields are never part of the LLM
      // parse result (see the ParsedRoleBrief comment) -- default them
      // here so the review form always has a well-formed object to edit.
      setParsed({
        ...result,
        preference_tiers: result.preference_tiers ?? [],
        clarifying_questions: result.clarifying_questions ?? [],
        company_type: null,
        company_size_min: null,
        company_size_max: null,
        excluded_companies: [],
        exclusion_keywords: [],
        past_titles: [],
        past_companies: [],
      });
      setSkillsText(arrayToText(result.required_skills));
      setMustHaveText(arrayToText(result.must_have_keywords));
      setNiceToHaveText(arrayToText(result.nice_to_have_keywords));
      setExcludedCompaniesText("");
      setExclusionKeywordsText("");
      setPastTitlesText("");
      setPastCompaniesText("");
      setQuestionsDismissed(false);
      notify(
        "Job description parsed -- review the fields below before saving",
        { type: "success" },
      );
    } catch (error: any) {
      notify(error?.message || "Failed to parse job description", {
        type: "error",
      });
    } finally {
      setParsing(false);
    }
  };

  const updateParsed = (patch: Partial<ParsedRoleBrief>) => {
    setParsed((current) => (current ? { ...current, ...patch } : current));
  };

  const updateTier = (rank: number, patch: Partial<PreferenceTier>) => {
    setParsed((current) => {
      if (!current) return current;
      return {
        ...current,
        preference_tiers: current.preference_tiers.map((tier) =>
          tier.rank === rank ? { ...tier, ...patch } : tier,
        ),
      };
    });
  };

  const handleCreate = async () => {
    if (!parsed) return;
    setSaving(true);
    try {
      const created = await dataProvider.create("deals", {
        data: {
          name: parsed.title,
          // Agent H: "opportunity" was Atomic's stock sales-deal stage,
          // kept only so the record showed up in the Kanban view before a
          // recruiting-specific stage vocabulary existed. That vocabulary
          // now exists (see root/defaultConfiguration.ts) -- every role
          // starts life at the first pipeline stage, "sourcing".
          stage: "sourcing",
          jd_text: jdText,
          seniority: parsed.seniority,
          location: parsed.location,
          industry: parsed.industry,
          employment_type: parsed.employment_type,
          years_experience_min: parsed.years_experience_min,
          years_experience_max: parsed.years_experience_max,
          required_skills: textToArray(skillsText),
          must_have_keywords: textToArray(mustHaveText),
          nice_to_have_keywords: textToArray(niceToHaveText),
          company_type: parsed.company_type,
          company_size_min: parsed.company_size_min,
          company_size_max: parsed.company_size_max,
          excluded_companies: textToArray(excludedCompaniesText),
          exclusion_keywords: textToArray(exclusionKeywordsText),
          past_titles: textToArray(pastTitlesText),
          past_companies: textToArray(pastCompaniesText),
          preference_tiers:
            parsed.preference_tiers.length > 0 ? parsed.preference_tiers : null,
          clarifying_questions:
            parsed.clarifying_questions.length > 0
              ? parsed.clarifying_questions
              : null,
          clarifying_questions_dismissed: questionsDismissed,
          role_status: "new",
          contact_ids: [],
        },
      });
      notify("Role brief created", { type: "success" });
      // Role Workspace (2026-07-19): go straight into the new role's
      // workspace (sourcing/calibration + pipeline, all on one screen)
      // instead of the plain deals list -- matches Noon.ai's flow of
      // JD intake leading directly into Sourcing under the same role
      // context, rather than dropping the recruiter back at a list they'd
      // have to click through again to resume work on what they just
      // created.
      redirect(`/roles/${created.data.id}`);
    } catch (error: any) {
      notify(error?.message || "Failed to create the role brief", {
        type: "error",
      });
    } finally {
      setSaving(false);
    }
  };

  return (
    <AgentHShell
      context={shellContext}
      commandBar={{
        placeholder: "Tell Agent H what role you're hiring for",
        hint: 'Try: "create a role for a senior backend engineer" or paste a JD above.',
        slashActions: [],
        onSubmit: runFreeTextCommand,
      }}
    >
      <div className="flex flex-col gap-6 max-w-3xl mx-auto p-6 pb-8 overflow-y-auto flex-1 min-h-0">
        <div>
          <h1 className="text-2xl font-semibold">JD Intake</h1>
          <p className="text-muted-foreground text-sm">
            Paste a job description in plain language. It'll be parsed into a
            structured role brief you can review and edit before saving.
          </p>
        </div>

        <div className="flex flex-col gap-2">
          <Label htmlFor="jd-text">Job description</Label>
          <Textarea
            id="jd-text"
            value={jdText}
            onChange={(e) => setJdText(e.target.value)}
            rows={10}
            placeholder="Paste the full job description here..."
          />
          <div>
            <Button onClick={handleParse} disabled={parsing}>
              {parsing ? "Parsing..." : "Parse with AI"}
            </Button>
          </div>
        </div>

        {parsed && (
          <div className="ah-panel flex flex-col gap-4 p-6">
            <h2 className="text-lg font-medium">Review extracted fields</h2>

            <div className="flex flex-col gap-2">
              <Label htmlFor="title">Role title</Label>
              <Input
                id="title"
                value={parsed.title}
                onChange={(e) => updateParsed({ title: e.target.value })}
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="flex flex-col gap-2">
                <Label htmlFor="seniority">Seniority</Label>
                <select
                  id="seniority"
                  className="border border-input bg-background text-foreground rounded-md h-9 px-2"
                  value={parsed.seniority}
                  onChange={(e) => updateParsed({ seniority: e.target.value })}
                >
                  {SENIORITY_OPTIONS.map((option) => (
                    <option key={option} value={option}>
                      {option}
                    </option>
                  ))}
                </select>
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="employment_type">Employment type</Label>
                <select
                  id="employment_type"
                  className="border border-input bg-background text-foreground rounded-md h-9 px-2"
                  value={parsed.employment_type}
                  onChange={(e) =>
                    updateParsed({ employment_type: e.target.value })
                  }
                >
                  {EMPLOYMENT_TYPE_OPTIONS.map((option) => (
                    <option key={option} value={option}>
                      {option}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="flex flex-col gap-2">
                <Label htmlFor="location">Location</Label>
                <Input
                  id="location"
                  value={parsed.location}
                  onChange={(e) => updateParsed({ location: e.target.value })}
                />
              </div>
              <div className="flex flex-col gap-2">
                <Label htmlFor="industry">Industry</Label>
                <Input
                  id="industry"
                  value={parsed.industry ?? ""}
                  onChange={(e) => updateParsed({ industry: e.target.value })}
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="flex flex-col gap-2">
                <Label htmlFor="years_min">Years experience (min)</Label>
                <Input
                  id="years_min"
                  type="number"
                  value={parsed.years_experience_min ?? ""}
                  onChange={(e) =>
                    updateParsed({
                      years_experience_min: e.target.value
                        ? Number(e.target.value)
                        : null,
                    })
                  }
                />
              </div>
              <div className="flex flex-col gap-2">
                <Label htmlFor="years_max">Years experience (max)</Label>
                <Input
                  id="years_max"
                  type="number"
                  value={parsed.years_experience_max ?? ""}
                  onChange={(e) =>
                    updateParsed({
                      years_experience_max: e.target.value
                        ? Number(e.target.value)
                        : null,
                    })
                  }
                />
              </div>
            </div>

            <div className="flex flex-col gap-2">
              <Label htmlFor="skills">Required skills (comma-separated)</Label>
              <Input
                id="skills"
                value={skillsText}
                onChange={(e) => setSkillsText(e.target.value)}
              />
            </div>

            <div className="flex flex-col gap-2">
              <Label htmlFor="must-have">
                Must-have keywords (comma-separated)
              </Label>
              <Input
                id="must-have"
                value={mustHaveText}
                onChange={(e) => setMustHaveText(e.target.value)}
              />
            </div>

            <div className="flex flex-col gap-2">
              <Label htmlFor="nice-to-have">
                Nice-to-have keywords (comma-separated)
              </Label>
              <Input
                id="nice-to-have"
                value={niceToHaveText}
                onChange={(e) => setNiceToHaveText(e.target.value)}
              />
            </div>

            {parsed.clarifying_questions.length > 0 && !questionsDismissed && (
              <div className="flex flex-col gap-2 rounded-md border border-amber-200 bg-amber-50 p-3">
                <h3 className="text-sm font-medium text-amber-900">
                  Worth confirming before sourcing starts
                </h3>
                <ul className="list-disc pl-5 text-sm text-amber-900">
                  {parsed.clarifying_questions.map((question, i) => (
                    <li key={i}>{question}</li>
                  ))}
                </ul>
                <div>
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => setQuestionsDismissed(true)}
                  >
                    Dismiss
                  </Button>
                </div>
              </div>
            )}

            {parsed.preference_tiers.length > 0 && (
              <div className="flex flex-col gap-3 rounded-md border p-3">
                <div>
                  <h3 className="text-sm font-medium">
                    Ranked candidate preferences
                  </h3>
                  <p className="text-muted-foreground text-xs">
                    This JD described a primary-vs-fallback profile -- edit each
                    tier below, or clear a tier's keywords to drop it.
                  </p>
                </div>
                {[...parsed.preference_tiers]
                  .sort((a, b) => a.rank - b.rank)
                  .map((tier) => (
                    <div
                      key={tier.rank}
                      className="flex flex-col gap-2 rounded-md bg-muted/40 p-2"
                    >
                      <div className="flex items-center gap-2">
                        <span className="text-xs font-medium text-muted-foreground">
                          Tier {tier.rank}
                        </span>
                        <Input
                          aria-label={`Tier ${tier.rank} label`}
                          value={tier.label}
                          onChange={(e) =>
                            updateTier(tier.rank, { label: e.target.value })
                          }
                          className="h-8"
                        />
                      </div>
                      <Input
                        aria-label={`Tier ${tier.rank} keywords`}
                        placeholder="Keywords (comma-separated)"
                        value={arrayToText(tier.keywords)}
                        onChange={(e) =>
                          updateTier(tier.rank, {
                            keywords: textToArray(e.target.value),
                          })
                        }
                        className="h-8"
                      />
                      <Input
                        aria-label={`Tier ${tier.rank} condition`}
                        placeholder="Extra qualifying condition (optional)"
                        value={tier.condition ?? ""}
                        onChange={(e) =>
                          updateTier(tier.rank, {
                            condition: e.target.value || null,
                          })
                        }
                        className="h-8"
                      />
                    </div>
                  ))}
              </div>
            )}

            <div className="border-t pt-4 flex flex-col gap-4">
              <div>
                <h3 className="text-sm font-medium">
                  Sourcing preferences (optional)
                </h3>
                <p className="text-muted-foreground text-xs">
                  Which companies to pull candidates from -- not facts about
                  this role, just where to look.
                </p>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="flex flex-col gap-2">
                  <Label htmlFor="company_type">Company type</Label>
                  <Input
                    id="company_type"
                    placeholder="Startup, Product, Services..."
                    value={parsed.company_type ?? ""}
                    onChange={(e) =>
                      updateParsed({ company_type: e.target.value || null })
                    }
                  />
                </div>
                <div className="flex flex-col gap-2">
                  <Label>Company size (employees)</Label>
                  <div className="flex items-center gap-2">
                    <Input
                      type="number"
                      aria-label="Minimum company size"
                      placeholder="Min"
                      value={parsed.company_size_min ?? ""}
                      onChange={(e) =>
                        updateParsed({
                          company_size_min: e.target.value
                            ? Number(e.target.value)
                            : null,
                        })
                      }
                    />
                    <span className="text-muted-foreground text-sm">to</span>
                    <Input
                      type="number"
                      aria-label="Maximum company size"
                      placeholder="Max"
                      value={parsed.company_size_max ?? ""}
                      onChange={(e) =>
                        updateParsed({
                          company_size_max: e.target.value
                            ? Number(e.target.value)
                            : null,
                        })
                      }
                    />
                  </div>
                </div>
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="excluded-companies">
                  Excluded companies (comma-separated)
                </Label>
                <Input
                  id="excluded-companies"
                  placeholder="Companies to never surface -- competitors, already contacted, etc."
                  value={excludedCompaniesText}
                  onChange={(e) => setExcludedCompaniesText(e.target.value)}
                />
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="exclusion-keywords">
                  Exclusion keywords (comma-separated)
                </Label>
                <Input
                  id="exclusion-keywords"
                  placeholder="Terms that should rule a candidate out"
                  value={exclusionKeywordsText}
                  onChange={(e) => setExclusionKeywordsText(e.target.value)}
                />
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="past-titles">
                  Past titles (comma-separated, optional)
                </Label>
                <Input
                  id="past-titles"
                  placeholder="Boosts, doesn't require -- e.g. 'Founding Engineer' for someone who held that title earlier in their career"
                  value={pastTitlesText}
                  onChange={(e) => setPastTitlesText(e.target.value)}
                />
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="past-companies">
                  Past companies (comma-separated, optional)
                </Label>
                <Input
                  id="past-companies"
                  placeholder="Boosts, doesn't require -- e.g. 'Microsoft' for candidates who worked there at any point, not just currently"
                  value={pastCompaniesText}
                  onChange={(e) => setPastCompaniesText(e.target.value)}
                />
              </div>
            </div>

            <div>
              <Button onClick={handleCreate} disabled={saving}>
                {saving ? "Saving..." : "Create Role Brief"}
              </Button>
            </div>
          </div>
        )}
      </div>
    </AgentHShell>
  );
};

JdIntakePage.path = "/jd-intake";

// Agent H, Triage Inbox: aggregates "decisions that need Harsha" across
// every open role into one ranked feed, replacing the old Dashboard's
// static stat cards as the landing experience. There is no single
// materialized view for this yet (see dataProvider.getCandidatesForDeal's
// own comment on why plain multi-table reads are this codebase's default
// over a dedicated edge function for read-only aggregation) -- this hook
// follows that same convention: a handful of getList calls, fanned out
// client-side, capped to the first OPEN_DEAL_SCAN_LIMIT open roles so this
// stays cheap. If the number of open roles grows large enough for this to
// matter, the fan-out (criteria impact + candidate list per deal) is the
// first thing to move server-side.
import { useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { useDataProvider, useGetList } from "ra-core";

import type { CrmDataProvider } from "../providers/types";
import type { Deal } from "../types";

const OPEN_DEAL_SCAN_LIMIT = 6;
const CONFIDENT_MATCH_THRESHOLD = 0.85;
const OFFER_EXPIRY_WARNING_HOURS = 48;

export type InboxDecision = {
  id: string;
  priority: "high" | "med" | "low";
  title: string;
  subtitle: string;
  dealId: number | string | null;
  candidateId?: number | string;
  kind: "confident_matches" | "expiring_offer" | "resume_reply" | "low_pass_rate" | "stale_role";
  criterionId?: number | string;
};

const hoursUntil = (iso: string | null | undefined) => {
  if (!iso) return Infinity;
  return (new Date(iso).getTime() - Date.now()) / (1000 * 60 * 60);
};

const hoursSince = (iso: string | null | undefined) => {
  if (!iso) return Infinity;
  return (Date.now() - new Date(iso).getTime()) / (1000 * 60 * 60);
};

export const useInboxDecisions = () => {
  const dataProvider = useDataProvider<CrmDataProvider>();

  const { data: openDeals, isPending: dealsPending } = useGetList<Deal>("deals", {
    pagination: { page: 1, perPage: 20 },
    sort: { field: "updated_at", order: "DESC" },
    filter: { "archived_at@is": null },
  });

  const scanDeals = useMemo(
    () => (openDeals ?? []).slice(0, OPEN_DEAL_SCAN_LIMIT),
    [openDeals],
  );

  const { data: offers } = useGetList("offers", {
    pagination: { page: 1, perPage: 50 },
    sort: { field: "updated_at", order: "DESC" },
    filter: { status: "sent" },
  });

  const { data: recentReplies } = useGetList("candidates", {
    pagination: { page: 1, perPage: 20 },
    sort: { field: "resume_received_at", order: "DESC" },
    filter: { resume_status: "received" },
  });

  // Design decision (2026-07-22, superseding the prior emergency disable):
  // getRoleBriefCriteriaImpact used to be called here for every scanned open
  // deal (up to OPEN_DEAL_SCAN_LIMIT), automatically, on every single Inbox
  // load/refresh -- one live Coresignal search per learned criterion, with
  // no cap, just from opening the dashboard. Even now that
  // source-candidates-discovery's criteria_impact mode is capped and cached
  // server-side, Harsha's call was that criteria-impact numbers should stay
  // on-demand only (see SourceCandidatesPage's Control Panel, which is the
  // one remaining place recruiters see this data, behind an explicit
  // refresh click) -- not something that silently fires just from landing
  // on the Inbox. So this hook no longer fetches it at all: candidates are
  // still fetched per deal for the confident-matches signal below, but
  // criteria impact isn't. The "low_pass_rate" decision kind that used to
  // read from it is permanently gone from this feed (not just dormant) --
  // InboxDecision/InboxPage still know how to render/act on a
  // "low_pass_rate" item defensively, but this hook will never emit one.
  const { data: perDealData, isPending: perDealPending } = useQuery({
    queryKey: ["inbox_per_deal_signals", scanDeals.map((d) => d.id)],
    queryFn: async () => {
      return Promise.all(
        scanDeals.map(async (deal) => {
          const candidates = await dataProvider
            .getCandidatesForDeal(deal.id)
            .catch(() => []);
          return { deal, candidates };
        }),
      );
    },
    enabled: scanDeals.length > 0,
  });

  const decisions = useMemo<InboxDecision[]>(() => {
    const items: InboxDecision[] = [];

    for (const offer of offers ?? []) {
      const hrsLeft = hoursUntil((offer as any).expiry_date);
      if (hrsLeft <= OFFER_EXPIRY_WARNING_HOURS) {
        items.push({
          id: `offer-${offer.id}`,
          priority: "high",
          title: `Offer expires in ${Math.max(0, Math.round(hrsLeft))}h`,
          subtitle: "No reply yet — worth a follow-up",
          dealId: (offer as any).deal_id,
          kind: "expiring_offer",
        });
      }
    }

    for (const { deal, candidates } of perDealData ?? []) {
      const confident = candidates.filter(
        (c) => (c.dealCandidate.match_score ?? 0) >= CONFIDENT_MATCH_THRESHOLD,
      );
      if (confident.length > 0) {
        items.push({
          id: `confident-${deal.id}`,
          priority: "high",
          title: `${confident.length} confident match${confident.length === 1 ? "" : "es"} ready for ${deal.name}`,
          subtitle: "All above the 85% match bar",
          dealId: deal.id,
          kind: "confident_matches",
        });
      }
    }

    for (const candidate of recentReplies ?? []) {
      if (hoursSince((candidate as any).resume_received_at) <= 24) {
        items.push({
          id: `reply-${candidate.id}`,
          priority: "med",
          title: `${[candidate.first_name, candidate.last_name].filter(Boolean).join(" ") || "A candidate"} sent their resume`,
          subtitle: "Received in the last 24 hours — open their profile to review",
          dealId: null,
          candidateId: candidate.id,
          kind: "resume_reply",
        });
      }
    }

    // "low_pass_rate" items used to be generated here from an auto-fetched
    // criteriaImpact per deal -- removed alongside that auto-fetch above.
    // Recruiters still see per-rule reject counts, just on-demand via
    // SourceCandidatesPage's Control Panel, not as a proactive Inbox alert.

    const priorityRank = { high: 0, med: 1, low: 2 };
    return items.sort((a, b) => priorityRank[a.priority] - priorityRank[b.priority]);
  }, [offers, perDealData, recentReplies]);

  return {
    decisions,
    isPending: dealsPending || (scanDeals.length > 0 && perDealPending),
  };
};

// Agent H, Triage Inbox + Command Canvas: a shared "what has Agent H done"
// log for the command bar. Deliberately NOT backed by a new database table
// -- the existing activity_log resource is CRM-object-change-oriented
// (contact/company/deal created, etc, see ActivityLog.tsx) and extending it
// for agent-command events would need its own migration + triggers. This
// is a lighter first pass: a module-level store (survives navigating
// between InboxPage and CanvasPage within the same session, cleared on a
// full page reload) using useSyncExternalStore so both pages can render
// the same live log without prop drilling or a React context provider.
import { useSyncExternalStore } from "react";

export type ActivityEntry = {
  id: string;
  createdAt: number;
  // "info" is for a correctly-handled "I can't do that yet" reply (e.g. an
  // unrecognized command) -- distinct from "error" (something actually
  // failed) so the log doesn't show a red/alarming dot for normal traffic.
  status: "pending" | "success" | "error" | "info";
  summary: string;
};

const MAX_ENTRIES = 50;
let entries: ActivityEntry[] = [];
const listeners = new Set<() => void>();

const notify = () => listeners.forEach((listener) => listener());

// Adds a new entry and returns its id, so the caller can later update it
// in place (e.g. "Sourcing…" -> "Found 6, saved 6") via updateActivityEntry
// instead of leaving a separate "started"/"finished" pair in the log.
export const addActivityEntry = (summary: string, status: ActivityEntry["status"] = "pending"): string => {
  const id = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  entries = [{ id, createdAt: Date.now(), status, summary }, ...entries].slice(0, MAX_ENTRIES);
  notify();
  return id;
};

export const updateActivityEntry = (id: string, patch: Partial<Pick<ActivityEntry, "status" | "summary">>) => {
  entries = entries.map((entry) => (entry.id === id ? { ...entry, ...patch } : entry));
  notify();
};

const subscribe = (listener: () => void) => {
  listeners.add(listener);
  return () => listeners.delete(listener);
};

const getSnapshot = () => entries;

export const useAgentActivityLog = () => useSyncExternalStore(subscribe, getSnapshot);

// Agent H, Triage Inbox + Command Canvas redesign: the "?" cheat sheet.
// Same keyboard grammar applies in both InboxPage and CanvasPage, so this
// is one shared component rather than a per-view help panel.
type ShortcutRow = { label: string; keys: string };

const SHARED_SHORTCUTS: ShortcutRow[] = [
  { label: "Move focus", keys: "j / k" },
  { label: "Open focused item", keys: "↵" },
  { label: "Approve / add focused item", keys: "a" },
  { label: "Dismiss / reject focused item", keys: "x" },
  { label: "Quick actions", keys: "/" },
  { label: "Jump anywhere / global command", keys: "⌘K" },
  { label: "Back", keys: "esc" },
  { label: "This cheat sheet", keys: "?" },
];

export const ShortcutsModal = ({
  open,
  onClose,
  extraRows = [],
}: {
  open: boolean;
  onClose: () => void;
  extraRows?: ShortcutRow[];
}) => {
  if (!open) return null;
  const rows = [
    ...SHARED_SHORTCUTS.slice(0, 4),
    ...extraRows,
    ...SHARED_SHORTCUTS.slice(4),
  ];

  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed",
        inset: 0,
        background: "var(--ah-overlay)",
        backdropFilter: "blur(3px)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 60,
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        className="ah-glass-card"
        style={{
          width: 420,
          maxWidth: "90vw",
          background: "var(--ah-bg-1)",
          borderColor: "var(--ah-border-strong)",
          padding: 22,
        }}
      >
        <h2
          style={{
            fontFamily: "var(--ah-serif)",
            fontWeight: 400,
            fontSize: 18,
            margin: "0 0 14px",
          }}
        >
          Keyboard shortcuts
        </h2>
        {rows.map((row, i) => (
          <div
            key={row.label + i}
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              padding: "7px 0",
              fontSize: 13,
              color: "var(--ah-text-2)",
              borderTop: i === 0 ? "none" : "1px solid var(--ah-border)",
            }}
          >
            <span>{row.label}</span>
            <span className="ah-kbd">{row.keys}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

// Agent H, Triage Inbox: the new landing experience (wired as the app's
// `dashboard` in CRM.tsx), replacing the old stat-card Dashboard. Approved
// design direction (mockup v4-triage, after three earlier rounds informed
// by Noon.ai / Spott / Kharta research): a ranked decision queue instead of
// a metrics page, driven by one keyboard grammar shared with CanvasPage
// (j/k move, Enter opens, a approves, x dismisses, / for quick actions).
import { useEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router";
import { useQueryClient } from "@tanstack/react-query";
import { useDataProvider, useGetList } from "ra-core";
import { toast } from "sonner";

import type { CrmDataProvider } from "../providers/types";
import type { Deal } from "../types";
import { useInboxDecisions, type InboxDecision } from "./useInboxDecisions";
import { ShortcutsModal } from "./ShortcutsModal";
import { ActivityPanel } from "./ActivityPanel";
import { addActivityEntry, updateActivityEntry } from "./agentActivityStore";
import { SourcingSidebar } from "../sourcing/SourcingSidebar";
import { AgentHShell } from "../shell/AgentHShell";
import { useInboxShellContext } from "../shell/useShellContext";
import "./agent-h-theme.css";

const GROUP_LABEL: Record<InboxDecision["priority"], string> = {
  high: "Now",
  med: "Today",
  low: "This week",
};

const PRIORITY_DOT_COLOR: Record<InboxDecision["priority"], string> = {
  high: "var(--ah-danger)",
  med: "var(--ah-warn)",
  low: "var(--ah-good)",
};

export const InboxPage = () => {
  const navigate = useNavigate();
  const dataProvider = useDataProvider<CrmDataProvider>();
  const queryClient = useQueryClient();
  const { decisions, isPending } = useInboxDecisions();
  const { data: openDeals } = useGetList<Deal>("deals", {
    pagination: { page: 1, perPage: 20 },
    sort: { field: "updated_at", order: "DESC" },
    filter: { "archived_at@is": null },
  });

  const [dismissedIds, setDismissedIds] = useState<Set<string>>(new Set());
  const [focusIdx, setFocusIdx] = useState(0);
  const [shortcutsOpen, setShortcutsOpen] = useState(false);
  const [activityOpen, setActivityOpen] = useState(false);
  const [sourcingOpen, setSourcingOpen] = useState(false);
  const approveCountRef = useRef(0);
  const [showLearningPill, setShowLearningPill] = useState(false);

  const visible = useMemo(
    () => decisions.filter((d) => !dismissedIds.has(d.id)),
    [decisions, dismissedIds],
  );

  useEffect(() => {
    setFocusIdx((i) => Math.min(i, Math.max(0, visible.length - 1)));
  }, [visible.length]);

  const openDecision = (decision: InboxDecision) => {
    if (decision.dealId != null) {
      navigate(`/canvas/${decision.dealId}`);
    } else if (decision.candidateId != null) {
      navigate(`/candidates/${decision.candidateId}/show`);
    }
  };

  const pulseLearning = () => {
    approveCountRef.current += 1;
    if (approveCountRef.current >= 2) {
      setShowLearningPill(true);
      setTimeout(() => setShowLearningPill(false), 4000);
    }
  };

  const approveDecision = async (decision: InboxDecision) => {
    if (decision.kind === "low_pass_rate" && decision.criterionId != null) {
      await dataProvider.relaxLearnedCriterion(decision.criterionId);
      queryClient.invalidateQueries({ queryKey: ["inbox_per_deal_signals"] });
      toast.success("Criterion relaxed — re-scanning that role's pool");
      setDismissedIds((prev) => new Set(prev).add(decision.id));
    } else {
      openDecision(decision);
    }
    pulseLearning();
  };

  const runFreeTextCommand = async (commandText: string) => {
    const logId = addActivityEntry(`"${commandText}"`, "pending");
    try {
      const parsed = await dataProvider.parseAgentCommand(commandText, {
        view: "inbox",
        open_deals: (openDeals ?? []).map((d) => ({ id: d.id, name: d.name })),
        current_deal_id: null,
      });

      if (parsed.action === "create_role") {
        updateActivityEntry(logId, {
          status: "success",
          summary: parsed.explanation,
        });
        navigate("/");
      } else if (
        parsed.action === "continue_sourcing" &&
        parsed.deal_id != null
      ) {
        const dealName =
          openDeals?.find((d) => d.id === parsed.deal_id)?.name ?? "that role";
        updateActivityEntry(logId, {
          summary: `Sourcing more candidates for ${dealName}…`,
        });
        const result = await dataProvider.continueSourcingForDeal(
          parsed.deal_id,
        );
        const filteredNote =
          result.filteredCount > 0
            ? `, ${result.filteredCount} filtered as not relevant`
            : "";
        updateActivityEntry(logId, {
          status: "success",
          summary: `${dealName}: found ${result.foundCount} candidates${filteredNote}`,
        });
        toast.success(
          `Found ${result.foundCount} candidate${result.foundCount === 1 ? "" : "s"} for ${dealName}${filteredNote} — open the role to add to pipeline`,
        );
      } else if (
        parsed.action === "relax_criterion" &&
        parsed.criterion_id != null
      ) {
        await dataProvider.relaxLearnedCriterion(parsed.criterion_id);
        queryClient.invalidateQueries({ queryKey: ["inbox_per_deal_signals"] });
        updateActivityEntry(logId, {
          status: "success",
          summary: parsed.explanation,
        });
        toast.success("Criterion relaxed");
      } else if (
        parsed.action === "show_candidates" &&
        parsed.deal_id != null
      ) {
        updateActivityEntry(logId, {
          status: "success",
          summary: parsed.explanation,
        });
        navigate(`/canvas/${parsed.deal_id}`);
      } else if (parsed.action === "show_roles") {
        updateActivityEntry(logId, {
          status: "success",
          summary: parsed.explanation,
        });
        navigate("/deals");
      } else {
        updateActivityEntry(logId, {
          status: "info",
          summary: parsed.explanation,
        });
        toast(parsed.explanation);
      }
    } catch (error) {
      updateActivityEntry(logId, {
        status: "error",
        summary:
          error instanceof Error
            ? error.message
            : "Something went wrong running that command.",
      });
      toast.error("Couldn't run that command");
    }
  };

  const dismissDecision = (decision: InboxDecision) => {
    setDismissedIds((prev) => new Set(prev).add(decision.id));
    toast("Dismissed", {
      action: {
        label: "Undo",
        onClick: () =>
          setDismissedIds((prev) => {
            const next = new Set(prev);
            next.delete(decision.id);
            return next;
          }),
      },
    });
  };

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      const typing = document.activeElement?.tagName === "INPUT";
      if (typing) return;
      if (e.key === "?") {
        setShortcutsOpen((v) => !v);
        return;
      }
      if (e.key === "Escape") {
        setShortcutsOpen(false);
        return;
      }
      if (shortcutsOpen) return;
      if (visible.length === 0) return;

      if (e.key === "j")
        setFocusIdx((i) => Math.min(visible.length - 1, i + 1));
      if (e.key === "k") setFocusIdx((i) => Math.max(0, i - 1));
      if (e.key === "Enter") openDecision(visible[focusIdx]);
      if (e.key === "a") approveDecision(visible[focusIdx]);
      if (e.key === "x") dismissDecision(visible[focusIdx]);
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [visible, focusIdx, shortcutsOpen]);

  const groups: InboxDecision["priority"][] = ["high", "med", "low"];
  const shellContext = useInboxShellContext({
    pendingDecisionCount: visible.length,
    isPending,
  });

  return (
    <AgentHShell
      context={shellContext}
      commandBar={{
        placeholder: "Tell Agent H what you need",
        hint: "Try: “start a new role for a backend engineer” or “find more candidates for the designer role”.",
        slashActions: [
          { cmd: "/open", label: "Open the focused decision" },
          { cmd: "/relax", label: "Relax a criterion on a role" },
        ],
        onSubmit: runFreeTextCommand,
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          flex: 1,
          minHeight: 0,
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 10,
            padding: "14px 22px",
            borderBottom: "1px solid var(--ah-border)",
            flexShrink: 0,
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 8,
              fontWeight: 700,
              fontSize: 14,
            }}
          >
            <div
              style={{
                width: 24,
                height: 24,
                borderRadius: 7,
                background: "var(--ah-accent-grad)",
              }}
            />
            Agent H
          </div>
          {showLearningPill && (
            <div
              className="ah-chip"
              style={{
                background: "var(--ah-accent-soft)",
                borderColor: "var(--ah-accent-soft-border)",
                color: "var(--ah-accent-text)",
              }}
            >
              <div className="ah-pulse-dot" />
              Agent H is adapting to your feedback
            </div>
          )}
          <div style={{ marginLeft: "auto", display: "flex", gap: 8 }}>
            {/* Recruiter-persona redesign (2026-07-24): starting a new role
              is the single most common thing a recruiter does here, so it
              gets a real, always-visible button -- not something that only
              works if you type the right words into the command bar (see
              /jd-intake's own header comment: it was previously a fully-
              built page with no link pointing to it anywhere in the UI). */}
            <button
              className="ah-btn-primary"
              onClick={() => navigate("/")}
              style={{
                height: 32,
                padding: "0 14px",
                display: "flex",
                alignItems: "center",
                gap: 6,
                fontSize: 12.5,
              }}
            >
              + New role
            </button>
            <button
              className="ah-btn-ghost"
              onClick={() => setSourcingOpen((v) => !v)}
              style={{
                height: 32,
                padding: "0 14px",
                display: "flex",
                alignItems: "center",
                gap: 6,
                fontSize: 12.5,
                borderColor: sourcingOpen ? "var(--ah-accent)" : undefined,
                color: sourcingOpen ? "var(--ah-accent)" : undefined,
              }}
            >
              &#10024; Sourcing
            </button>
            <button
              className="ah-btn-ghost"
              onClick={() => setActivityOpen((v) => !v)}
              style={{
                width: 32,
                height: 32,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                borderColor: activityOpen ? "var(--ah-accent)" : undefined,
                color: activityOpen ? "var(--ah-accent)" : undefined,
              }}
              aria-label="Agent H activity"
            >
              &#128337;
            </button>
            <button
              className="ah-btn-ghost"
              onClick={() => setShortcutsOpen(true)}
              style={{
                width: 32,
                height: 32,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
              aria-label="Keyboard shortcuts"
            >
              ?
            </button>
          </div>
        </div>

        <ActivityPanel
          open={activityOpen}
          onClose={() => setActivityOpen(false)}
        />

        <div style={{ flex: 1, overflowY: "auto", padding: "20px 22px 24px" }}>
          <h1
            style={{
              fontFamily: "var(--ah-serif)",
              fontWeight: 400,
              fontSize: 24,
              margin: "0 0 4px",
            }}
          >
            Good day, Harsha
          </h1>
          <div
            style={{
              fontSize: 13,
              color: "var(--ah-text-2)",
              marginBottom: 18,
            }}
          >
            {isPending
              ? "Checking on your roles…"
              : visible.length === 0
                ? "Nothing needs you right now."
                : `${visible.length} decision${visible.length === 1 ? "" : "s"} need you · `}
            {!isPending && visible.length > 0 && (
              <>
                use <span className="ah-kbd">j</span>{" "}
                <span className="ah-kbd">k</span> to move,{" "}
                <span className="ah-kbd">↵</span> to open,{" "}
                <span className="ah-kbd">a</span> to approve,{" "}
                <span className="ah-kbd">x</span> to dismiss
              </>
            )}
          </div>

          {groups.map((group) => {
            const rows = visible.filter((d) => d.priority === group);
            if (rows.length === 0) return null;
            return (
              <div key={group}>
                <div
                  style={{
                    fontSize: 11,
                    color: "var(--ah-text-3)",
                    textTransform: "uppercase",
                    letterSpacing: ".05em",
                    margin: "18px 0 8px",
                  }}
                >
                  {GROUP_LABEL[group]}
                </div>
                {rows.map((decision) => {
                  const idx = visible.indexOf(decision);
                  const focused = idx === focusIdx;
                  return (
                    <div
                      key={decision.id}
                      onClick={() => openDecision(decision)}
                      className="ah-glass-card"
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 14,
                        padding: "13px 14px",
                        marginBottom: 7,
                        cursor: "pointer",
                        borderColor: focused ? "var(--ah-accent)" : undefined,
                        background: focused
                          ? "var(--ah-accent-row)"
                          : undefined,
                        boxShadow: focused
                          ? "var(--ah-accent-focus-ring)"
                          : undefined,
                      }}
                    >
                      <div
                        style={{
                          width: 6,
                          height: 6,
                          borderRadius: "50%",
                          flexShrink: 0,
                          background: PRIORITY_DOT_COLOR[decision.priority],
                        }}
                      />
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontSize: 13.5, fontWeight: 600 }}>
                          {decision.title}
                        </div>
                        <div
                          style={{
                            fontSize: 12,
                            color: "var(--ah-text-3)",
                            marginTop: 2,
                          }}
                        >
                          {decision.subtitle}
                        </div>
                      </div>
                      {focused && (
                        <div style={{ display: "flex", gap: 5, flexShrink: 0 }}>
                          <span className="ah-kbd">A</span>
                          <span className="ah-kbd">↵</span>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            );
          })}
        </div>

        <ShortcutsModal
          open={shortcutsOpen}
          onClose={() => setShortcutsOpen(false)}
        />

        <SourcingSidebar
          open={sourcingOpen}
          onClose={() => setSourcingOpen(false)}
          openDeals={openDeals ?? []}
        />
      </div>
    </AgentHShell>
  );
};

// Agent H, Triage Inbox + Command Canvas redesign: the one persistent
// command surface shared by InboxPage and CanvasPage. Free text goes to
// onSubmit as-is (the caller decides what "tell Agent H to do X" means in
// its own context); typing "/" opens a scaffolded quick-action menu so the
// bar is never pure guesswork, matching the approved v4 mockup's slash-menu.
// Cmd/Ctrl+K focuses it from anywhere on the page.
import { useEffect, useRef, useState } from "react";

export type SlashAction = {
  cmd: string;
  label: string;
};

type CommandBarProps = {
  placeholder: string;
  hint: string;
  slashActions: SlashAction[];
  onSubmit: (value: string) => void;
};

export const CommandBar = ({
  placeholder,
  hint,
  slashActions,
  onSubmit,
}: CommandBarProps) => {
  const [value, setValue] = useState("");
  const [showSlashMenu, setShowSlashMenu] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        inputRef.current?.focus();
      }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, []);

  const runCommand = () => {
    const trimmed = value.trim();
    if (!trimmed) return;
    onSubmit(trimmed);
    setValue("");
    setShowSlashMenu(false);
  };

  return (
    <div
      style={{ padding: "12px 22px 16px", flexShrink: 0, position: "relative" }}
    >
      {showSlashMenu && slashActions.length > 0 && (
        <div
          className="ah-glass-card"
          style={{
            position: "absolute",
            bottom: "calc(100% + 8px)",
            left: 22,
            right: 22,
            maxWidth: 760,
            margin: "0 auto",
            overflow: "hidden",
            background: "var(--ah-bg-1)",
            borderColor: "var(--ah-border-strong)",
            boxShadow: "var(--ah-shadow-lg)",
          }}
        >
          {slashActions.map((action) => (
            <div
              key={action.cmd}
              onClick={() => {
                setValue(action.cmd + " ");
                setShowSlashMenu(false);
                inputRef.current?.focus();
              }}
              style={{
                padding: "9px 14px",
                fontSize: 12.5,
                color: "var(--ah-text-2)",
                cursor: "pointer",
                display: "flex",
                alignItems: "center",
                gap: 10,
              }}
              onMouseEnter={(e) =>
                (e.currentTarget.style.background = "var(--ah-accent-soft)")
              }
              onMouseLeave={(e) =>
                (e.currentTarget.style.background = "transparent")
              }
            >
              <span
                style={{
                  fontFamily: "var(--ah-mono)",
                  fontSize: 10.5,
                  color: "var(--ah-accent-2)",
                  flexShrink: 0,
                  width: 90,
                }}
              >
                {action.cmd}
              </span>
              {action.label}
            </div>
          ))}
        </div>
      )}

      <div
        className="ah-glass-card"
        style={{
          maxWidth: 760,
          margin: "0 auto",
          display: "flex",
          alignItems: "center",
          gap: 10,
          background: "var(--ah-bg-1)",
          borderColor: "var(--ah-border-strong)",
          padding: "9px 9px 9px 16px",
          boxShadow: "var(--ah-shadow-md)",
        }}
      >
        <span style={{ color: "var(--ah-text-3)", fontSize: 13 }}>
          &#10024;
        </span>
        <input
          ref={inputRef}
          type="text"
          value={value}
          placeholder={placeholder}
          onChange={(e) => {
            setValue(e.target.value);
            setShowSlashMenu(e.target.value.startsWith("/"));
          }}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              runCommand();
            }
            if (e.key === "Escape") {
              setShowSlashMenu(false);
              inputRef.current?.blur();
            }
          }}
          style={{
            flex: 1,
            background: "none",
            border: "none",
            outline: "none",
            color: "var(--ah-text-1)",
            fontSize: 14,
          }}
        />
        <span className="ah-kbd">&#8984;K</span>
        <button
          className="ah-btn-primary"
          onClick={runCommand}
          style={{
            width: 28,
            height: 28,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 12,
          }}
          aria-label="Send"
        >
          &#8593;
        </button>
      </div>
      <div
        style={{
          maxWidth: 760,
          margin: "7px auto 0",
          fontSize: 10.5,
          color: "var(--ah-text-3)",
          textAlign: "center",
        }}
      >
        {hint}
      </div>
    </div>
  );
};

// Agent H, Triage Inbox + Command Canvas: slide-out panel showing what
// Agent H has actually done in this session -- every command bar action,
// pending/success/error, newest first. Answers "what's loaded so far, what
// happened" directly at the point of use instead of a separate page you'd
// have to remember to check.
import { useAgentActivityLog } from "./agentActivityStore";

const STATUS_COLOR: Record<string, string> = {
  pending: "var(--ah-warn)",
  success: "var(--ah-good)",
  error: "var(--ah-danger)",
  info: "var(--ah-text-3)",
};

const timeAgo = (ts: number) => {
  const seconds = Math.max(0, Math.round((Date.now() - ts) / 1000));
  if (seconds < 60) return "just now";
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return `${minutes}m ago`;
  return `${Math.round(minutes / 60)}h ago`;
};

export const ActivityPanel = ({
  open,
  onClose,
}: {
  open: boolean;
  onClose: () => void;
}) => {
  const entries = useAgentActivityLog();
  if (!open) return null;

  return (
    <div
      style={{
        position: "absolute",
        top: 60,
